    // ---- fleet-manager changelog parse guard ----
    // js/changelog.js is synced by manager.polecat.live, which does NOT run the file — it
    // text-extracts the CHANGELOG array and normalizes single-quoted JS to JSON (see its
    // js/ingest.js). A raw apostrophe in a double-quoted string, a `//`, or JSON drift breaks
    // it. This guard runs the manager's EXACT parser so the loop catches a breaking entry
    // before committing (the suite gates every commit) — do NOT weaken it.
    console.log("\n• fleet changelog parse guard");
    (function () {
      // verbatim copy of manager.polecat.live/js/ingest.js extract+normalize
      function extractArrayLiteral(src, varName) {
        const m = src.match(new RegExp(varName + "\\s*=\\s*\\["));
        if (!m) return null;
        const start = m.index + m[0].length - 1;
        let depth = 0, inStr = null, esc = false;
        for (let i = start; i < src.length; i++) {
          const c = src[i];
          if (inStr) { if (esc) esc = false; else if (c === "\\") esc = true; else if (c === inStr) inStr = null; continue; }
          if (c === '"' || c === "'" || c === "`") { inStr = c; continue; }
          if (c === "[") depth++; else if (c === "]") { depth--; if (depth === 0) return src.slice(start, i + 1); }
        }
        return null;
      }
      // Byte-for-byte port of the manager's char-walker. The ORDER is load-bearing:
      // it requotes strings FIRST, THEN runs the bare-key regex over the whole result,
      // so a string value containing `{ident:` gets unescaped quotes injected and the
      // file fails to parse. An earlier "verbatim" copy here applied the same regexes
      // in the opposite order, which silently re-escaped that break and passed files
      // the real manager rejected — the exact reason a broken changelog shipped.
      function jsLiteralToJSON(lit) {
        let out = "", i = 0; const n = lit.length;
        const esc = (ch) => ch === '"' ? '\\"' : ch;
        while (i < n) {
          const c = lit[i];
          if (c === "/" && lit[i + 1] === "/") { while (i < n && lit[i] !== "\n") i++; continue; }
          if (c === "'" || c === '"') {
            const quote = c; i++; let s = '"';
            while (i < n) {
              const ch = lit[i];
              if (ch === "\\" && i + 1 < n) {
                const next = lit[i + 1];
                if (next === "\\") s += "\\\\"; else if ("ntrbf".includes(next)) s += "\\" + next; else s += esc(next);
                i += 2; continue;
              }
              if (ch === quote) { i++; break; }
              s += esc(ch); i++;
            }
            out += s + '"'; continue;
          }
          out += c; i++;
        }
        out = out.replace(/,\s*([}\]])/g, "$1").replace(/([{,]\s*)([A-Za-z_$][A-Za-z0-9_$]*)\s*:/g, '$1"$2":');
        return JSON.parse(out);
      }
      const clSrc = fs.readFileSync(path.join(ROOT, "js/changelog.js"), "utf8");
      let parsed = null, perr = null;
      try { parsed = jsLiteralToJSON(extractArrayLiteral(clSrc, "CHANGELOG")); } catch (e) { perr = e.message; }
      ok("changelog parses with the fleet manager's exact parser (relay literal style)", Array.isArray(parsed) && parsed.length > 0, perr || "");
      // and it must yield EVERY entry (a bad entry can truncate silently mid-array)
      const w = {}; new Function("window", clSrc.replace(/export\s+const/g, "const"))(w);
      const actual = (w.STUDIO_CHANGELOG || []).length;
      ok("manager parse yields ALL changelog entries (no silent truncation)", parsed && parsed.length === actual, (parsed ? parsed.length : 0) + " parsed vs " + actual + " actual");
    })();

    // ---- vendored Polecat Shell integrity guard ----
    // vendor/polecat-shell/ is a READ-ONLY verbatim copy of kevinrhaas/polecat-platform
    // lib/ (fleet sweeps drift-check it remotely; this is the same check locally, so an
    // accidental edit fails the suite before it ever ships). Every file listed in
    // MANIFEST.json must hash-match, and no unlisted stray files may appear.
    console.log("\n• vendored polecat-shell integrity (MANIFEST sha256)");
    (function () {
      const crypto = require("crypto");
      const VDIR = path.join(ROOT, "vendor/polecat-shell");
      const manifest = JSON.parse(fs.readFileSync(path.join(VDIR, "MANIFEST.json"), "utf8"));
      const listed = Object.keys(manifest.files);
      let drifted = [];
      for (const f of listed) {
        const h = crypto.createHash("sha256").update(fs.readFileSync(path.join(VDIR, f))).digest("hex");
        if (h !== manifest.files[f]) drifted.push(f);
      }
      ok("every vendored shell file sha256-matches MANIFEST.json (v" + manifest.version + ", " + listed.length + " files)",
        listed.length > 0 && drifted.length === 0, drifted.join(", "));
      const onDisk = [];
      (function walk(dir, rel) {
        for (const name of fs.readdirSync(dir)) {
          const fp = path.join(dir, name), r = rel ? rel + "/" + name : name;
          if (fs.statSync(fp).isDirectory()) walk(fp, r);
          else if (name !== "MANIFEST.json") onDisk.push(r);
        }
      })(VDIR, "");
      const strays = onDisk.filter((f) => listed.indexOf(f) < 0);
      ok("no stray files under vendor/polecat-shell/ beyond the MANIFEST", strays.length === 0, strays.join(", "));
      const version = fs.readFileSync(path.join(VDIR, "VERSION"), "utf8").trim();
      ok("vendored VERSION file agrees with MANIFEST.json version", version === manifest.version, version + " vs " + manifest.version);
    })();

    // ---- Polecat Shell token bridge (theming) ----
    // tokens.css loads BEFORE studio.css; the Studio's own variable blocks must win
    // every shared name, the bridge must express the shell's canonical tokens in
    // Studio values, and data-palette must mirror data-app-theme (historical
    // studio-theme / studio-app-theme storage keys unchanged).
    console.log("\n• polecat-shell token bridge");
    const shellBridge = await page.evaluate(function () {
      var de = document.documentElement;
      var cs = getComputedStyle(de);
      var links = Array.prototype.map.call(document.querySelectorAll('link[rel="stylesheet"]'), function (l) { return l.getAttribute("href"); });
      return {
        palette: de.getAttribute("data-palette"),
        appTheme: de.getAttribute("data-app-theme"),
        tokensIdx: links.indexOf("vendor/polecat-shell/tokens.css"),
        studioIdx: links.indexOf("app/studio.css"),
        surface: cs.getPropertyValue("--surface").trim(),
        pane: cs.getPropertyValue("--pane").trim(),
        text: cs.getPropertyValue("--text").trim(),
        ink: cs.getPropertyValue("--ink").trim(),
        brand: cs.getPropertyValue("--brand").trim(),
        bg: cs.getPropertyValue("--bg").trim()
      };
    });
    ok("tokens.css is linked before studio.css (Studio wins shared names)",
      shellBridge.tokensIdx >= 0 && shellBridge.studioIdx > shellBridge.tokensIdx, JSON.stringify({ tokensIdx: shellBridge.tokensIdx, studioIdx: shellBridge.studioIdx }));
    ok("data-palette mirrors data-app-theme on <html>",
      !!shellBridge.palette && shellBridge.palette === shellBridge.appTheme, shellBridge.palette + " vs " + shellBridge.appTheme);
    // Computed custom properties substitute var() (verified in Chromium), so the
    // bridge names must RESOLVE to the exact same values as the Studio's own vars.
    ok("bridge maps shell canonical tokens onto Studio values (--surface→--pane, --text→--ink)",
      shellBridge.surface !== "" && shellBridge.surface === shellBridge.pane &&
      shellBridge.text === shellBridge.ink,
      JSON.stringify(shellBridge));
    // --brand converged onto the shell's own canonical name in the 2026-07-18
    // studio.css fold (formerly bridged from a separate --pentaho variable) —
    // the default Polecat theme's accent is the concrete regression check now
    // (same "default polecat light theme" context as the --bg check below).
    ok("--brand (default Polecat theme) resolves to the Studio's own chrome accent",
      shellBridge.brand.toUpperCase() === "#C1602C", shellBridge.brand);
    // Regression: the Studio's own look is untouched — its --bg (not the shell's
    // #0a0a0f dark base / #f4f4fb light) must still win in the default polecat light theme.
    ok("studio.css still wins the shared --bg token (Polecat warm cream, not the shell base)",
      shellBridge.bg.toUpperCase() === "#F7EEDF", shellBridge.bg);
    const shellBridgeToggle = await page.evaluate(function () {
      window.__studioAppTheme.set("modern");
      var de = document.documentElement;
      var after = { palette: de.getAttribute("data-palette"), appTheme: de.getAttribute("data-app-theme"), stored: localStorage.getItem("studio-app-theme") };
      window.__studioAppTheme.set("polecat");
      return after;
    });
    ok("switching the app theme re-stamps data-palette and keeps the historical storage key",
      shellBridgeToggle.palette === "modern" && shellBridgeToggle.appTheme === "modern" && shellBridgeToggle.stored === "modern",
      JSON.stringify(shellBridgeToggle));

    // LF10: the default dashboard theme (new dashboards/widgets, Explore's preview) now
    // follows whichever app Color theme is active whenever no EXPLICIT Settings default is
    // stored — it no longer always falls back to a hardcoded "polecat".
    const lf10DefaultFollowsAppTheme = await page.evaluate(function () {
      localStorage.removeItem("studio-default-dashboardtheme"); // explicit override unset
      var out = {};
      window.__studioAppTheme.set("modern"); out.modern = window.__studioDefaultDashboardTheme();
      window.__studioAppTheme.set("classic"); out.classic = window.__studioDefaultDashboardTheme();
      window.__studioAppTheme.set("polecat"); out.polecat = window.__studioDefaultDashboardTheme();
      window.__studioAppTheme.set("conservation"); out.conservation = window.__studioDefaultDashboardTheme();
      // #113: the three parity themes map 1:1 onto their dashboard-theme twins.
      window.__studioAppTheme.set("high-contrast"); out.highContrast = window.__studioDefaultDashboardTheme();
      window.__studioAppTheme.set("editorial"); out.editorial = window.__studioDefaultDashboardTheme();
      window.__studioAppTheme.set("neon"); out.neon = window.__studioDefaultDashboardTheme();
      window.__studioAppTheme.set("classic"); // restore for subsequent tests
      return out;
    });
    ok("LF10 / #113: with no explicit Settings default, defaultDashboardTheme() tracks the app Color theme (modern→fleet-modern, classic→'', polecat→polecat, conservation→conservation, and the 3 parity themes 1:1)",
      lf10DefaultFollowsAppTheme.modern === "fleet-modern" && lf10DefaultFollowsAppTheme.classic === "" && lf10DefaultFollowsAppTheme.polecat === "polecat" &&
      lf10DefaultFollowsAppTheme.conservation === "conservation" &&
      lf10DefaultFollowsAppTheme.highContrast === "high-contrast" && lf10DefaultFollowsAppTheme.editorial === "editorial" && lf10DefaultFollowsAppTheme.neon === "neon",
      JSON.stringify(lf10DefaultFollowsAppTheme));

    // ---- fleet app-switcher (vendored appSwitcher via app/fleet.js) ----
