      var paged = await rs.queryData(cfg, { kind: "sql", sql: "SELECT PAGED" });
      var noCreds = await rs.testData({ region: "us-east-1" });
      return { test: test, query: query, failed: failed, empty: empty, paged: paged, noCreds: noCreds };
