    ok("RS: testConnection succeeds against the mock Data API (ExecuteStatement -> poll -> GetStatementResult)",
      rsRun.test.ok === true, JSON.stringify(rsRun.test));
    ok("RS: queryData returns the mock's two rows with correctly-decoded string/long fields",
      rsRun.query.columns.join(",") === "region,total" && rsRun.query.rows.length === 2 &&
      rsRun.query.rows[0][0] === "EMEA" && rsRun.query.rows[0][1] === 120, JSON.stringify(rsRun.query));
    ok("RS: a FAILED statement surfaces the mock's error message in-band, not a throw",
      !!rsRun.failed.error && /syntax error/.test(rsRun.failed.error), JSON.stringify(rsRun.failed));
    ok("RS: HasResultSet:false (e.g. a DDL statement) resolves an empty result, not an error",
      !rsRun.empty.error && rsRun.empty.rows.length === 0, JSON.stringify(rsRun.empty));
    ok("RS: GetStatementResult pagination (NextToken) is followed to completion across pages",
      rsRun.paged.rows.length === 2 && rsRun.paged.rows[0][0] === "EMEA" && rsRun.paged.rows[1][0] === "AMER", JSON.stringify(rsRun.paged));
    ok("RS: missing access key/secret is an honest in-band refusal, not a throw",
      rsRun.noCreds.ok === false && !!rsRun.noCreds.error, JSON.stringify(rsRun.noCreds));

    const rsIcon = await page.evaluate(function () {
      return {
        path: Studio._iconPaths.redshift,
        distinctFromSnowflake: Studio._iconPaths.redshift !== Studio._iconPaths.snowflake,
        distinctFromDatabricks: Studio._iconPaths.redshift !== Studio._iconPaths.databricks,
        distinctFromBigquery: Studio._iconPaths.redshift !== Studio._iconPaths.bigquery,
        distinctFromDb: Studio._iconPaths.redshift !== Studio._iconPaths.db
      };
    });
    ok("RS: redshift icon exists and is distinct from the other connector marks",
      !!rsIcon.path && rsIcon.distinctFromSnowflake && rsIcon.distinctFromDatabricks && rsIcon.distinctFromBigquery && rsIcon.distinctFromDb,
      JSON.stringify(rsIcon));

    // ---- Schema browser (post-overhaul backlog item 5, "dataset delight" — the
    // schema-browser half): listSchema() runs an ANSI information_schema.columns
    // SELECT through the SAME engine.query() bridge queryData uses, grouped into
    // a table→columns tree. Wired for Snowflake/Databricks/Redshift; the mock
    // Data API above now answers an information_schema query with two tables.
    console.log("\n• Schema browser (post-overhaul item 5)");
    const rsSchema = await page.evaluate(async function (port) {
      var rs = Studio.sourceById("redshift");
      var cfg = { region: "us-east-1", accessKeyId: "AKIDEXAMPLE", secretAccessKey: "secret", database: "dev",
        workgroupName: "default", endpoint: "http://localhost:" + port + "/__redshift-data" };
      var ok1 = await rs.listSchema(cfg);
      var bad = await rs.listSchema({ region: "us-east-1" }); // missing creds -> in-band error
      return { ok1: ok1, bad: bad };
    }, PORT);
    ok("RS: listSchema groups the mock's information_schema.columns rows into a table→columns tree",
      rsSchema.ok1.tables.length === 2 &&
      rsSchema.ok1.tables[0].name === "customers" && rsSchema.ok1.tables[0].schema === "public" && rsSchema.ok1.tables[0].columns.length === 2 &&
      rsSchema.ok1.tables[1].name === "orders" && rsSchema.ok1.tables[1].columns.length === 3 &&
      rsSchema.ok1.tables[1].columns[0].name === "id" && rsSchema.ok1.tables[1].columns[0].type === "integer",
      JSON.stringify(rsSchema.ok1));
    ok("RS: listSchema surfaces a missing-credentials failure in-band, not a throw",
      rsSchema.bad.tables.length === 0 && !!rsSchema.bad.error, JSON.stringify(rsSchema.bad));

    // Snowflake/Databricks have no configurable endpoint field (unlike Redshift),
    // so — same reason the rest of this suite's Snowflake/Databricks checks do —
    // their query() façade is monkey-patched in-page rather than hitting a mock
    // HTTP server, while still exercising the REAL listSchema()/SQL-building code.
    const sfSchema = await page.evaluate(async function () {
      var sf = Studio.sourceById("snowflake");
      var orig = Studio.Snowflake.query, captured = [];
      Studio.Snowflake.query = function (cfg, sql) {
        captured.push(sql);
        return Promise.resolve({
          cols: ["TABLE_SCHEMA", "TABLE_NAME", "COLUMN_NAME", "DATA_TYPE"],
          rows: [["PUBLIC", "ORDERS", "ID", "NUMBER"], ["PUBLIC", "ORDERS", "REGION", "VARCHAR"], ["PUBLIC", "CUSTOMERS", "NAME", "VARCHAR"]]
        });
      };
      var qualified = await sf.listSchema({ account: "xy", token: "t", database: "ANALYTICS" });
      var unqualified = await sf.listSchema({ account: "xy", token: "t" });
      Studio.Snowflake.query = orig;
      return { qualified: qualified, unqualified: unqualified, captured: captured };
    });
    ok("SF: listSchema quotes the database when set and groups uppercase-header rows case-insensitively",
      /^SELECT table_schema, table_name, column_name, data_type FROM "ANALYTICS"\.information_schema\.columns ORDER BY/.test(sfSchema.captured[0]) &&
      sfSchema.qualified.tables.length === 2 && sfSchema.qualified.tables[0].name === "ORDERS" && sfSchema.qualified.tables[0].columns.length === 2,
      JSON.stringify(sfSchema.captured[0]) + " / " + JSON.stringify(sfSchema.qualified));
    ok("SF: listSchema queries an unqualified information_schema.columns when no database is set",
      /^SELECT table_schema, table_name, column_name, data_type FROM information_schema\.columns ORDER BY/.test(sfSchema.captured[1]) &&
      sfSchema.unqualified.tables.length === 2, JSON.stringify(sfSchema.captured[1]));

    const dbxSchema = await page.evaluate(async function () {
      var dbx = Studio.sourceById("databricks");
      var orig = Studio.Databricks.query, captured = [];
      Studio.Databricks.query = function (cfg, sql) {
        captured.push(sql);
        return Promise.resolve({ cols: ["table_schema", "table_name", "column_name", "data_type"], rows: [["default", "events", "ts", "timestamp"]] });
      };
      var r = await dbx.listSchema({ host: "h", token: "t", warehouseId: "w", catalog: "main" });
      Studio.Databricks.query = orig;
      return { r: r, sql: captured[0] };
    });
    ok("DBX: listSchema backtick-quotes the catalog when set",
      /^SELECT table_schema, table_name, column_name, data_type FROM `main`\.information_schema\.columns ORDER BY/.test(dbxSchema.sql) &&
      dbxSchema.r.tables.length === 1 && dbxSchema.r.tables[0].name === "events", JSON.stringify(dbxSchema));

    // PostgREST already answers GET / with a full OpenAPI doc (testData() checks
    // for exactly this 200) — listSchema() reads its `definitions.<table>.properties`
    // straight from that same document, no second query shape needed unlike the
    // three ANSI-SQL adapters above. Runs against the real mock HTTP server (PG
    // has a URL field, unlike Snowflake/Databricks, so no monkey-patch needed).
    const pgSchema = await page.evaluate(async function () {
      var pg = Studio.sourceById("postgrest");
      var ok1 = await pg.listSchema({ url: location.origin + "/__postgrest" });
      var authed = await pg.listSchema({ url: location.origin + "/__postgrest401" }); // bad token -> in-band error
      return { ok1: ok1, authed: authed };
    });
    ok("PG: listSchema reads the OpenAPI document's definitions into a table→columns tree",
      pgSchema.ok1.tables.length === 2 &&
      pgSchema.ok1.tables[0].name === "orders" && pgSchema.ok1.tables[0].schema === "public" &&
      pgSchema.ok1.tables[0].columns.length === 3 &&
      pgSchema.ok1.tables[0].columns[0].name === "region" && pgSchema.ok1.tables[0].columns[0].type === "text" &&
      pgSchema.ok1.tables[1].name === "secure_orders" && pgSchema.ok1.tables[1].columns.length === 2,
      JSON.stringify(pgSchema.ok1));
    ok("PG: listSchema surfaces a rejected request as an in-band error, not a throw",
      pgSchema.authed.tables.length === 0 && !!pgSchema.authed.error, JSON.stringify(pgSchema.authed));

    // BigQuery: a default dataset makes INFORMATION_SCHEMA.COLUMNS reachable unqualified;
    // with none set, the project.region-qualified view lists every dataset in that region.
    // No configurable endpoint field (like Snowflake/Databricks), so query() is monkey-patched.
    const bqSchema = await page.evaluate(async function () {
      var bq = Studio.sourceById("bigquery");
      var orig = Studio.BigQuery.query, captured = [];
      Studio.BigQuery.query = function (cfg, sql) {
        captured.push(sql);
        return Promise.resolve({
          cols: ["table_schema", "table_name", "column_name", "data_type"],
          rows: [["analytics", "orders", "id", "INTEGER"], ["analytics", "orders", "region", "STRING"], ["analytics", "customers", "name", "STRING"]]
        });
      };
      var withDataset = await bq.listSchema({ project: "my-proj", token: "t", dataset: "analytics" });
      var withoutDataset = await bq.listSchema({ project: "my-proj", token: "t", location: "US" });
      Studio.BigQuery.query = orig;
      return { withDataset: withDataset, withoutDataset: withoutDataset, captured: captured };
    });
    ok("BQ: listSchema queries an unqualified INFORMATION_SCHEMA.COLUMNS when a default dataset is set",
      /^SELECT table_schema, table_name, column_name, data_type FROM INFORMATION_SCHEMA\.COLUMNS ORDER BY/.test(bqSchema.captured[0]) &&
      bqSchema.withDataset.tables.length === 2 && bqSchema.withDataset.tables[0].name === "orders" && bqSchema.withDataset.tables[0].columns.length === 2,
      JSON.stringify(bqSchema.captured[0]) + " / " + JSON.stringify(bqSchema.withDataset));
    ok("BQ: listSchema falls back to the project.region-qualified view when no dataset is set",
      /^SELECT table_schema, table_name, column_name, data_type FROM `my-proj`\.`region-us`\.INFORMATION_SCHEMA\.COLUMNS ORDER BY/.test(bqSchema.captured[1]) &&
      bqSchema.withoutDataset.tables.length === 2, JSON.stringify(bqSchema.captured[1]));

    // DuckDB: a connection is always exactly one registered file, so listSchema() is a single-
    // table tree (named after the file, not the internal "t" view alias) described via the same
    // DESCRIBE query testConnection() runs. query() is monkey-patched (same reason as the CDN/
    // wasm-avoiding Z14 DuckDB tests above) — listSchema() goes through it rather than the private
    // withView(), so this exercises the real name-derivation + column-mapping logic.
    const dkSchema = await page.evaluate(async function () {
      var dk = Studio.sourceById("duckdb");
      var orig = Studio.DuckDB.query, captured = [];
      Studio.DuckDB.query = function (cfg, sql) {
        captured.push(sql);
        return Promise.resolve({
          cols: ["column_name", "column_type", "null", "key", "default", "extra"],
          rows: [["region", "VARCHAR", "YES", null, null, null], ["revenue", "DOUBLE", "YES", null, null, null]]
        });
      };
      var r = await dk.listSchema({ fileUrl: "https://bucket.s3.amazonaws.com/sales.parquet?x=1" });
      Studio.DuckDB.query = orig;
      return { r: r, sql: captured[0] };
    });
    ok("DK: listSchema DESCRIBEs the registered view and names the single table after the file, not the alias",
      /^DESCRIBE SELECT \* FROM t$/.test(dkSchema.sql) &&
      dkSchema.r.tables.length === 1 && dkSchema.r.tables[0].name === "sales.parquet" && dkSchema.r.tables[0].schema === null &&
      dkSchema.r.tables[0].columns.length === 2 && dkSchema.r.tables[0].columns[0].name === "region" && dkSchema.r.tables[0].columns[0].type === "VARCHAR",
      JSON.stringify(dkSchema));

    // SQLite: unlike DuckDB's single file, a .sqlite file can hold many tables — listSchema()
    // lists them all via sqlite_master, then PRAGMA table_info per table (not just the one
    // cfg.tableName points at). query() is monkey-patched to answer both query shapes in turn.
    const slSchema = await page.evaluate(async function () {
      var sl = Studio.sourceById("sqlite");
      var orig = Studio.SQLiteHttp.query, captured = [];
      Studio.SQLiteHttp.query = function (cfg, sql) {
        captured.push(sql);
        if (/^SELECT name FROM sqlite_master/.test(sql)) {
          return Promise.resolve({ cols: ["name"], rows: [["customers"], ["orders"]] });
        }
        if (/table_info\("customers"\)/.test(sql)) {
          return Promise.resolve({ cols: ["cid", "name", "type"], rows: [[0, "id", "INTEGER"], [1, "name", "TEXT"]] });
        }
        return Promise.resolve({ cols: ["cid", "name", "type"], rows: [[0, "id", "INTEGER"], [1, "region", "TEXT"], [2, "total", "REAL"]] });
      };
      var r = await sl.listSchema({ fileUrl: "https://example.com/data.sqlite" });
      Studio.SQLiteHttp.query = orig;
      return { r: r, calls: captured };
    });
    ok("SL: listSchema lists every table via sqlite_master, then PRAGMA table_info per table",
      slSchema.calls.length === 3 &&
      slSchema.r.tables.length === 2 &&
      slSchema.r.tables[0].name === "customers" && slSchema.r.tables[0].columns.length === 2 && slSchema.r.tables[0].columns[0].name === "id" &&
      slSchema.r.tables[1].name === "orders" && slSchema.r.tables[1].columns.length === 3,
      JSON.stringify(slSchema));

    const noSchemaAdapters = await page.evaluate(function () {
      return ["httpsql"].map(function (id) { return { id: id, has: typeof (Studio.sourceById(id) || {}).listSchema === "function" }; });
    });
    ok("Schema browser: generic SQL/HTTP (arbitrary JSON API, no reliable dialect/catalog) doesn't claim the capability",
      noSchemaAdapters.every(function (a) { return !a.has; }), JSON.stringify(noSchemaAdapters));

    // ---- CX UI: the "Browse schema" wizard panel (Redshift, against the same mock) ----
    await page.evaluate(function () { window.__studioShellSetSection("connections"); });
    await page.waitForTimeout(80);
    await page.click("#connNewBtn");
    await page.waitForTimeout(120);
    await page.evaluate(function () {
      [].slice.call(document.querySelectorAll(".cx-src-card")).filter(function (c) { return c.querySelector("b").textContent === "Amazon Redshift"; })[0].click();
    });
    await page.waitForTimeout(100);
    const cxSchemaBtnPresent = await page.evaluate(function () { return !!document.querySelector(".cx-schema-btn"); });
    ok("CX: wizard shows a Browse schema button for a listSchema-capable adapter (Redshift)", cxSchemaBtnPresent);
    await page.evaluate(function (port) {
      var f = [].slice.call(document.querySelectorAll(".cx-field input")); // name,region,accessKeyId,secretAccessKey,sessionToken,database,clusterIdentifier,dbUser,workgroupName,endpoint
      f[1].value = "us-east-1"; f[2].value = "AKIDEXAMPLE"; f[3].value = "secret"; f[5].value = "dev"; f[8].value = "default";
      f[9].value = "http://localhost:" + port + "/__redshift-data";
    }, PORT);
    await page.click(".cx-schema-btn");
    await page.waitForFunction(() => document.querySelectorAll(".cx-schema-table").length > 0, { timeout: 5000 });
    const cxSchema = await page.evaluate(function () {
      var tables = [].slice.call(document.querySelectorAll(".cx-schema-table"));
      return { count: tables.length, names: tables.map(function (t) { return t.querySelector("summary b").textContent; }).sort().join(","), firstCols: tables[0].querySelectorAll(".cx-schema-cols li").length };
    });
    ok("CX: Browse schema renders the mock's tables, each with its columns",
      cxSchema.count === 2 && cxSchema.names === "customers,orders", JSON.stringify(cxSchema));
    await page.evaluate(function () {
      var inp = document.querySelector(".cx-schema-filter input");
      inp.value = "ord"; inp.dispatchEvent(new Event("input"));
    });
    const cxSchemaFiltered = await page.evaluate(function () {
      return [].slice.call(document.querySelectorAll(".cx-schema-table")).filter(function (t) { return !t.hidden; }).length;
    });
    ok("CX: the schema panel's filter narrows the table list", cxSchemaFiltered === 1, "visible=" + cxSchemaFiltered);
    await page.evaluate(function () { document.querySelector(".modal-ov .x").click(); });
    await page.waitForTimeout(100);

    // ---- CX UI: the same "Browse schema" wizard, driven by PostgREST this time
    // (proves the panel is genuinely adapter-agnostic, not something that only
    // happens to work for Redshift) ----
    await page.click("#connNewBtn");
    await page.waitForTimeout(120);
    await page.evaluate(function () {
      [].slice.call(document.querySelectorAll(".cx-src-card")).filter(function (c) { return c.querySelector("b").textContent === "PostgreSQL (PostgREST)"; })[0].click();
    });
    await page.waitForTimeout(100);
    const cxPgSchemaBtnPresent = await page.evaluate(function () { return !!document.querySelector(".cx-schema-btn"); });
    ok("CX: wizard shows a Browse schema button for PostgREST too", cxPgSchemaBtnPresent);
    await page.evaluate(function () {
      var f = [].slice.call(document.querySelectorAll(".cx-field input")); // name,url,token,schema
      f[1].value = location.origin + "/__postgrest";
    });
    await page.click(".cx-schema-btn");
    await page.waitForFunction(() => document.querySelectorAll(".cx-schema-table").length > 0, { timeout: 5000 });
    const cxPgSchema = await page.evaluate(function () {
      var tables = [].slice.call(document.querySelectorAll(".cx-schema-table"));
      return { count: tables.length, names: tables.map(function (t) { return t.querySelector("summary b").textContent; }).sort().join(",") };
    });
    ok("CX: Browse schema renders PostgREST's OpenAPI-derived tables too",
      cxPgSchema.count === 2 && cxPgSchema.names === "orders,secure_orders", JSON.stringify(cxPgSchema));
    await page.evaluate(function () { document.querySelector(".modal-ov .x").click(); });
    await page.waitForTimeout(100);

    // ---- QA-01 (2026-07-24 frontend QA): a fresh credentialed connection form must never
    // arrive pre-filled (the reported bug: an unrelated password-manager entry silently
    // populated a brand-new BigQuery token field) and must carry a stable, connector-specific
    // id/name + autocomplete="new-password" instead of the old autocomplete="off" (widely
    // ignored by password managers on password-typed fields). ----
    await page.click("#connNewBtn");
    await page.waitForTimeout(120);
    const cxWizIntro = await page.evaluate(function () {
      var intro = document.querySelector(".cx-wiz-intro");
      return intro ? intro.textContent : null;
    });
    ok("QA-08: new-connection intro no longer promises a stale, mismatched adapter roadmap",
      !!cxWizIntro && !/join this list over time/i.test(cxWizIntro) && !/azure/i.test(cxWizIntro),
      JSON.stringify(cxWizIntro));
    await page.evaluate(function () {
      [].slice.call(document.querySelectorAll(".cx-src-card")).filter(function (c) { return c.querySelector("b").textContent === "BigQuery"; })[0].click();
    });
    await page.waitForTimeout(100);
    const cxFreshSecret = await page.evaluate(function () {
      var f = [].slice.call(document.querySelectorAll(".cx-field input")); // name,project,token,location,dataset
      var tok = f[2];
      return {
        empty: tok.value === "",
        readOnly: tok.readOnly,
        autocomplete: tok.autocomplete,
        idHasAdapterAndKey: /bigquery/.test(tok.id) && /token/.test(tok.id),
        nameMatchesId: tok.name === tok.id,
        projectNotReadOnly: !f[1].readOnly // a plain text field is unaffected
      };
    });
    ok("QA-01: a brand-new credentialed connection's secret field renders empty, readonly, with a stable connector-specific id/name and autocomplete=new-password",
      cxFreshSecret.empty && cxFreshSecret.readOnly && cxFreshSecret.autocomplete === "new-password" &&
      cxFreshSecret.idHasAdapterAndKey && cxFreshSecret.nameMatchesId && cxFreshSecret.projectNotReadOnly,
      JSON.stringify(cxFreshSecret));
    const cxSecretUnlocks = await page.evaluate(function () {
      var tok = [].slice.call(document.querySelectorAll(".cx-field input"))[2];
      tok.dispatchEvent(new Event("focus"));
      var stillReadOnlyAfterFocus = tok.readOnly;
      tok.value = "ya29.usertyped";
      return { stillReadOnlyAfterFocus: stillReadOnlyAfterFocus, value: tok.value };
    });
    ok("QA-01: focusing the secret field lifts readonly so the user can type a real credential",
      cxSecretUnlocks.stillReadOnlyAfterFocus === false && cxSecretUnlocks.value === "ya29.usertyped",
      JSON.stringify(cxSecretUnlocks));
    await page.evaluate(function () { document.querySelector(".modal-ov .x").click(); });
    await page.waitForTimeout(100);

    // Editing an EXISTING connection is unaffected: its already-saved secret still prefills
    // (this is intentional reveal of the user's own stored credential, not autofill).
    const cxEditPrefill = await page.evaluate(function () {
      var row = { id: "qa01-edit-test", name: "QA01 BigQuery", adapter: "bigquery", cfg: { project: "p1", token: "SAVEDSECRET" } };
      Studio.Workspace.put("connections", row, { silent: true });
      window.__studioOpenConnectionWizard(row);
      var f = [].slice.call(document.querySelectorAll(".cx-field input"));
      var tok = f[2];
      return { value: tok.value, readOnly: tok.readOnly, autocomplete: tok.autocomplete };
    });
    ok("QA-01: editing an existing connection still prefills its saved secret (not readonly)",
      cxEditPrefill.value === "SAVEDSECRET" && !cxEditPrefill.readOnly && cxEditPrefill.autocomplete === "new-password",
      JSON.stringify(cxEditPrefill));
    await page.evaluate(function () { document.querySelector(".modal-ov .x").click(); });
    await page.waitForTimeout(100);
    await page.evaluate(function () { Studio.Workspace.remove("connections", "qa01-edit-test", { silent: true }); });

    // ---- LF38 (2026-07-24 live feedback): every masked field gets an eye/eye-off reveal
    // toggle, one shared enhancer (studio.js withRevealToggle) wired into credentialFieldInput
    // (covers every adapter's password-typed field, e.g. the BigQuery token here) plus the
    // Add-user password and M7 provision-secret fields tested further below. ----
    await page.click("#connNewBtn");
    await page.waitForTimeout(120);
    await page.evaluate(function () {
      [].slice.call(document.querySelectorAll(".cx-src-card")).filter(function (c) { return c.querySelector("b").textContent === "BigQuery"; })[0].click();
    });
    await page.waitForTimeout(100);
    const lf38Before = await page.evaluate(function () {
      var tok = [].slice.call(document.querySelectorAll(".cx-field input"))[2];
      var btn = tok.closest(".pw-reveal").querySelector(".pw-reveal-btn");
      return { type: tok.type, ariaPressed: btn.getAttribute("aria-pressed"), ariaLabel: btn.getAttribute("aria-label") };
    });
    ok("LF38: a credentialed connection field's password input starts masked with the toggle in its unrevealed aria state",
      lf38Before.type === "password" && lf38Before.ariaPressed === "false" && lf38Before.ariaLabel === "Show password",
      JSON.stringify(lf38Before));
    await page.click(".pw-reveal .pw-reveal-btn");
    const lf38After = await page.evaluate(function () {
      var tok = [].slice.call(document.querySelectorAll(".cx-field input"))[2];
      var btn = tok.closest(".pw-reveal").querySelector(".pw-reveal-btn");
      return { type: tok.type, ariaPressed: btn.getAttribute("aria-pressed"), ariaLabel: btn.getAttribute("aria-label") };
    });
    ok("LF38: clicking the toggle flips the input to text and updates aria-pressed/aria-label to the revealed state",
      lf38After.type === "text" && lf38After.ariaPressed === "true" && lf38After.ariaLabel === "Hide password",
      JSON.stringify(lf38After));
    await page.click(".pw-reveal .pw-reveal-btn");
    const lf38Back = await page.evaluate(function () {
      var tok = [].slice.call(document.querySelectorAll(".cx-field input"))[2];
      return tok.type;
    });
    ok("LF38: clicking it again re-masks the field", lf38Back === "password", lf38Back);
    await page.evaluate(function () { document.querySelector(".modal-ov .x").click(); });
    await page.waitForTimeout(100);

    // ---- PostgREST adapter (★★★-2): end-to-end against a mock PostgREST -----
    console.log("\n• PostgREST data adapter (★★★-2)");
    const pgShape = await page.evaluate(async function () {
      var pg = Studio.sourceById("postgrest");
      var refuse = await pg.provision({});
      var noTable = await pg.queryData({ url: location.origin + "/__postgrest" }, { kind: "table", table: "" });
      return {
        present: !!pg, dataOnly: !!(pg && !pg.caps.meta && pg.caps.data),
        fieldKeys: pg ? pg.fields.map(function (f) { return f.key; }).join(",") : "",
        refuses: refuse.ok === false && /workspace/i.test(refuse.error || ""),
        noTableInBand: noTable && /no table/i.test(noTable.error || "")
      };
    });
    ok("PG: postgrest adapter registered — data-only, url/token/schema fields, meta-plane refusals, in-band empty-table error",
      pgShape.present && pgShape.dataOnly && pgShape.fieldKeys === "url,token,schema" && pgShape.refuses && pgShape.noTableInBand,
      JSON.stringify(pgShape));
    const pgLive = await page.evaluate(async function () {
      var pg = Studio.sourceById("postgrest");
      var cfg = { url: location.origin + "/__postgrest" };
      var test = await pg.testData(cfg);
      var all = await pg.queryData(cfg, { kind: "table", table: "orders" });
      var filtered = await pg.queryData(cfg, { kind: "table", table: "orders", query: "select=region,total&region=eq.EMEA" });
      var missing = await pg.queryData(cfg, { kind: "table", table: "nope" });
      var bad = await pg.testData({ url: location.origin + "/__postgrest401" });
      return {
        testOk: test.ok === true,
        cols: all.columns.join(","), rowCount: all.rows.length,
        filteredCols: filtered.columns.join(","), filteredRows: JSON.stringify(filtered.rows),
        missingInBand: /HTTP 404/.test(missing.error || ""),
        badTokenInBand: bad.ok === false && /401/.test(bad.error || "") && /token/i.test(bad.error || "")
      };
    });
    ok("PG: testData reaches the REST root; a whole-table read returns real columns and rows",
      pgLive.testOk && pgLive.cols === "region,total,year" && pgLive.rowCount === 3, JSON.stringify(pgLive));
    ok("PG: a raw PostgREST query string (select + eq filter) passes through verbatim",
      pgLive.filteredCols === "region,total" && pgLive.filteredRows === '[["EMEA",120]]', JSON.stringify(pgLive));
    ok("PG: a missing relation and a rejected JWT both come back as friendly in-band errors",
      pgLive.missingInBand && pgLive.badTokenInBand, JSON.stringify(pgLive));
    const pgAuth = await page.evaluate(async function () {
      var pg = Studio.sourceById("postgrest");
      var base = location.origin + "/__postgrest";
      var withToken = await pg.queryData({ url: base, token: "test-token" }, { kind: "table", table: "secure_orders" });
      var noToken = await pg.queryData({ url: base }, { kind: "table", table: "secure_orders" });
      return { authedRows: withToken.rows.length, deniedInBand: /HTTP 401/.test(noToken.error || "") };
    });
    ok("PG: the Bearer token flows as an Authorization header (authed table reads; denied without)",
      pgAuth.authedRows === 3 && pgAuth.deniedInBand, JSON.stringify(pgAuth));
    // The full workspace path a dashboard uses: connection row → dataset row
    // (kind:'table' via dsxKindFor) → runDataset applies {{params}} to the
    // query string, learns the real column list, and stamps lastRun.
    const pgDataset = await page.evaluate(async function () {
      var W = Studio.Workspace;
      W.put("connections", { id: "cx-pg-test", name: "Mock Postgres", adapter: "postgrest", cfg: { url: location.origin + "/__postgrest" } }, { silent: true });
      var d = { id: "ds-pg-test", name: "Orders by region", connectionId: "cx-pg-test", kind: "table",
        table: "orders", query: "select=region,total&region=eq.{{region}}", params: [{ key: "region", value: "AMER" }] };
      W.put("datasets", d, { silent: true });
      var r = await window.__studioRunDataset(d, null);            // defaults: region=AMER
      var override = await window.__studioRunDataset(d, { region: "APAC" }); // dashboard variable wins
      var saved = W.get("datasets", "ds-pg-test");
      W.remove("datasets", "ds-pg-test", { silent: true });
      W.remove("connections", "cx-pg-test", { silent: true });
      return {
        rows: JSON.stringify(r.rows), overrideRows: JSON.stringify(override.rows),
        learnedCols: (saved.columns || []).join(","), lastRunOk: !!(saved.lastRun && saved.lastRun.ok)
      };
    });
    ok("PG: a workspace dataset on a postgrest connection runs live — parameter defaults apply and dashboard variables override them",
      pgDataset.rows === '[["AMER",200]]' && pgDataset.overrideRows === '[["APAC",80]]', JSON.stringify(pgDataset));
    ok("PG: a successful run teaches the dataset its real column list and stamps lastRun",
      pgDataset.learnedCols === "region,total" && pgDataset.lastRunOk, JSON.stringify(pgDataset));

    // ---- CSV/JSON file adapter (★★★-2): inline-content datasets ------------
    console.log("\n• CSV/JSON file adapter (★★★-2)");
    const fileShape = await page.evaluate(async function () {
      var fa = Studio.sourceById("file");
      var test = await fa.testData({});
      var refuse = await fa.provision({});
      var empty = await fa.queryData({}, { kind: "file", content: "" });
      return {
        present: !!fa, dataOnly: !!(fa && !fa.caps.meta && fa.caps.data),
        noFields: fa && fa.fields.length === 0,
        testOk: test.ok === true,
        refuses: refuse.ok === false && /workspace/i.test(refuse.error || ""),
        emptyInBand: /no file/i.test(empty.error || "")
      };
    });
    ok("FILE: adapter registered — data-only, zero connection fields, always-ok test, in-band no-file error",
      fileShape.present && fileShape.dataOnly && fileShape.noFields && fileShape.testOk && fileShape.refuses && fileShape.emptyInBand,
      JSON.stringify(fileShape));
    const fileParse = await page.evaluate(async function () {
      var fa = Studio.sourceById("file");
      // RFC4180: quoted field with an embedded comma + escaped quote; numbers typed
      var csv = 'region,note,total\nEMEA,"hello, ""world""",120\nAMER,plain,200.5\n';
      var c = await fa.queryData({}, { kind: "file", fileName: "t.csv", content: csv });
      // semicolon CSV (European) — delimiter sniffed from the header
      var semi = await fa.queryData({}, { kind: "file", fileName: "s.csv", content: "a;b\n1;2\n" });
      // JSON array with a sparse first object — columns are the UNION over rows
      var json = await fa.queryData({}, { kind: "file", fileName: "t.json", content: '[{"region":"EMEA","total":120},{"region":"APAC","total":80,"year":2025}]' });
      // format sniffed from CONTENT when the name has no useful extension
      var sniffed = await fa.queryData({}, { kind: "file", fileName: "data.txt", content: '[{"x":1}]' });
      var badJson = await fa.queryData({}, { kind: "file", fileName: "bad.json", content: "{not json" });
      var scalarJson = await fa.queryData({}, { kind: "file", fileName: "nums.json", content: "[1,2,3]" });
      var tooBig = await fa.queryData({}, { kind: "file", fileName: "big.csv", content: new Array(2100000).join("x") });
      return {
        csvCols: c.columns.join("|"), csvRow0: JSON.stringify(c.rows[0]), csvTotalTyped: typeof c.rows[1][2],
        semiCols: semi.columns.join("|"), semiRow: JSON.stringify(semi.rows[0]),
        jsonCols: json.columns.join("|"), jsonRow1: JSON.stringify(json.rows[1]),
        sniffedCols: sniffed.columns.join("|"),
        badJsonInBand: /Could not parse bad\.json/.test(badJson.error || ""),
        scalarInBand: /objects/i.test(scalarJson.error || ""),
        tooBigInBand: /too large/i.test(tooBig.error || "") && /DuckDB/.test(tooBig.error || "")
      };
    });
    ok("FILE: CSV parses RFC4180 (quoted commas, escaped quotes) and types numeric cells",
      fileParse.csvCols === "region|note|total" && fileParse.csvRow0 === '["EMEA","hello, \\"world\\"",120]' && fileParse.csvTotalTyped === "number",
      JSON.stringify(fileParse));
    ok("FILE: semicolon CSVs sniff their delimiter; JSON arrays use the key UNION and content-sniff a .txt name",
      fileParse.semiCols === "a|b" && fileParse.semiRow === "[1,2]" &&
      fileParse.jsonCols === "region|total|year" && fileParse.jsonRow1 === '["APAC",80,2025]' &&
      fileParse.sniffedCols === "x", JSON.stringify(fileParse));
    ok("FILE: malformed JSON, non-object rows, and the 2MB cap all come back as friendly in-band errors (cap points at DuckDB)",
      fileParse.badJsonInBand && fileParse.scalarInBand && fileParse.tooBigInBand, JSON.stringify(fileParse));
    // The real user flow: a file connection + the dataset editor's DROP ZONE —
    // pick a file through the real input, save, and run it through the builder path.
    const fixturePath = path.join(__dirname, "fixture-sales.csv");
    fs.writeFileSync(fixturePath, "region,total\nEMEA,120\nAMER,200\n");
    await page.evaluate(function () {
      Studio.Workspace.put("connections", { id: "cx-file-test", name: "My files", adapter: "file", cfg: {} }, { silent: true });
      window.__studioOpenDatasetEditor();
    });
    await page.waitForTimeout(150);
    await page.evaluate(function () {
      var sel = document.querySelector(".modal select.cx-sel");
      sel.value = "cx-file-test"; sel.dispatchEvent(new Event("change", { bubbles: true }));
    });
    await page.waitForTimeout(100);
    const fileZone = await page.evaluate(function () {
      var zone = document.querySelector(".modal .dsx-drop");
      return { hasZone: !!zone, invites: !!zone && /Drop a \.csv or \.json/.test(zone.textContent) };
    });
    ok("FILE: picking a file connection in the dataset editor renders the drop zone", fileZone.hasZone && fileZone.invites, JSON.stringify(fileZone));
    await page.setInputFiles(".modal .dsx-drop-input", fixturePath);
    await page.waitForTimeout(250);
    const fileLoaded = await page.evaluate(function () {
      var zone = document.querySelector(".modal .dsx-drop");
      var name = document.querySelector(".modal input");
      return { label: zone.textContent, nameAutofilled: name.value === "fixture-sales" };
    });
    ok("FILE: the drop zone loads the file (shows name + size) and auto-fills the dataset name from the file",
      /fixture-sales\.csv/.test(fileLoaded.label) && /KB loaded/.test(fileLoaded.label) && fileLoaded.nameAutofilled, JSON.stringify(fileLoaded));
    await page.evaluate(function () {
      var btns = [].slice.call(document.querySelectorAll(".modal button"));
      btns.filter(function (x) { return /^(Save|Add)/.test(x.textContent.trim()); })[0].click();
    });
    await page.waitForTimeout(200);
    const fileRun = await page.evaluate(async function () {
      var d = Studio.Workspace.all("datasets").filter(function (x) { return x.connectionId === "cx-file-test"; })[0];
      if (!d) return { saved: false };
      var r = await window.__studioRunDataset(d, null);
      var saved = Studio.Workspace.get("datasets", d.id);
      Studio.Workspace.remove("datasets", d.id, { silent: true });
      Studio.Workspace.remove("connections", "cx-file-test", { silent: true });
      return { saved: true, kind: d.kind, fileName: d.fileName, rows: JSON.stringify(r.rows), cols: (saved.columns || []).join(","), lastRunOk: !!(saved.lastRun && saved.lastRun.ok) };
    });
    ok("FILE: the saved dataset runs through the builder path — parsed rows, learned columns, lastRun stamped",
      fileRun.saved && fileRun.kind === "file" && fileRun.fileName === "fixture-sales.csv" &&
      fileRun.rows === '[["EMEA",120],["AMER",200]]' && fileRun.cols === "region,total" && fileRun.lastRunOk, JSON.stringify(fileRun));
    fs.unlinkSync(fixturePath);

    // ---- LF24 slice 1: Quick import's column profiler (app/quickmode.js) ----
    console.log("\n• LF24 slice 1: Quick import column profiler");
    const qmProfile = await page.evaluate(function () {
      var states = ["IA", "IL", "IN", "OH", "MO"];
      var cats = ["Cover crops", "No-till", "Reduced tillage", "Conventional"];
      var columns = ["state", "obs_date", "revenue", "practice", "row_id", "notes"];
      var rows = [];
      for (var i = 0; i < 30; i++) {
        rows.push([
          states[i % states.length],
          "2024-" + (1 + (i % 12) < 10 ? "0" : "") + (1 + (i % 12)) + "-01",
          1000 + i * 37,
          cats[i % cats.length],
          i + 1,
          "unique free-text note number " + i
        ]);
      }
      var profile = Studio.QuickMode.profileColumns({ columns: columns, rows: rows });
      var byName = {}; profile.forEach(function (c) { byName[c.name] = c; });
      var summary = Studio.QuickMode.summarize(profile);
      // guardrail columns: all-empty and all-identical should be flagged, not
      // misclassified as something chartable.
      var edge = Studio.QuickMode.profileColumns({ columns: ["blank", "same"], rows: [["", "x"], ["", "x"], ["", "x"]] });
      return {
        types: profile.map(function (c) { return c.name + ":" + c.type; }).join(","),
        stateUnique: byName.state.uniquePct < 1,
        idUniquePct: byName.row_id.uniquePct,
        summary: summary,
        edgeTypes: edge.map(function (c) { return c.type; }).join(",")
      };
    });
    ok("QM: classifyColumn infers geo/temporal/measure/categorical/id/text from name+value signals",
      qmProfile.types === "state:geo,obs_date:temporal,revenue:measure,practice:categorical,row_id:id,notes:text",
      JSON.stringify(qmProfile));
    ok("QM: profile carries cardinality/uniquePct stats usable by a future auto-build engine",
      qmProfile.stateUnique && qmProfile.idUniquePct === 1 &&
      qmProfile.summary.geo === 1 && qmProfile.summary.temporal === 1 && qmProfile.summary.measure === 1 &&
      qmProfile.summary.categorical === 1 && qmProfile.summary.id === 1 && qmProfile.summary.text === 1,
      JSON.stringify(qmProfile));
    ok("QM: guardrail columns (all-blank, all-identical) are flagged empty/constant, not chartable types",
      qmProfile.edgeTypes === "empty,constant", JSON.stringify(qmProfile));

    // The real user flow: drop a CSV straight on the Home "Quick import" card —
    // profiles it, creates a real dataset, and (LF24 slice 2) auto-builds a real
    // dashboard from that profile, landing in Studio with it.
    await page.click('#railNav .rail-item[data-sec="home"]');
    await page.waitForTimeout(150);
    const qiCardBefore = await page.evaluate(function () {
      var c = document.querySelector('#secHome .home-card[data-home="quickimport"]');
      return { present: !!c, hasIcon: !!(c && c.querySelector(".home-card-ic svg")), hasInput: !!document.querySelector("#secHome .home-quickimport-input") };
    });
    ok("QM: Home shows a 'Quick import' card with an icon and a file input", qiCardBefore.present && qiCardBefore.hasIcon && qiCardBefore.hasInput, JSON.stringify(qiCardBefore));
    const qiFixture = path.join(__dirname, "fixture-quickimport.csv");
    // Non-geo dimension on purpose: with the Quick-import default now High (Kevin,
    // 2026-07-27), a geo column would add a choropleth (geo assets); a plain
    // categorical dim keeps this core test deterministic + fast while still
    // exercising the High build (KPI + bars + treemap + table). The full fun tier
    // (map/slope/ensemble) is covered by the dedicated fixture-quickimport-fun block.
    fs.writeFileSync(qiFixture, "category,revenue\nAlpha,120\nBeta,200\nAlpha,150\n");
    const qiDatasetsBefore = await page.evaluate(function () { return Studio.Workspace.all("datasets").length; });
    await page.setInputFiles("#secHome .home-quickimport-input", qiFixture);
    await page.waitForTimeout(500);
    const qiAfter = await page.evaluate(function () {
      var ds = Studio.Workspace.all("datasets").filter(function (d) { return d.fileName === "fixture-quickimport.csv"; })[0];
      var spec = window.__STUDIO_STATE.spec;
      return {
        datasetCount: Studio.Workspace.all("datasets").length,
        dataset: ds ? { kind: ds.kind, columns: ds.columns, name: ds.name } : null,
        connectionAdapter: ds ? (Studio.Workspace.get("connections", ds.connectionId) || {}).adapter : null,
        onStudio: document.querySelector('#railNav .rail-item[data-sec="studio"]').classList.contains("active"),
        kpis: spec.kpis,
        panelTypes: spec.panels.map(function (p) { return p.chart.type; }).sort(),
        daCount: spec.cda.dataAccesses.length,
        barsPanel: spec.panels.filter(function (p) { return p.chart.type === "bars"; }).map(function (p) { return p.chart.map; })[0],
        toastText: document.querySelector("#toast").textContent
      };
    });
    ok("QM: dropping a file creates exactly one new real dataset (kind:file, learned columns)",
      qiAfter.datasetCount === qiDatasetsBefore + 1 && qiAfter.dataset && qiAfter.dataset.kind === "file" &&
      qiAfter.dataset.columns.join(",") === "category,revenue" && qiAfter.connectionAdapter === "file",
      JSON.stringify(qiAfter));
    ok("QM: after import, the app navigates to Studio with an auto-built dashboard (KPI + bars + treemap + table, High default), and the toast summarizes it",
      qiAfter.onStudio && qiAfter.kpis.length === 1 && qiAfter.kpis[0].valueCol === "revenue" &&
      qiAfter.panelTypes.join(",") === "bars,table,treemap" && qiAfter.daCount === 4 &&
      qiAfter.barsPanel && qiAfter.barsPanel.labelCol === "category" && qiAfter.barsPanel.valueCol === "revenue" &&
      /built a dashboard/.test(qiAfter.toastText) && /1 KPI/.test(qiAfter.toastText) && /3 Views/.test(qiAfter.toastText),
      JSON.stringify(qiAfter));
    fs.unlinkSync(qiFixture);
    await page.evaluate(function () {
      var ds = Studio.Workspace.all("datasets").filter(function (d) { return d.fileName === "fixture-quickimport.csv"; })[0];
      if (ds) {
        Studio.Workspace.remove("datasets", ds.id, { silent: true });
        var stillUsed = Studio.Workspace.all("datasets").some(function (d) { return d.connectionId === ds.connectionId; });
        if (!stillUsed) Studio.Workspace.remove("connections", ds.connectionId, { silent: true });
      }
      window.__studioShellSetSection("studio");
    });
    await page.waitForTimeout(100);

    // ---- LF24 slice 3: the creativity dial + "fun" chart tier ----------------
    console.log("\n• LF24 slice 3: Quick mode creativity dial (map/treemap/slope/ensemble)");
    // Snapshot whatever dashboard is currently loaded (JSON round-trip also strips
    // the non-enumerable _qmSource marker, same as normalize()/Studio.clone() do) so
    // the tuner-doesn't-leak check below can restore it afterward instead of leaving
    // Studio on an empty blank dashboard for every later test in this suite.
    const qmPriorSpec = await page.evaluate(function () { return JSON.parse(JSON.stringify(window.__STUDIO_STATE.spec)); });
    const qmAutoSpec = await page.evaluate(function () {
      // Hand-rolled profile (bypassing classifyColumn) for exact control over the
      // signals buildAutoSpec reads: a geo dim (state), a genuine multi-provider
      // series column (provider), a spare composition dim (practice), a real
      // before/after measure pair (revenue_2023/2024), and a temporal column —
      // every "fun" widget's guardrail should fire at once.
      var profile = [
        { name: "state", type: "geo", cardinality: 5, nullPct: 0, uniquePct: 0.17, sample: ["IA", "IL", "IN"] },
        { name: "provider", type: "categorical", cardinality: 3, nullPct: 0, uniquePct: 0.1, sample: ["NASS", "FSA", "AgCensus"] },
        { name: "practice", type: "categorical", cardinality: 4, nullPct: 0, uniquePct: 0.13, sample: ["Cover crops", "No-till"] },
        { name: "revenue_2023", type: "measure", cardinality: 30, nullPct: 0, uniquePct: 1, sample: [] },
        { name: "revenue_2024", type: "measure", cardinality: 30, nullPct: 0, uniquePct: 1, sample: [] },
        { name: "obs_date", type: "temporal", cardinality: 12, nullPct: 0, uniquePct: 0.4, sample: [] }
      ];
      var low = Studio.QuickMode.buildAutoSpec(profile, "low");
      var high = Studio.QuickMode.buildAutoSpec(profile, "high");
      var byType = function (plan) { return plan.map(function (w) { return w.type || w.kind; }); };
      var find = function (plan, t) { return plan.filter(function (w) { return w.type === t; })[0] || null; };
      return {
        lowTypes: byType(low).sort().join(","),
        highTypes: byType(high).sort().join(","),
        map: find(high, "choropleth"),
        treemap: find(high, "treemap"),
        slope: find(high, "slope"),
        ensemble: find(high, "ensembleSeries"),
        scaleZip: Studio.QuickMode.guessGeoScale({ name: "zip_code", sample: [] }),
        scaleHuc: Studio.QuickMode.guessGeoScale({ name: "watershed_huc", sample: [] }),
        scaleFallback: Studio.QuickMode.guessGeoScale({ name: "region", sample: ["IA", "IL", "IN"] }),
        pairNone: Studio.QuickMode.pickSlopePair([{ name: "revenue" }, { name: "cost" }]),
        pairYear: Studio.QuickMode.pickSlopePair([{ name: "revenue_2023" }, { name: "revenue_2024" }, { name: "cost_2023" }])
      };
    });
    ok("QM3: LOW creativity stays the conservative bars/donut/kpi/line/table set — no fun tier",
      qmAutoSpec.lowTypes === "bars,donut,kpi,line,table", JSON.stringify(qmAutoSpec));
    ok("QM3: HIGH creativity mixes in map/treemap/slope/ensemble on top of the same conservative base",
      qmAutoSpec.highTypes === "bars,choropleth,donut,ensembleSeries,kpi,line,slope,table,treemap", JSON.stringify(qmAutoSpec));
    ok("QM3: the map widget uses the geo column + a guessed region scale",
      qmAutoSpec.map && qmAutoSpec.map.dim === "state" && qmAutoSpec.map.scale === "state", JSON.stringify(qmAutoSpec.map));
    ok("QM3: the treemap widget picks a dim the bar/donut pair hasn't already used",
      qmAutoSpec.treemap && qmAutoSpec.treemap.dim === "state", JSON.stringify(qmAutoSpec.treemap));
    ok("QM3: the slope widget only fires on a real before/after measure pair (revenue_2023 → revenue_2024)",
      qmAutoSpec.slope && qmAutoSpec.slope.valueCol1 === "revenue_2023" && qmAutoSpec.slope.valueCol2 === "revenue_2024" && qmAutoSpec.slope.dim === "provider",
      JSON.stringify(qmAutoSpec.slope));
    ok("QM3: the ensemble widget only fires on a genuine multi-provider series column",
      qmAutoSpec.ensemble && qmAutoSpec.ensemble.dim === "practice" && qmAutoSpec.ensemble.seriesCol === "provider" && qmAutoSpec.ensemble.valueCol === "revenue_2023",
      JSON.stringify(qmAutoSpec.ensemble));
    ok("QM3: guessGeoScale reads zip/huc from the column name, and falls back to sampled value shape",
      qmAutoSpec.scaleZip === "zcta" && qmAutoSpec.scaleHuc === "huc8" && qmAutoSpec.scaleFallback === "state", JSON.stringify(qmAutoSpec));
    ok("QM3: pickSlopePair refuses to pair two unrelated measures, but pairs a real year signal",
      qmAutoSpec.pairNone === null && qmAutoSpec.pairYear.a === "revenue_2023" && qmAutoSpec.pairYear.b === "revenue_2024", JSON.stringify(qmAutoSpec));

    // LF50 (b): the Settings "Quick import creativity" row is hidden for now (Kevin:
    // "it's confusing things for now until we improve that") — the row is GONE from the
