      providers.forEach(function (pr, pi) { years.forEach(function (y, yi) {
        chartRows.push([y, pr, +(3 + yi * 0.8 + Math.sin(pi * 2.1 + yi) * 1.4).toFixed(2)]);
      }); });
      chartRows.push(["2017", "AgCensus", 100]);
      var fips = ["17031", "17113", "19153", "19113", "18097", "18157"];
