    // ---- JOBS (Viridis V8 slice 1): prep/rollup engine + materialize --------
    console.log("\n• JOBS: prep/rollup engine (Viridis V8 slice 1)");
    const jobsEngine = await page.evaluate(function () {
      var input = {
        columns: ["county", "state", "pct", "acres"],
        rows: [
          ["Story", "IA", "40", "100"],
          ["Polk", "IA", "60", "300"],
          ["Cook", "IL", "20", "50"]
        ]
      };
      var renamed = Studio.runJobSteps(input, [{ op: "rename", from: "pct", to: "adoption_pct" }]);
      var cast = Studio.runJobSteps(input, [{ op: "cast", col: "pct", to: "number" }]);
      var derived = Studio.runJobSteps(input, [{ op: "derive", outCol: "acre_pct", a: { col: "pct" }, operator: "*", b: { col: "acres" } }]);
      var filtered = Studio.runJobSteps(input, [{ op: "filter", col: "state", cmp: "eq", value: "IA" }]);
      var rolled = Studio.runJobSteps(input, [
        { op: "cast", col: "pct", to: "number" }, { op: "cast", col: "acres", to: "number" },
        { op: "aggregate", groupBy: ["state"], metrics: [
          { col: "pct", fn: "wmean", as: "wmean_pct", weightCol: "acres" },
          { col: "pct", fn: "avg", as: "avg_pct" },
          { col: "county", fn: "count", as: "n" }
        ] }
      ]);
      var csv = Studio.rowsToCsv(["a", "b"], [["1", "x,y"], ["2", 'he said "hi"']]);
      var iaRow = rolled.rows.filter(function (r) { return r[0] === "IA"; })[0];
      return {
        renamedCols: renamed.columns, castType: typeof cast.rows[0][2],
        derivedVal: derived.rows[0][4], filteredCount: filtered.rows.length,
        iaRow: iaRow, csv: csv
      };
    });
    ok("JOBS: rename swaps the column name in place",
      jobsEngine.renamedCols.indexOf("adoption_pct") >= 0 && jobsEngine.renamedCols.indexOf("pct") < 0, JSON.stringify(jobsEngine.renamedCols));
    ok("JOBS: cast turns a text cell into a real number",
      jobsEngine.castType === "number", jobsEngine.castType);
    ok("JOBS: derive multiplies two explicit {col} operands into a new column (40*100=4000)",
      jobsEngine.derivedVal === 4000, String(jobsEngine.derivedVal));
    ok("JOBS: filter keeps only rows matching the comparator",
      jobsEngine.filteredCount === 2, String(jobsEngine.filteredCount));
    ok("JOBS: aggregate's weighted mean is acreage-weighted, not a flat average — IA's 40%/100ac + 60%/300ac -> 55%, not the flat 50% average",
      jobsEngine.iaRow && Math.abs(jobsEngine.iaRow[1] - 55) < 1e-9 && Math.abs(jobsEngine.iaRow[2] - 50) < 1e-9 && jobsEngine.iaRow[3] === 2,
      JSON.stringify(jobsEngine.iaRow));
    ok("JOBS: rowsToCsv quotes cells containing commas/quotes",
      jobsEngine.csv === 'a,b\n1,"x,y"\n2,"he said ""hi"""', jobsEngine.csv);

    // ---- JOBS: join/union across datasets (Viridis V8 slice 2) ------------
    console.log("\n• JOBS: join/union across datasets (Viridis V8 slice 2)");
    const joinUnionEngine = await page.evaluate(function () {
      var left = { columns: ["state", "score"], rows: [["IA", "10"], ["IL", "20"], ["MO", "5"]] };
      var right = { columns: ["state", "pop", "region"], rows: [["IA", "3000", "Midwest"], ["IL", "12000", "Midwest"]] };
      var ctx = { datasets: { R: right } };
      var innerJoin = Studio.runJobSteps(left, [{ op: "join", datasetId: "R", leftCol: "state", rightCol: "state", type: "inner" }], ctx);
      var leftJoin = Studio.runJobSteps(left, [{ op: "join", datasetId: "R", leftCol: "state", rightCol: "state", type: "left" }], ctx);
      var collideJoin = Studio.runJobSteps({ columns: ["state", "score", "pop"], rows: [["IA", "10", "1"]] },
        [{ op: "join", datasetId: "R", leftCol: "state", rightCol: "state", type: "inner" }], ctx);

      var providerA = { columns: ["Provider_Name", "Adoption_Pct", "State"], rows: [["DTN", "35", "IA"]] };
      var providerB = { columns: ["vendor", "pct", "st"], rows: [["Indigo", "42", "IL"]] };
      var base = { columns: ["provider", "adoption_pct", "state"], rows: [] };
      var unionCtx = { datasets: { A: providerA, B: providerB } };
      var unioned = Studio.runJobSteps(base, [
        { op: "union", datasetId: "A", columnMap: [{ to: "provider", from: "Provider_Name" }, { to: "adoption_pct", from: "Adoption_Pct" }, { to: "state", from: "State" }] },
        { op: "union", datasetId: "B", columnMap: [{ to: "provider", from: "vendor" }, { to: "adoption_pct", from: "pct" }, { to: "state", from: "st" }] }
      ], unionCtx);
      var unionFallback = Studio.runJobSteps({ columns: ["state", "score"], rows: [] },
        [{ op: "union", datasetId: "R", columnMap: [] }], ctx);

      return {
        innerRows: innerJoin.rows, innerCols: innerJoin.columns,
        leftRows: leftJoin.rows, collideCols: collideJoin.columns,
        unionRows: unioned.rows, unionCols: unioned.columns,
        fallbackRows: unionFallback.rows,
        stepKinds: Studio.JOB_STEP_KINDS.map(function (k) { return k.op; }),
        datasetIds: Studio.jobStepDatasetIds([{ op: "join", datasetId: "R" }, { op: "union", datasetId: "A" }, { op: "union", datasetId: "R" }, { op: "rename", from: "x", to: "y" }])
      };
    });
    ok("JOBS: inner join adds the right dataset's non-key columns onto matching rows only (MO has no match, dropped)",
      joinUnionEngine.innerCols.join(",") === "state,score,pop,region" &&
      joinUnionEngine.innerRows.length === 2 &&
      joinUnionEngine.innerRows[0].join(",") === "IA,10,3000,Midwest",
      JSON.stringify(joinUnionEngine.innerRows));
    ok("JOBS: left join keeps the unmatched row (MO) with blank added columns instead of dropping it",
      joinUnionEngine.leftRows.length === 3 &&
      joinUnionEngine.leftRows.filter(function (r) { return r[0] === "MO"; })[0][2] == null,
      JSON.stringify(joinUnionEngine.leftRows));
    ok("JOBS: a join column name colliding with an existing column gets an auto _2 suffix, never silently clobbers",
      joinUnionEngine.collideCols.join(",") === "state,score,pop,pop_2,region",
      JSON.stringify(joinUnionEngine.collideCols));
    ok("JOBS: union normalizes two differently-named provider schemas onto one common schema via columnMap (the 5-provider case)",
      joinUnionEngine.unionCols.join(",") === "provider,adoption_pct,state" &&
      joinUnionEngine.unionRows.length === 2 &&
      joinUnionEngine.unionRows[0].join(",") === "DTN,35,IA" &&
      joinUnionEngine.unionRows[1].join(",") === "Indigo,42,IL",
      JSON.stringify(joinUnionEngine.unionRows));
    ok("JOBS: union with no columnMap falls back to a same-name match, else blank (state matches, score has no counterpart)",
      joinUnionEngine.fallbackRows.length === 2 &&
      joinUnionEngine.fallbackRows[0][0] === "IA" && joinUnionEngine.fallbackRows[0][1] == null,
      JSON.stringify(joinUnionEngine.fallbackRows));
    ok("JOBS: JOB_STEP_KINDS now includes join and union",
      joinUnionEngine.stepKinds.indexOf("join") >= 0 && joinUnionEngine.stepKinds.indexOf("union") >= 0,
      JSON.stringify(joinUnionEngine.stepKinds));
    ok("JOBS: jobStepDatasetIds collects every distinct join/union datasetId, ignoring non-referencing steps",
      joinUnionEngine.datasetIds.length === 2 && joinUnionEngine.datasetIds.indexOf("R") >= 0 && joinUnionEngine.datasetIds.indexOf("A") >= 0,
      JSON.stringify(joinUnionEngine.datasetIds));

    // ---- JOBS: uniqueKey step (STATUS.md LF13(c) — the engine had no row-id
    // concept before this) -----------------------------------------------
    console.log("\n• JOBS: uniqueKey step (LF13c)");
    const uniqueKeyEngine = await page.evaluate(function () {
      var input = { columns: ["state", "score"], rows: [["IA", "10"], ["IL", "20"], ["MO", "5"]] };
      var defaulted = Studio.runJobSteps(input, [{ op: "uniqueKey" }]);
      var named = Studio.runJobSteps(input, [{ op: "uniqueKey", outCol: "uid" }]);
      var afterAggregate = Studio.runJobSteps(
        { columns: ["state", "score"], rows: [["IA", "10"], ["IA", "20"], ["IL", "5"]] },
        [{ op: "aggregate", groupBy: ["state"], metrics: [{ col: "score", fn: "sum", as: "total" }] }, { op: "uniqueKey", outCol: "row_id" }]
      );
      var overwritten = Studio.runJobSteps({ columns: ["state", "row_id"], rows: [["IA", "keep-me"]] }, [{ op: "uniqueKey" }]);
      return {
        defaultCols: defaulted.columns, defaultIds: defaulted.rows.map(function (r) { return r[2]; }),
        namedCols: named.columns, namedIds: named.rows.map(function (r) { return r[2]; }),
        aggCols: afterAggregate.columns, aggIds: afterAggregate.rows.map(function (r) { return r[2]; }),
        overwrittenCols: overwritten.columns, overwrittenVal: overwritten.rows[0][1],
        stepKinds: Studio.JOB_STEP_KINDS.map(function (k) { return k.op; })
      };
    });
    ok("JOBS: uniqueKey with no outCol adds a 'row_id' column with a distinct id per row",
      uniqueKeyEngine.defaultCols.join(",") === "state,score,row_id" &&
      uniqueKeyEngine.defaultIds.length === 3 && new Set(uniqueKeyEngine.defaultIds).size === 3,
      JSON.stringify(uniqueKeyEngine.defaultCols) + " " + JSON.stringify(uniqueKeyEngine.defaultIds));
    ok("JOBS: uniqueKey honors a custom outCol name",
      uniqueKeyEngine.namedCols.indexOf("uid") >= 0 && uniqueKeyEngine.namedIds.every(function (v) { return v != null; }),
      JSON.stringify(uniqueKeyEngine.namedCols));
    ok("JOBS: uniqueKey placed after aggregate keys the COLLAPSED rows (one id per group, not per source row)",
      uniqueKeyEngine.aggCols.join(",") === "state,total,row_id" &&
      uniqueKeyEngine.aggIds.length === 2 && new Set(uniqueKeyEngine.aggIds).size === 2,
      JSON.stringify(uniqueKeyEngine.aggCols) + " " + JSON.stringify(uniqueKeyEngine.aggIds));
    ok("JOBS: uniqueKey re-stamps an existing outCol in place rather than duplicating the column",
      uniqueKeyEngine.overwrittenCols.join(",") === "state,row_id" && uniqueKeyEngine.overwrittenVal !== "keep-me",
      JSON.stringify(uniqueKeyEngine.overwrittenCols) + " " + uniqueKeyEngine.overwrittenVal);
    ok("JOBS: JOB_STEP_KINDS now includes uniqueKey",
      uniqueKeyEngine.stepKinds.indexOf("uniqueKey") >= 0, JSON.stringify(uniqueKeyEngine.stepKinds));

    // ---- JOBS: Custom SQL step (Viridis V8 slice 3) -----------------------
    console.log("\n• JOBS: Custom SQL step (Viridis V8 slice 3)");
    const jobsSqlEngine = await page.evaluate(async function () {
      var input = { columns: ["state", "score"], rows: [["IA", "10"], ["IL", "20"]] };
      var calls = [];
      function fakeSqlRunner(columns, rows, query) {
        calls.push({ columns: columns, rows: rows, query: query });
        return Promise.resolve({ columns: ["state", "doubled"], rows: rows.map(function (r) { return [r[0], Number(r[1]) * 2]; }) });
      }
      // no 'sql' step -> the fast path never calls sqlRunner at all
      var noSql = await Studio.runJobStepsAsync(input, [{ op: "rename", from: "score", to: "pts" }], null, fakeSqlRunner);
      var callsAfterNoSql = calls.length;

      // a pipe step, then 'sql', then another pipe step -> proves ordering AND that the sql
      // step's output becomes the input to the step after it
      var mixed = await Studio.runJobStepsAsync(input,
        [{ op: "rename", from: "score", to: "pts" }, { op: "sql", query: "SELECT * FROM t WHERE doubled > 20" }, { op: "cast", col: "doubled", to: "string" }],
        null, fakeSqlRunner);

      // no sqlRunner supplied -> a clear in-band error, not a thrown exception
      var noRunner = await Studio.runJobStepsAsync(input, [{ op: "sql", query: "SELECT 1" }], null, null);

      return {
        noSqlRows: noSql.rows, callsAfterNoSql: callsAfterNoSql,
        mixedCols: mixed.columns, mixedRows: mixed.rows, sqlCallColumns: calls[0] && calls[0].columns, sqlCallQuery: calls[0] && calls[0].query,
        noRunnerError: noRunner.error,
        stepKinds: Studio.JOB_STEP_KINDS.map(function (k) { return k.op; })
      };
    });
    ok("JOBS: runJobStepsAsync never calls sqlRunner when a job has no 'sql' step (zero async engine cost)",
      jobsSqlEngine.callsAfterNoSql === 0 && jobsSqlEngine.noSqlRows[0][1] === "10", JSON.stringify(jobsSqlEngine.noSqlRows));
    ok("JOBS: runJobStepsAsync runs pipe segments around a 'sql' step in order, feeding the sql step's output to the next pipe segment",
      jobsSqlEngine.sqlCallColumns && jobsSqlEngine.sqlCallColumns.join(",") === "state,pts" &&
      jobsSqlEngine.sqlCallQuery === "SELECT * FROM t WHERE doubled > 20" &&
      jobsSqlEngine.mixedCols.join(",") === "state,doubled" &&
      jobsSqlEngine.mixedRows.length === 2 && typeof jobsSqlEngine.mixedRows[0][1] === "string",
      JSON.stringify(jobsSqlEngine));
    ok("JOBS: runJobStepsAsync resolves an in-band error (not a rejection) when a 'sql' step has no sqlRunner available",
      /Custom SQL/.test(jobsSqlEngine.noRunnerError || ""), jobsSqlEngine.noRunnerError);
    ok("JOBS: JOB_STEP_KINDS now includes sql",
      jobsSqlEngine.stepKinds.indexOf("sql") >= 0, JSON.stringify(jobsSqlEngine.stepKinds));

    // end-to-end: a real job with a 'sql' step, DuckDB stubbed (never hits the real CDN/wasm —
    // same precedent as the Z14 DuckDB connector tests above)
    const jobsSqlRun = await page.evaluate(async function () {
      var origQueryRows = Studio.DuckDB.queryRows;
      Studio.DuckDB.queryRows = function (columns, rows, sql) {
        return Promise.resolve({ columns: columns.concat(["flag"]), rows: rows.map(function (r) { return r.concat(["seen:" + sql]); }) });
      };
      var conn = Studio.Workspace.put("connections", { name: "jobs-sql-test", adapter: "file", cfg: {} });
      var src = Studio.Workspace.put("datasets", { name: "jobs-sql-src", connectionId: conn.id, kind: "file", format: "csv", content: "state,score\nIA,10\nIL,20\n" });
      var job = Studio.Workspace.put("jobs", {
        name: "sql-test-job", sourceDatasetId: src.id, outputName: "sql-test-out",
        steps: [{ op: "sql", query: "SELECT * FROM t" }]
      });
      var r = await window.__studioRunJob(job);
      var out = Studio.Workspace.get("datasets", job.outputDatasetId);
      Studio.Workspace.remove("jobs", job.id, { silent: true });
      if (out) Studio.Workspace.remove("datasets", out.id, { silent: true });
      Studio.Workspace.remove("datasets", src.id, { silent: true });
      Studio.Workspace.remove("connections", conn.id, { silent: true });
      Studio.Workspace.all("connections").filter(function (c) { return c.jobOutputs; }).forEach(function (c) { Studio.Workspace.remove("connections", c.id, { silent: true }); });
      Studio.Workspace.notify("*");
      Studio.DuckDB.queryRows = origQueryRows;
      return { columns: r.columns, rows: r.rows, outTags: out && out.tags };
    });
