    await page.evaluate(function () {
      var ta = document.querySelector(".modal textarea.dsx-sql");
      ta.value = "SELECT "; ta.selectionStart = ta.selectionEnd = ta.value.length;
      var det = [].slice.call(document.querySelectorAll(".cx-schema-table")).filter(function (t) { return t.querySelector("summary b").textContent === "orders"; })[0];
      det.open = true; // expand without the table's own click-to-insert, keeping this check focused on columns
    });
    await page.evaluate(function () {
      var det = [].slice.call(document.querySelectorAll(".cx-schema-table")).filter(function (t) { return t.querySelector("summary b").textContent === "orders"; })[0];
      [].slice.call(det.querySelectorAll(".cx-schema-cols li")).filter(function (li) { return li.querySelector(".cx-schema-col").textContent === "region"; })[0].click();
    });
    const dsxColPicked = await page.evaluate(function () { return document.querySelector(".modal textarea.dsx-sql").value; });
    ok("DSX: clicking a column in the schema panel inserts its name into the SQL textarea at the cursor",
      dsxColPicked === "SELECT region", dsxColPicked);
    await page.evaluate(function () { document.querySelector(".modal-ov .x").click(); });
    await page.waitForTimeout(100);
    // negative case: an adapter with no listSchema (turso, "conn-mock" from the earlier DSX test) never shows the button.
    await page.click("#dsxNewBtn");
    await page.waitForTimeout(120);
    await page.evaluate(function () {
      document.querySelector(".modal select.cx-sel").value = "conn-mock";
      document.querySelector(".modal select.cx-sel").dispatchEvent(new Event("change"));
    });
    await page.waitForTimeout(80);
    const dsxSchemaBtnAbsent = await page.evaluate(function () { return !document.querySelector(".dsx-schema-btn"); });
    ok("DSX: no Browse schema button for a connection whose adapter has no listSchema (turso)", dsxSchemaBtnAbsent);
    await page.evaluate(function () { document.querySelector(".modal-ov .x").click(); });
    await page.waitForTimeout(100);
    await page.evaluate(function () {
      Studio.Workspace.remove("connections", "conn-pg-schema", { silent: true });
      Studio.Workspace.remove("connections", "conn-rs-schema", { silent: true });
    });

    const dsxParams = await page.evaluate(async function () {
      var d = Studio.Workspace.all("datasets")[0];
      var okRun = await window.__studioRunDataset(d);                      // default schema=prod
      var badRun = await window.__studioRunDataset(d, { schema: "nope" }); // caller override wins
      return { okRows: okRun.rows.length, okErr: okRun.error || "", badErr: badRun.error || "" };
    });
    ok("DSX: runDataset applies param defaults and lets caller overrides win",
      dsxParams.okRows === 2 && !dsxParams.okErr && /no such table: nope/.test(dsxParams.badErr), JSON.stringify(dsxParams));

    // LF62 (live-QA queue, slice 1): a ✨ name-suggest sparkle button on the dataset
    // editor's name field — the shared Studio.nameSuggest(kind, ctx) heuristic plus a
    // reusable withSparkleButton DOM enhancer, wired first into the field with the
    // richest available context (table/SQL/file/sheet source shape); other name
    // fields (job/dashboard/View/connection) are a separate, later slice.
    console.log("\n• LF62: dataset-name sparkle-suggest button");
    await page.click("#dsxNewBtn");
    await page.waitForTimeout(120);
    const lf62Empty = await page.evaluate(function () {
      var btn = document.querySelector(".modal .name-sparkle-btn");
      var nameInp = document.querySelector(".modal .cx-field input");
      btn.click();
      return {
        btnPresent: !!btn,
        nameStillEmpty: nameInp.value === "",
        toastCls: document.getElementById("toast").className,
        toastText: document.getElementById("toast").textContent
      };
    });
    ok("LF62: the sparkle button sits next to the dataset name field; clicking it with no source filled in yet leaves the name blank and explains why (error toast)",
      lf62Empty.btnPresent && lf62Empty.nameStillEmpty && /err/.test(lf62Empty.toastCls) && /source/i.test(lf62Empty.toastText),
      JSON.stringify(lf62Empty));
    const lf62Filled = await page.evaluate(function () {
      document.querySelector(".modal select.cx-sel").value = "conn-mock";
      document.querySelector(".modal select.cx-sel").dispatchEvent(new Event("change"));
      document.querySelector(".modal textarea.dsx-sql").value = "SELECT region, SUM(amount) AS total FROM sales_by_region GROUP BY region";
      document.querySelector(".modal .name-sparkle-btn").click();
      return { name: document.querySelector(".modal .cx-field input").value };
    });
    ok("LF62: with a SQL source filled in, the sparkle button suggests a readable name pulled from the FROM clause (Studio.nameSuggest + titleize, e.g. 'sales_by_region' -> 'Sales By Region')",
      lf62Filled.name === "Sales By Region", JSON.stringify(lf62Filled));
    await page.evaluate(function () { var x = document.querySelector(".modal-ov .modal .x"); if (x) x.click(); });
    await page.waitForTimeout(120);

    // LF62 slice 7 (live-QA queue, LF62 slice 6's own NEXT pointer): the same sparkle
    // name-suggest button, wired into the dataset editor's "Folder" field — suggests
    // the picked connection's own folder, falling back to the first Tag when no
    // connection is picked yet (or that connection has no folder of its own).
    console.log("\n• LF62 slice 7: dataset-folder sparkle-suggest button");
    await page.evaluate(function () {
      Studio.Workspace.put("connections", { id: "conn-folder-sparkle-test", name: "Folder sparkle test conn", adapter: "turso", folder: "Finance", cfg: {} });
    });
    await page.click("#dsxNewBtn");
    await page.waitForTimeout(120);
    const lf62DsFolder = await page.evaluate(function () {
      document.querySelector(".modal select.cx-sel").value = "conn-folder-sparkle-test";
      document.querySelector(".modal select.cx-sel").dispatchEvent(new Event("change"));
      var folderInp = document.querySelector('.modal input[placeholder="e.g. Finance"]');
      folderInp.parentElement.querySelector(".name-sparkle-btn").click();
      return { folder: folderInp.value };
    });
    ok("LF62 slice 7: with a connection picked that has its own Folder set, the dataset editor's Folder field sparkle suggests that same folder",
      lf62DsFolder.folder === "Finance", JSON.stringify(lf62DsFolder));
    const lf62DsFolderTagFallback = await page.evaluate(function () {
      document.querySelector(".modal select.cx-sel").value = "";
      document.querySelector(".modal select.cx-sel").dispatchEvent(new Event("change"));
      var tagsInp = document.querySelector('.modal input[placeholder="finance, demo"]');
      tagsInp.value = "ops, shared";
      var folderInp = document.querySelector('.modal input[placeholder="e.g. Finance"]');
      folderInp.value = "";
      folderInp.parentElement.querySelector(".name-sparkle-btn").click();
      return { folder: folderInp.value };
    });
    ok("LF62 slice 7: with no connection picked but Tags filled in, the Folder field sparkle falls back to the titleized first tag",
      lf62DsFolderTagFallback.folder === "Ops", JSON.stringify(lf62DsFolderTagFallback));
    await page.evaluate(function () {
      var x = document.querySelector(".modal-ov .modal .x"); if (x) x.click();
      Studio.Workspace.remove("connections", "conn-folder-sparkle-test", { silent: true });
      Studio.Workspace.notify("*");
    });
    await page.waitForTimeout(120);

    // UX8 slice 2 (UX-POLISH track): the remaining non-button badge title= call sites —
    // folder/lineage/param badges (Datasets), the folder badge (Connections/Jobs/Explore),
    // the workspace-capable + last-edited badges (Connections), and the refresh-due/
    // reminder badges (Jobs) — get the same data-tip hydration slice 1 proved on the
    // status dots. Explore's renderExplore() gained its own Studio.Tooltip.hydrate(body)
    // call in this slice (the other three subsystems already called it for their dots).
    const badgeTips = await page.evaluate(function () {
      window.__studioShellSetSection("studio");
      var conn = Studio.Workspace.put("connections", { name: "ux8b-conn", adapter: "turso", cfg: {}, folder: "Finance" });
      var ds = Studio.Workspace.put("datasets", {
        name: "ux8b-ds", connectionId: conn.id, kind: "sql", sql: "select 1", folder: "Finance",
        params: [{ key: "p", value: "1" }]
      });
      Studio.Workspace.put("dashboards", {
        id: "ux8b-dash", ts: new Date().toISOString(), title: "ux8b dashboard", name: "",
        spec: { title: "ux8b dashboard", cda: { dataAccesses: [{ id: "da1", datasetId: ds.id }] }, panels: [], kpis: [] }
      }, { silent: true });
      var job = Studio.Workspace.put("jobs", {
        name: "ux8b-job", sourceDatasetId: ds.id, steps: [], folder: "Finance",
        refreshEveryDays: 30, lastRun: { ok: true, at: Date.now() - 40 * 86400000, rows: 1, error: "" }
      });
      var analysis = Studio.Workspace.put("analyses", { name: "ux8b-analysis", chartType: "bar", folder: "Finance" });

      window.__studioRenderConnections();
      window.__studioRenderDatasets();
      window.__studioRenderJobs();
      window.__studioRenderExplore();

      function tipInfo(el) {
        if (!el) return null;
        var bub = el.querySelector(".ps-tip-bub");
        return {
          noNativeTitle: !el.hasAttribute("title"), noDataTip: !el.hasAttribute("data-tip"),
          isPsTip: el.classList.contains("ps-tip"), focusable: el.tabIndex === 0,
          ariaLabel: el.getAttribute("aria-label") || "", bubText: bub ? bub.textContent : ""
        };
      }

      var connRow = document.querySelector('.cx-row[data-conn-id="' + conn.id + '"]');
      var dsRow = document.querySelector('.cx-row[data-dsx-id="' + ds.id + '"]');
      var jobRow = document.querySelector('.cx-row[data-job-id="' + job.id + '"]');
      var xpRow = document.querySelector('.xp-saved-row[data-xp-a="' + analysis.id + '"]');

      var out = {
        connMeta: tipInfo(connRow && connRow.querySelector(".cx-badge:not(.cx-folder)")),
        connFolder: tipInfo(connRow && connRow.querySelector(".cx-folder")),
        connWhen: tipInfo(connRow && connRow.querySelector(".cx-when")),
        dsFolder: tipInfo(dsRow && dsRow.querySelector(".cx-folder")),
        dsLineage: tipInfo(dsRow && dsRow.querySelector(".cx-lineage")),
        dsParam: tipInfo(dsRow && dsRow.querySelector(".cx-badge:not(.cx-folder):not(.cx-lineage)")),
        jobFolder: tipInfo(jobRow && jobRow.querySelector(".cx-folder")),
        jobRefreshDue: tipInfo(jobRow && jobRow.querySelector(".cx-refresh-due")),
        xpFolder: tipInfo(xpRow && xpRow.querySelector(".cx-folder"))
      };

      Studio.Workspace.remove("analyses", analysis.id, { silent: true });
      Studio.Workspace.remove("jobs", job.id, { silent: true });
      Studio.Workspace.remove("dashboards", "ux8b-dash", { silent: true });
      Studio.Workspace.remove("datasets", ds.id, { silent: true });
      Studio.Workspace.remove("connections", conn.id, { silent: true });
      Studio.Workspace.notify("*");
      return out;
    });
    function tipOk(t) { return !!t && t.noNativeTitle && t.noDataTip && t.isPsTip && t.focusable && t.ariaLabel === t.bubText && t.bubText.length > 0; }
    ok("UX8: Connections' workspace-capable badge is hydrated into a focusable tooltip",
      tipOk(badgeTips.connMeta) && /workspace/.test(badgeTips.connMeta.bubText), JSON.stringify(badgeTips.connMeta));
    ok("UX8: Connections' folder badge is hydrated, aria-labeled 'Folder: Finance'",
      tipOk(badgeTips.connFolder) && badgeTips.connFolder.bubText === "Folder: Finance", JSON.stringify(badgeTips.connFolder));
    ok("UX8: Connections' 'last edited' timestamp is hydrated into a focusable tooltip",
      tipOk(badgeTips.connWhen) && badgeTips.connWhen.bubText === "Last edited", JSON.stringify(badgeTips.connWhen));
    ok("UX8: Datasets' folder badge is hydrated, aria-labeled 'Folder: Finance'",
      tipOk(badgeTips.dsFolder) && badgeTips.dsFolder.bubText === "Folder: Finance", JSON.stringify(badgeTips.dsFolder));
    ok("UX8: Datasets' lineage badge is hydrated and names the referencing dashboard",
      tipOk(badgeTips.dsLineage) && /ux8b dashboard/.test(badgeTips.dsLineage.bubText), JSON.stringify(badgeTips.dsLineage));
    ok("UX8: Datasets' param-count badge is hydrated, aria-labeled 'Accepts parameters'",
      tipOk(badgeTips.dsParam) && badgeTips.dsParam.bubText === "Accepts parameters", JSON.stringify(badgeTips.dsParam));
    ok("UX8: Jobs' folder badge is hydrated the same way",
      tipOk(badgeTips.jobFolder) && badgeTips.jobFolder.bubText === "Folder: Finance", JSON.stringify(badgeTips.jobFolder));
    ok("UX8: Jobs' 'Refresh due' badge is hydrated and states why it's overdue",
      tipOk(badgeTips.jobRefreshDue) && /overdue/.test(badgeTips.jobRefreshDue.bubText), JSON.stringify(badgeTips.jobRefreshDue));
    ok("UX8: Explore's saved-analysis folder badge is hydrated too (renderExplore now calls Tooltip.hydrate)",
      tipOk(badgeTips.xpFolder) && badgeTips.xpFolder.bubText === "Folder: Finance", JSON.stringify(badgeTips.xpFolder));

    // LF51 (nav IA spec (c), "show a full date-time, not just a date"): every "cx-when"
    // row badge — Connections/Datasets/Jobs/Dashboards/Repository — now goes through the
    // shared Studio.fmtWhen (app/model.js) instead of a bare toLocaleDateString().
    const lf51When = await page.evaluate(function () {
      window.__studioShellSetSection("studio");
      var fixedTs = new Date("2026-03-05T18:30:00Z").getTime();
      var conn = Studio.Workspace.put("connections", { name: "lf51-conn", adapter: "turso", cfg: {}, updatedAt: fixedTs });
      var ds = Studio.Workspace.put("datasets", { name: "lf51-ds", connectionId: conn.id, kind: "sql", sql: "select 1", updatedAt: fixedTs });
      var job = Studio.Workspace.put("jobs", { name: "lf51-job", sourceDatasetId: ds.id, steps: [], updatedAt: fixedTs });
      Studio.Workspace.put("dashboards", {
        id: "lf51-dash", ts: new Date(fixedTs).toISOString(), title: "lf51 dashboard", name: "",
        spec: { title: "lf51 dashboard", cda: { dataAccesses: [] }, panels: [], kpis: [] }
      }, { silent: true });

      window.__studioRenderConnections();
      window.__studioRenderDatasets();
      window.__studioRenderJobs();
      window.__studioShellSetSection("dashboards");
      window.__studioRenderDashboards();
      // dashListRowHtml (the "cx-when"-carrying compact row) only paints in List
      // view — tiles (recentCardHtml) are the default — so toggle into List for
      // this check, then toggle back so later view-toggle tests aren't disturbed.
      var wasList = localStorage.getItem("studio-dash-view") === "list";
      if (!wasList) document.getElementById("dashViewToggle").click();
      window.__studioShellSetSection("repository");
      window.__studioRenderRepository();

      function whenText(sel) { var el = document.querySelector(sel); return el ? el.textContent : null; }
      var out = {
        conn: whenText('.cx-row[data-conn-id="' + conn.id + '"] .cx-when'),
        ds: whenText('.cx-row[data-dsx-id="' + ds.id + '"] .cx-when'),
        job: whenText('.cx-row[data-job-id="' + job.id + '"] .cx-when'),
        dash: whenText('.dash-li[data-recent="lf51-dash"] .cx-when'),
        repo: whenText('.cx-row[data-repo-id="' + job.id + '"] .cx-when')
      };
      if (!wasList) document.getElementById("dashViewToggle").click();

      Studio.Workspace.remove("dashboards", "lf51-dash", { silent: true });
      Studio.Workspace.remove("jobs", job.id, { silent: true });
      Studio.Workspace.remove("datasets", ds.id, { silent: true });
      Studio.Workspace.remove("connections", conn.id, { silent: true });
      Studio.Workspace.notify("*");
      window.__studioShellSetSection("studio");
      return out;
    });
    function hasDateAndTime(s) { return !!s && /\d{1,2}:\d{2}/.test(s) && /,/.test(s); }
    ok("LF51: Connections row 'last edited' badge shows a full date-time, not just a date",
      hasDateAndTime(lf51When.conn), JSON.stringify(lf51When.conn));
    ok("LF51: Datasets row timestamp badge shows a full date-time",
      hasDateAndTime(lf51When.ds), JSON.stringify(lf51When.ds));
    ok("LF51: Jobs row timestamp badge shows a full date-time",
      hasDateAndTime(lf51When.job), JSON.stringify(lf51When.job));
    ok("LF51: Dashboards list row timestamp badge shows a full date-time",
      hasDateAndTime(lf51When.dash), JSON.stringify(lf51When.dash));
    ok("LF51: Repository row timestamp badge shows a full date-time",
      hasDateAndTime(lf51When.repo), JSON.stringify(lf51When.repo));

    // LF51 (nav IA spec (d), "list + rich-tile views"): the Datasets section can render
    // as the compact list (default) or a tile grid, via #dsxViewToggle (persisted at
    // studio-dsx-view). Both layouts reuse the same data-dsx-* hooks, so a tile keeps a
    // working title button + Edit action. Verify the toggle flips list ⇆ tiles and sticks.
    const lf51View = await page.evaluate(function () {
      window.__studioShellSetSection("datasets");
      try { localStorage.removeItem("studio-dsx-view"); } catch (e) {}
      var conn = Studio.Workspace.put("connections", { name: "lf51v-conn", adapter: "turso", cfg: {} });
      var ds = Studio.Workspace.put("datasets", { name: "lf51v-ds", connectionId: conn.id, kind: "sql", sql: "select 1" });
      var results = document.getElementById("dsxResults");
      var toggle = document.getElementById("dsxViewToggle");
      window.__studioRenderDatasets();
      // default = list
      var listRow = results.querySelector('.cx-row[data-dsx-id="' + ds.id + '"]');
      var out = {
        toggleExists: !!toggle,
        listDefault: !!listRow && !results.querySelector(".dsx-tile"),
        listToggleLabel: toggle ? toggle.textContent : null
      };
      // switch to tiles
      if (toggle) toggle.click();
      var tile = results.querySelector('.dsx-tile[data-dsx-id="' + ds.id + '"]');
      out.tilesAfterClick = !!tile && !results.querySelector(".cx-row");
      out.tileHasTitleBtn = !!(tile && tile.querySelector(".cx-title-btn"));
      out.tileHasEdit = !!(tile && tile.querySelector('[data-dsx-edit="' + ds.id + '"]'));
      out.tileToggleLabel = toggle ? toggle.textContent : null;
      out.persisted = localStorage.getItem("studio-dsx-view");
      // switch back to list
      if (toggle) toggle.click();
      out.backToList = !!results.querySelector('.cx-row[data-dsx-id="' + ds.id + '"]') && !results.querySelector(".dsx-tile");
      Studio.Workspace.remove("datasets", ds.id, { silent: true });
      Studio.Workspace.remove("connections", conn.id, { silent: true });
      Studio.Workspace.notify("*");
      try { localStorage.removeItem("studio-dsx-view"); } catch (e) {}
      window.__studioShellSetSection("studio");
      return out;
    });
    ok("LF51: the Datasets section defaults to the compact list with a 'Tile view' toggle",
      lf51View.toggleExists && lf51View.listDefault && lf51View.listToggleLabel === "Tile view", JSON.stringify(lf51View));
    ok("LF51: the toggle switches Datasets to a tile grid (persisted), keeping title + Edit hooks",
      lf51View.tilesAfterClick && lf51View.tileHasTitleBtn && lf51View.tileHasEdit &&
      lf51View.tileToggleLabel === "List view" && lf51View.persisted === "tiles", JSON.stringify(lf51View));
    ok("LF51: toggling back returns Datasets to the list layout",
      lf51View.backToList, JSON.stringify(lf51View));

    // LF51 (d) extended to Connections and Jobs: the same list ⇆ tile toggle, each with its own
    // persisted key (studio-conn-view / studio-jobs-view), each keeping its title + Edit hooks.
    const lf51ViewCJ = await page.evaluate(function () {
      function flip(section, render, resultsId, toggleId, key, dataAttr, id) {
        window.__studioShellSetSection(section);
        try { localStorage.removeItem(key); } catch (e) {}
        render();
        var results = document.getElementById(resultsId), toggle = document.getElementById(toggleId);
        var listDefault = !!results.querySelector('.cx-row[' + dataAttr + '="' + id + '"]') && !results.querySelector(".dsx-tile");
        var listLabel = toggle ? toggle.textContent : null;
        if (toggle) toggle.click();
        var tile = results.querySelector('.dsx-tile[' + dataAttr + '="' + id + '"]');
        var out = {
          listDefault: listDefault, listLabel: listLabel,
          tiles: !!tile && !results.querySelector(".cx-row"),
          titleBtn: !!(tile && tile.querySelector(".cx-title-btn")),
          persisted: localStorage.getItem(key)
        };
        if (toggle) toggle.click();
        out.backToList = !!results.querySelector('.cx-row[' + dataAttr + '="' + id + '"]') && !results.querySelector(".dsx-tile");
        try { localStorage.removeItem(key); } catch (e) {}
        return out;
      }
      var conn = Studio.Workspace.put("connections", { name: "lf51cj-conn", adapter: "turso", cfg: {} });
      var connOut = flip("connections", window.__studioRenderConnections, "connResults", "connViewToggle", "studio-conn-view", "data-conn-id", conn.id);
      var ds = Studio.Workspace.put("datasets", { name: "lf51cj-ds", connectionId: conn.id, kind: "sql", sql: "select 1" });
      var job = Studio.Workspace.put("jobs", { name: "lf51cj-job", sourceDatasetId: ds.id, steps: [] });
      var jobOut = flip("jobs", window.__studioRenderJobs, "jobsResults", "jobsViewToggle", "studio-jobs-view", "data-job-id", job.id);
      Studio.Workspace.remove("jobs", job.id, { silent: true });
      Studio.Workspace.remove("datasets", ds.id, { silent: true });
      Studio.Workspace.remove("connections", conn.id, { silent: true });
      Studio.Workspace.notify("*");
      window.__studioShellSetSection("studio");
      return { conn: connOut, job: jobOut };
    });
    ok("LF51: Connections has the same list ⇆ tile toggle (persisted, keeps title hooks)",
      lf51ViewCJ.conn.listDefault && lf51ViewCJ.conn.listLabel === "Tile view" && lf51ViewCJ.conn.tiles &&
      lf51ViewCJ.conn.titleBtn && lf51ViewCJ.conn.persisted === "tiles" && lf51ViewCJ.conn.backToList,
      JSON.stringify(lf51ViewCJ.conn));
    ok("LF51: Jobs has the same list ⇆ tile toggle (persisted, keeps title hooks)",
      lf51ViewCJ.job.listDefault && lf51ViewCJ.job.listLabel === "Tile view" && lf51ViewCJ.job.tiles &&
      lf51ViewCJ.job.titleBtn && lf51ViewCJ.job.persisted === "tiles" && lf51ViewCJ.job.backToList,
      JSON.stringify(lf51ViewCJ.job));

    // LF51 (d), last of the four: Repository — a row lives inside a folder-group tree rather
    // than a flat list, so the toggle switches every group's contents wrapper (cx-list ⇆
    // dsx-grid) as well as each row's own markup (cx-row ⇆ dsx-tile), keeping the quick-edit hook.
    const lf51ViewRepo = await page.evaluate(function () {
      window.__studioShellSetSection("repository");
      try { localStorage.removeItem("studio-repo-view"); } catch (e) {}
      var conn = Studio.Workspace.put("connections", { name: "lf51repo-conn", adapter: "turso", cfg: {} });
      var ds = Studio.Workspace.put("datasets", { name: "lf51repo-ds", connectionId: conn.id, kind: "sql", sql: "select 1" });
      var results = document.getElementById("repoAllResults");
      var toggle = document.getElementById("repoViewToggle");
      window.__studioRenderRepository();
      var listDefault = !!results.querySelector('.cx-row[data-repo-id="' + ds.id + '"]') && !results.querySelector(".dsx-tile");
      var out = { toggleExists: !!toggle, listDefault: listDefault, listLabel: toggle ? toggle.textContent : null };
      if (toggle) toggle.click();
      var tile = results.querySelector('.dsx-tile[data-repo-id="' + ds.id + '"]');
      out.tiles = !!tile && !results.querySelector(".cx-row");
      out.titleBtn = !!(tile && tile.querySelector(".cx-title-btn"));
      out.editBtn = !!(tile && tile.querySelector('[data-repo-edit-id="' + ds.id + '"]'));
      out.tileLabel = toggle ? toggle.textContent : null;
      out.persisted = localStorage.getItem("studio-repo-view");
      if (toggle) toggle.click();
      out.backToList = !!results.querySelector('.cx-row[data-repo-id="' + ds.id + '"]') && !results.querySelector(".dsx-tile");
      Studio.Workspace.remove("datasets", ds.id, { silent: true });
      Studio.Workspace.remove("connections", conn.id, { silent: true });
      Studio.Workspace.notify("*");
      try { localStorage.removeItem("studio-repo-view"); } catch (e) {}
      window.__studioShellSetSection("studio");
      return out;
    });
    ok("LF51: Repository defaults to the compact list with a 'Tile view' toggle",
      lf51ViewRepo.toggleExists && lf51ViewRepo.listDefault && lf51ViewRepo.listLabel === "Tile view", JSON.stringify(lf51ViewRepo));
    ok("LF51: the toggle switches Repository's folder groups to a tile grid (persisted), keeping title + quick-edit hooks",
      lf51ViewRepo.tiles && lf51ViewRepo.titleBtn && lf51ViewRepo.editBtn &&
      lf51ViewRepo.tileLabel === "List view" && lf51ViewRepo.persisted === "tiles", JSON.stringify(lf51ViewRepo));
    ok("LF51: toggling back returns Repository to the list layout",
      lf51ViewRepo.backToList, JSON.stringify(lf51ViewRepo));

