        listDefault: !!row && !results.querySelector(".dsx-tile"),
        rowHasTitle: !!(row && row.querySelector(".cx-title-btn") && row.querySelector(".cx-title-btn b").textContent === "lf57-a"),
        rowHasChartType: !!(row && row.textContent.indexOf("Bar chart") >= 0),
