    ok("LF57: the chart-type facet (multi-select) narrows the list to just that type",
      lf57Facets.typeChipExists && lf57Facets.typeNarrows, JSON.stringify(lf57Facets));

    const lf57Actions = await page.evaluate(function () {
      window.__studioShellSetSection("views");
      var a = Studio.Workspace.put("analyses", { name: "lf57act", chartType: "bars", da: { id: "da1", columns: [] } });
      window.__studioRenderViews();
      var out = {};
      // Pin/private route straight into Studio.Explore's own methods, so state can
      // never drift from Explore's own sidebar — verify the underlying row flips.
      document.querySelector('[data-vw-pin="' + a.id + '"]').click();
      out.pinnedAfterClick = !!Studio.Workspace.get("analyses", a.id).pinned;
      document.querySelector('[data-vw-private="' + a.id + '"]').click();
      out.privateAfterClick = !!Studio.Workspace.get("analyses", a.id).private;
      // Open: loads it into Explore and switches section (row click and the explicit button do the same)
      document.querySelector('[data-vw-open="' + a.id + '"]').click();
      out.openedIntoExplore = window.__studioShellGetSection() === "explore" && Studio.Explore.XP.analysisId === a.id;
      window.__studioShellSetSection("views");
      window.__studioRenderViews();
      // Add to dashboard: opens the same "Add to which dashboard?" picker Explore's sidebar uses
      document.querySelector('[data-vw-dash="' + a.id + '"]').click();
      out.dashPickerOpened = !!document.querySelector(".modal-ov");
      var ov = document.querySelector(".modal-ov"); if (ov) ov.remove();
      window.__studioShellSetSection("views");
      window.__studioRenderViews();
      // Delete: confirm() gate, then the row is gone and Explore's own pointer is cleared
      Studio.Explore.XP.analysisId = a.id;
      window.confirm = function () { return true; };
      document.querySelector('[data-vw-del="' + a.id + '"]').click();
      out.deleted = !Studio.Workspace.get("analyses", a.id);
      out.explorePointerCleared = Studio.Explore.XP.analysisId !== a.id;
      window.__studioShellSetSection("studio");
      return out;
    });
    ok("LF57: the pin toggle flips straight through Studio.Explore.togglePin",
      lf57Actions.pinnedAfterClick, JSON.stringify(lf57Actions));
    ok("LF57: the private toggle flips straight through Studio.Explore.togglePrivate",
      lf57Actions.privateAfterClick, JSON.stringify(lf57Actions));
    ok("LF57: Open loads the View into Explore and switches section",
      lf57Actions.openedIntoExplore, JSON.stringify(lf57Actions));
    ok("LF57: Add to dashboard opens the same existing-dashboard picker Explore's sidebar uses",
      lf57Actions.dashPickerOpened, JSON.stringify(lf57Actions));
    ok("LF57: Delete removes the View (after confirm) and clears Explore's own pointer if it was open",
      lf57Actions.deleted && lf57Actions.explorePointerCleared, JSON.stringify(lf57Actions));

    // LF57 follow-up: Duplicate — a straight clone (chart/folder/private carried over,
    // pinned reset, uniquified "(copy)" name), one of the three items LF57 slice 1's own
    // DONE note left "genuinely still open."
    const lf57Dup = await page.evaluate(function () {
      window.__studioShellSetSection("views");
      var a = Studio.Workspace.put("analyses", {
        name: "lf57dup", chartType: "donut", folder: "Finance", private: true, pinned: true,
        da: { id: "da1", columns: [] }
      });
      window.__studioRenderViews();
      var out = {};
      var row = document.querySelector('.cx-row[data-vw-id="' + a.id + '"]');
      out.dupBtnExists = !!row.querySelector('[data-vw-dup="' + a.id + '"]');
      document.querySelector('[data-vw-dup="' + a.id + '"]').click();
      out.stillOnViews = window.__studioShellGetSection() === "views";
      var all = Studio.Workspace.all("analyses");
      var dup = all.filter(function (r) { return r.id !== a.id && r.name.indexOf("lf57dup") === 0; })[0];
      out.dupCreated = !!dup;
      out.dupName = dup && dup.name;
      out.dupCarriesChartType = !!dup && dup.chartType === "donut";
      out.dupCarriesFolder = !!dup && dup.folder === "Finance";
      out.dupCarriesPrivate = !!dup && dup.private === true;
      out.dupNotPinned = !!dup && dup.pinned === false;
      out.originalUntouched = Studio.Workspace.get("analyses", a.id).name === "lf57dup";
      // duplicating the duplicate uniquifies again instead of colliding
      document.querySelector('[data-vw-dup="' + dup.id + '"]').click();
      var dup2 = Studio.Workspace.all("analyses").filter(function (r) { return r.id !== a.id && r.id !== dup.id && r.name.indexOf("lf57dup") === 0; })[0];
      out.dup2Created = !!dup2;
      out.dup2NameDiffers = !!dup2 && dup2.name !== dup.name;
      Studio.Workspace.remove("analyses", a.id, { silent: true });
      Studio.Workspace.remove("analyses", dup.id, { silent: true });
      if (dup2) Studio.Workspace.remove("analyses", dup2.id, { silent: true });
      Studio.Workspace.notify("*");
      window.__studioShellSetSection("studio");
      return out;
    });
    ok("LF57: each row carries a Duplicate action",
      lf57Dup.dupBtnExists, JSON.stringify(lf57Dup));
    ok("LF57: Duplicate creates a new row (not a navigation to Explore) and leaves the original untouched",
      lf57Dup.dupCreated && lf57Dup.stillOnViews && lf57Dup.originalUntouched, JSON.stringify(lf57Dup));
    ok("LF57: the duplicate carries over chart type/folder/private but starts unpinned, with a uniquified '(copy)' name",
      lf57Dup.dupCarriesChartType && lf57Dup.dupCarriesFolder && lf57Dup.dupCarriesPrivate &&
      lf57Dup.dupNotPinned && lf57Dup.dupName === "lf57dup (copy)", JSON.stringify(lf57Dup));
    ok("LF57: duplicating a duplicate uniquifies again instead of colliding",
      lf57Dup.dup2Created && lf57Dup.dup2NameDiffers, JSON.stringify(lf57Dup));

    // LF57 follow-up: per-chart-type row icons — reuses the same themed gallery-thumbnail
    // SVGs (Studio.CHART_SVG) the chart-type picker already draws from, instead of every
    // row sharing one generic glyph. One of the three items LF57 slice 1's own DONE note
    // left "genuinely still open" (alongside Duplicate and the standalone export, both
    // shipped separately).
    const lf57Icons = await page.evaluate(function () {
      window.__studioShellSetSection("views");
      var a1 = Studio.Workspace.put("analyses", { name: "lf57ic-bars", chartType: "bars", da: { id: "da1", columns: [] } });
      var a2 = Studio.Workspace.put("analyses", { name: "lf57ic-donut", chartType: "donut", da: { id: "da2", columns: [] } });
      // colorScale has no Studio.CHART_SVG gallery thumbnail — exercises the fallback path.
      var a3 = Studio.Workspace.put("analyses", { name: "lf57ic-fallback", chartType: "colorScale", da: { id: "da3", columns: [] } });
      window.__studioRenderViews();
      var out = {};
      var ic1 = document.querySelector('.cx-row[data-vw-id="' + a1.id + '"] .cx-ic');
      var ic2 = document.querySelector('.cx-row[data-vw-id="' + a2.id + '"] .cx-ic');
      var ic3 = document.querySelector('.cx-row[data-vw-id="' + a3.id + '"] .cx-ic');
      out.bothHaveSvg = !!(ic1 && ic1.querySelector("svg") && ic2 && ic2.querySelector("svg"));
      out.differByType = !!(ic1 && ic2) && ic1.innerHTML !== ic2.innerHTML;
      out.fallbackUsesGenericIcon = !!(ic3 && ic3.querySelector("svg") && ic3.innerHTML !== (ic1 ? ic1.innerHTML : null));
      Studio.Workspace.remove("analyses", a1.id, { silent: true });
      Studio.Workspace.remove("analyses", a2.id, { silent: true });
      Studio.Workspace.remove("analyses", a3.id, { silent: true });
      Studio.Workspace.notify("*");
      window.__studioShellSetSection("studio");
      return out;
    });
    ok("LF57: each row's icon is a themed per-chart-type SVG (not one shared generic glyph)",
      lf57Icons.bothHaveSvg && lf57Icons.differByType, JSON.stringify(lf57Icons));
    ok("LF57: a chart type with no gallery thumbnail falls back to a generic icon",
      lf57Icons.fallbackUsesGenericIcon, JSON.stringify(lf57Icons));

    // LF57 follow-up ("make standalone") — the last of the three items LF57 slice 1's own
    // DONE note flagged as genuinely still open (Duplicate + per-chart-type icons both
    // shipped separately, above). A saved View has no open dashboard to pare down like the
    // in-canvas panel's own "Export this View…" (exportPanelEmbed) does — this reuses
    // Studio.Explore.analysisSpec(a), the same single-panel/no-kpis/no-filters shape Home's
    // live-widget preview already builds from a saved analysis, so the exported HTML is the
    // SAME self-contained toolkit as every other export, just fed from the catalog instead
    // of a canvas selection.
    const lf57Export = await page.evaluate(function () {
      window.__studioShellSetSection("views");
      var a = Studio.Workspace.put("analyses", {
        name: "lf57export", chartType: "donut",
        chart: { type: "donut", map: {}, opts: {} },
        da: { id: "da1", columns: [] }
      });
      window.__studioRenderViews();
      var out = {};
      var row = document.querySelector('.cx-row[data-vw-id="' + a.id + '"]');
      out.exportBtnExists = !!row.querySelector('[data-vw-export="' + a.id + '"]');
      document.querySelector('[data-vw-export="' + a.id + '"]').click();
      out.stillOnViews = window.__studioShellGetSection() === "views";
      var rows = [].slice.call(document.querySelectorAll(".modal .dl-row"));
      var title = document.querySelector(".modal-h") ? document.querySelector(".modal-h").textContent : "";
      var fileName = rows[0] ? rows[0].querySelector(".nm").textContent : "";
      out.modalTitle = title;
      out.rowCount = rows.length;
      out.isHtmlFile = /\.html$/.test(fileName);
      var expectedHtml = Studio.exportCDF(Studio.Explore.analysisSpec(a), window.__STUDIO_STATE.assets, window.__STUDIO_STATE.settings.deployPath);
      out.hasThisChartType = expectedHtml.indexOf('"type":"donut"') >= 0;
      out.noKpis = expectedHtml.indexOf('"kpis":[]') >= 0;
      var ov = document.querySelector(".modal-ov"); if (ov) ov.remove();
      Studio.Workspace.remove("analyses", a.id, { silent: true });
      Studio.Workspace.notify("*");
      window.__studioShellSetSection("studio");
      return out;
    });
    ok("LF57: each row carries an Export action (make a saved View standalone, no open dashboard needed)",
      lf57Export.exportBtnExists, JSON.stringify(lf57Export));
    ok("LF57: Export opens the same single-file 'Embed View' modal as the in-canvas panel export, without navigating away from Views",
      lf57Export.stillOnViews && lf57Export.rowCount === 1 && lf57Export.isHtmlFile && /Embed View/.test(lf57Export.modalTitle),
      JSON.stringify(lf57Export));
    ok("LF57: the exported HTML is the self-contained single-View spec (this chart type, no KPIs) — LF57 is now fully done",
      lf57Export.hasThisChartType && lf57Export.noKpis, JSON.stringify(lf57Export));

    // ── LF51 (command center): Repository's ＋ New ▾ creates EVERY object kind ─────────
    // Each entry routes into that kind's own builder/editor (dashboard → Studio blank spec,
    // View → Explore fresh analysis, dataset/connection/job → their real editor modals), and
    // the "New dashboard" entry is role-gated the same way Home's card is.
    const lf51NewA = await page.evaluate(function () {
      window.__studioShellSetSection("repository");
      window.__studioRenderRepository();
      var btn = document.getElementById("repoNewBtn"), menu = document.getElementById("repoNewMenu");
      if (!btn || !menu) return { err: "missing btn/menu" };
      var kinds = Array.from(menu.querySelectorAll("[data-repo-new]")).map(function (b) { return b.getAttribute("data-repo-new"); });
      var dashVisible = !menu.querySelector('[data-repo-new="dashboard"]').hidden;
      btn.click();
      var opened = menu.classList.contains("open");
      menu.querySelector('[data-repo-new="dataset"]').click();
      var m = document.querySelector(".modal-h");
      return { kinds: kinds.join(","), dashVisible: dashVisible, opened: opened,
        menuClosedAfterPick: !menu.classList.contains("open"), dsTitle: m ? m.textContent : null };
    });
    ok("LF51 (command center): Repository's ＋ New ▾ lists all five object kinds and 'New dataset' opens the real dataset editor",
      lf51NewA.kinds === "dashboard,view,dataset,connection,job" && lf51NewA.dashVisible &&
      lf51NewA.opened && lf51NewA.menuClosedAfterPick && lf51NewA.dsTitle === "New dataset",
      JSON.stringify(lf51NewA));
    await page.evaluate(function () { var x = document.querySelector(".modal .x"); if (x) x.click(); });
    await page.waitForTimeout(120);

    const lf51NewJob = await page.evaluate(function () {
      var btn = document.getElementById("repoNewBtn"), menu = document.getElementById("repoNewMenu");
      btn.click(); menu.querySelector('[data-repo-new="job"]').click();
      var m = document.querySelector(".modal-h");
      return { jobTitle: m ? m.textContent : null };
    });
    await page.evaluate(function () { var x = document.querySelector(".modal .x"); if (x) x.click(); });
    await page.waitForTimeout(120);
    const lf51NewConn = await page.evaluate(function () {
      var btn = document.getElementById("repoNewBtn"), menu = document.getElementById("repoNewMenu");
      btn.click(); menu.querySelector('[data-repo-new="connection"]').click();
      var m = document.querySelector(".modal-h");
      return { connTitle: m ? m.textContent : null };
    });
    await page.evaluate(function () { var x = document.querySelector(".modal .x"); if (x) x.click(); });
    await page.waitForTimeout(120);
    ok("LF51 (command center): 'New job' and 'New connection' open their own real editors from Repository",
      lf51NewJob.jobTitle === "New job" && lf51NewConn.connTitle === "New connection",
      JSON.stringify({ job: lf51NewJob, conn: lf51NewConn }));

    const lf51NewView = await page.evaluate(function () {
      // Seed a stale loaded-analysis state so the test proves startNew actually resets it.
      window.__studioExplore.state.analysisId = "lf51-stale"; window.__studioExplore.state.name = "Stale";
      window.__studioShellSetSection("repository");
      var btn = document.getElementById("repoNewBtn"), menu = document.getElementById("repoNewMenu");
      btn.click(); menu.querySelector('[data-repo-new="view"]').click();
      return { sec: window.__studioShellGetSection(), analysisId: window.__studioExplore.state.analysisId,
        name: window.__studioExplore.state.name };
    });
    ok("LF51 (command center): 'New View' routes to Explore (the View builder) with a genuinely fresh analysis state",
      lf51NewView.sec === "explore" && lf51NewView.analysisId === null && lf51NewView.name === "",
      JSON.stringify(lf51NewView));

    const lf51NewDash = await page.evaluate(function () {
      window.__lf51SpecBackup = JSON.stringify(window.__STUDIO_STATE.spec); // restored below
      window.__studioShellSetSection("repository");
      var btn = document.getElementById("repoNewBtn"), menu = document.getElementById("repoNewMenu");
      btn.click(); menu.querySelector('[data-repo-new="dashboard"]').click();
      var sp = window.__STUDIO_STATE.spec;
      return { sec: window.__studioShellGetSection(), panels: (sp.panels || []).length,
        kpis: (sp.kpis || []).length, title: sp.title || "" };
    });
    ok("LF51 (command center): 'New dashboard' enters Studio with a fresh blank spec",
      lf51NewDash.sec === "studio" && lf51NewDash.panels === 0 && lf51NewDash.kpis === 0 && /untitled/i.test(lf51NewDash.title),
      JSON.stringify(lf51NewDash));
    await page.evaluate(function () {
      try { window.__STUDIO_STATE.spec = JSON.parse(window.__lf51SpecBackup); delete window.__lf51SpecBackup; } catch (e) {}
      if (window.__studioSelectDashboard) window.__studioSelectDashboard();
    });
    await page.waitForTimeout(80);

    // Role gate: a viewer-role account must not see the "New dashboard" entry (it routes
    // through enterStudio(), which a viewer can never pass — LF44's no-dead-clicks rule).
    const lf51NewGate = await page.evaluate(function () {
      var prev = window.PolecatAuth.current();
      window.PolecatAuth.login("demo"); // seeded viewer account
      window.__studioRenderRepository();
      var hiddenForViewer = document.querySelector('#repoNewMenu [data-repo-new="dashboard"]').hidden;
      if (prev && prev.u && prev.u !== "local") window.PolecatAuth.login(prev.u); else window.PolecatAuth.logout();
      window.__studioRenderRepository();
      var backVisible = !document.querySelector('#repoNewMenu [data-repo-new="dashboard"]').hidden;
      window.__studioShellSetSection("studio");
      return { hiddenForViewer: hiddenForViewer, backVisible: backVisible };
    });
    ok("LF51 (command center): the 'New dashboard' entry hides for a viewer-role account and returns for a developing one",
      lf51NewGate.hiddenForViewer && lf51NewGate.backVisible, JSON.stringify(lf51NewGate));

    // ── LF51 (Explore navigator): the dataset picker is a multi-level tree, not a flat list ──
    // Your datasets group by folder (nested via "/", unfiled rows after folders), sample data
    // groups by set (collapsed by default once you have your own datasets), every branch
    // collapses/expands, and a search query flattens the tree so name-finding never depends
    // on knowing where something is filed. Every row stays in the DOM (hooks unchanged).
    const lf51XpTree = await page.evaluate(function () {
      window.__studioShellSetSection("explore");
      var conn = Studio.Workspace.put("connections", { name: "lf51xp-conn", adapter: "turso", cfg: {} });
      var d1 = Studio.Workspace.put("datasets", { name: "lf51xp-filed", connectionId: conn.id, kind: "sql", sql: "select 1", folder: "TreeT/Nested" });
      var d2 = Studio.Workspace.put("datasets", { name: "lf51xp-unfiled", connectionId: conn.id, kind: "sql", sql: "select 1" });
      window.__lf51xp = { conn: conn.id, d1: d1.id, d2: d2.id };
      window.__studioExplore.render();
      var body = document.getElementById("xpBody");
      var heads = Array.from(body.querySelectorAll(".xp-tree-h")).map(function (h) { return h.getAttribute("data-xp-tree"); });
      var sampleHead = body.querySelector('.xp-tree-h[data-xp-tree^="sample:"]');
      return {
        hasTop: heads.indexOf("TreeT") >= 0,
        hasNested: heads.indexOf("TreeT/Nested") >= 0,
        grpLabels: Array.from(body.querySelectorAll(".xp-grp-h")).map(function (g) { return g.textContent.trim().split(/\s/)[0]; }).join("|"),
        filedRowInTree: !!body.querySelector('.xp-tree-kids [data-xp-ds$="' + d1.id + '"]'),
        sampleCollapsedByDefault: sampleHead ? sampleHead.getAttribute("aria-expanded") === "false" : null,
        sampleRowsStillInDom: body.querySelectorAll('[data-xp-ds^="sample"]').length > 0
      };
    });
    ok("LF51 (Explore navigator): folders render as a nested tree (parent + child headers), filed rows inside, sample sets grouped + default-collapsed with rows still in the DOM",
      lf51XpTree.hasTop && lf51XpTree.hasNested && lf51XpTree.grpLabels === "Your|Sample" &&
      lf51XpTree.filedRowInTree && lf51XpTree.sampleCollapsedByDefault === true && lf51XpTree.sampleRowsStillInDom,
      JSON.stringify(lf51XpTree));

    const lf51XpToggle = await page.evaluate(function () {
      document.querySelector('#xpBody .xp-tree-h[data-xp-tree="TreeT"]').click(); // collapse (re-renders)
      var head = document.querySelector('#xpBody .xp-tree-h[data-xp-tree="TreeT"]');
      var collapsed = head.getAttribute("aria-expanded") === "false" && head.nextElementSibling.hasAttribute("hidden");
      head.click(); // expand again
      var head2 = document.querySelector('#xpBody .xp-tree-h[data-xp-tree="TreeT"]');
      var reopened = head2.getAttribute("aria-expanded") === "true" && !head2.nextElementSibling.hasAttribute("hidden");
      return { collapsed: collapsed, reopened: reopened };
    });
    ok("LF51 (Explore navigator): a branch header collapses and re-expands its children",
      lf51XpToggle.collapsed && lf51XpToggle.reopened, JSON.stringify(lf51XpToggle));

    const lf51XpSearch = await page.evaluate(function () {
      window.__studioExplore.state.q = "lf51xp-filed";
      window.__studioExplore.render();
      var body = document.getElementById("xpBody");
      var out = { noTreeWhileSearching: !body.querySelector(".xp-tree-h"),
        matchShownFlat: !!body.querySelector('[data-xp-ds$="' + window.__lf51xp.d1 + '"]') };
      window.__studioExplore.state.q = "";
      window.__studioExplore.render();
      return out;
    });
    ok("LF51 (Explore navigator): a search query flattens the tree to plain matching rows",
      lf51XpSearch.noTreeWhileSearching && lf51XpSearch.matchShownFlat, JSON.stringify(lf51XpSearch));

    await page.evaluate(function () {
      var row = document.querySelector('#xpBody .xp-tree-kids [data-xp-ds$="' + window.__lf51xp.d1 + '"]');
      if (row) row.click();
    });
    await page.waitForTimeout(400);
    const lf51XpPick = await page.evaluate(function () {
      var picked = window.__studioExplore.state.dsId === window.__lf51xp.d1;
      // cleanup: remove seeded rows, reset Explore to the fresh list, back to Studio
      Studio.Workspace.remove("datasets", window.__lf51xp.d1, { silent: true });
      Studio.Workspace.remove("datasets", window.__lf51xp.d2, { silent: true });
      Studio.Workspace.remove("connections", window.__lf51xp.conn, { silent: true });
      Studio.Workspace.notify("*");
      delete window.__lf51xp;
      if (Studio.Explore.startNew) Studio.Explore.startNew();
      window.__studioShellSetSection("studio");
      return { picked: picked };
    });
    ok("LF51 (Explore navigator): clicking a row inside a folder branch still selects that dataset (selection contract unchanged)",
      lf51XpPick.picked, JSON.stringify(lf51XpPick));

    // ── Kevin live feedback (2026-07-29): Explore saves a "View", not an "analysis" ─────
    // The LF52 widget→View rename missed the savebar's own button labels and the section
    // hero's framing sentence — the exact strings Kevin screenshotted.
    const lfViewTermHero = await page.evaluate(function () {
      window.__studioShellSetSection("explore");
      var hero = (document.querySelector("#secExplore p") || {}).textContent || "";
      var ds = document.querySelector("#xpBody [data-xp-ds]");
      if (ds) ds.click(); // open any dataset so the savebar renders
      return { heroSaysView: /save the result as a View/.test(hero), heroSaysAnalysis: /as an analysis/.test(hero) };
    });
    await page.waitForTimeout(500);
    const lfViewTermBtn = await page.evaluate(function () {
      var btn = document.getElementById("xpSaveBtn");
      var saveLbl = btn ? btn.textContent : null;
      window.__studioExplore.state.analysisId = "lfvt-x"; // a loaded View flips the label to Update
      window.__studioExplore.render();
      var btn2 = document.getElementById("xpSaveBtn");
      var updLbl = btn2 ? btn2.textContent : null;
      Studio.Explore.startNew();
      window.__studioShellSetSection("studio");
      return { saveLbl: saveLbl, updLbl: updLbl };
    });
    ok("Kevin live: Explore's hero copy frames the saved result as a 'View' (not 'an analysis')",
      lfViewTermHero.heroSaysView && !lfViewTermHero.heroSaysAnalysis, JSON.stringify(lfViewTermHero));
    ok("Kevin live: the savebar button reads 'Save View' / 'Update View'",
      lfViewTermBtn.saveLbl === "Save View" && lfViewTermBtn.updLbl === "Update View", JSON.stringify(lfViewTermBtn));

    // ── Kevin live feedback (2026-07-29, phone screenshot): Settings' connected-backend row ──
    // At 390px the row's four action buttons crushed the backend name to a letter-per-line
    // sliver and pushed "Switch backend" off-screen. The row now wraps: actions get their own
    // full-width line, the name stays readable, and every button stays inside the viewport.
    const wsPhone = await browser.newPage({ viewport: { width: 390, height: 780 } });
    await wsPhone.addInitScript(() => { try {
      sessionStorage.setItem("studio-gate-ok", "1");
      localStorage.setItem("studio-welcome-seen", "1");
      localStorage.setItem("studio-shell-section", "settings");
      // the /__supabase mock harness makes this a REAL connected remote backend, so the row
      // renders the full Refresh/Edit/Disconnect/Switch-backend cluster the screenshot shows
      localStorage.setItem("analytics.datasource.v1", JSON.stringify({ sourceId: "supabase", cfg: { url: location.origin + "/__supabase", key: "sb_publishable_valid" }, at: 1 }));
    } catch (e) {} });
    await wsPhone.goto(`http://localhost:${PORT}/app/`, { waitUntil: "networkidle" });
    await wsPhone.waitForTimeout(700);
    const wsRow = await wsPhone.evaluate(() => {
      var row = document.querySelector("#secSettings .ws-current");
      if (!row) return { err: "no .ws-current row" };
      var name = row.querySelector(".cx-name");
      var switchBtn = document.getElementById("wsSwitchBtn");
      var vw = window.innerWidth;
      return {
        wraps: getComputedStyle(row).flexWrap === "wrap",
        fourButtons: row.querySelectorAll(".ws-actions .btn").length === 4,
        nameReadable: name.getBoundingClientRect().width > 80,
        rowInViewport: row.getBoundingClientRect().right <= vw + 1,
        switchBtnOnScreen: !!switchBtn && switchBtn.getBoundingClientRect().right <= vw + 1
      };
    });
    await wsPhone.close();
    ok("Kevin live (phone): the connected-backend row wraps at 390px — name readable, all four actions incl. 'Switch backend' on-screen",
      wsRow.wraps && wsRow.fourButtons && wsRow.nameReadable && wsRow.rowInViewport && wsRow.switchBtnOnScreen,
      JSON.stringify(wsRow));

    // LF51 (nav IA spec (b), "right-aligned filter pills"): the Datasets/Connections/Jobs
    // filter pill strips (folder + facet filters) carry .cx-filter-strip and right-align their
    // pills at desktop widths (falling back to left-align on ≤640px phones).
    const lf51Pills = await page.evaluate(function () {
      window.__studioShellSetSection("datasets");
      var conn = Studio.Workspace.put("connections", { name: "lf51b-conn", adapter: "turso", cfg: {} });
      var ds = Studio.Workspace.put("datasets", { name: "lf51b-ds", connectionId: conn.id, kind: "sql", sql: "select 1", tags: ["alpha"] });
      window.__studioRenderDatasets();
      var strip = document.querySelector('#dsxResults .cx-filter-strip.cx-pills');
      var out = {
        stripFound: !!strip,
        justify: strip ? getComputedStyle(strip).justifyContent : null,
        narrow: window.innerWidth <= 640
      };
      Studio.Workspace.remove("datasets", ds.id, { silent: true });
      Studio.Workspace.remove("connections", conn.id, { silent: true });
      Studio.Workspace.notify("*");
      window.__studioShellSetSection("studio");
      return out;
    });
    ok("LF51: the facet filter pill strip is right-aligned (.cx-filter-strip, flex-end on desktop)",
      lf51Pills.stripFound && (lf51Pills.justify === "flex-end" || lf51Pills.narrow), JSON.stringify(lf51Pills));

    // library integration: the dataset shows as a draggable card and imports as a linked, self-contained DA
    await page.evaluate(function () { window.__studioShellSetSection("studio"); });
    await page.waitForTimeout(120);
    const dsxLib = await page.evaluate(function () {
      window.__studioLoad({ title: "DS test", panels: [], kpis: [] });
      var group = document.querySelector("#libList .lib-wsds");
      var card = group && group.querySelector(".da");
      return { group: !!group, card: !!card, cardText: card ? card.textContent.slice(0, 80) : "" };
    });
    ok("DSX: the library pins a Workspace datasets group with the dataset card", dsxLib.group && dsxLib.card && /sales_by_region/.test(dsxLib.cardText), JSON.stringify(dsxLib));

    // LF66 (5) slice 1: the Workspace datasets library group is renamed "Datasets" and its
    // cards are compact — name + meta by default, with the column-chip wall + the +chart
    // quick-adds collapsed (max-height:0) until hover/focus, not an always-on wall of chips.
    const lf66Lib = await page.evaluate(function () {
      var group = document.querySelector("#libList .lib-wsds");
      var header = group && group.querySelector(".h .nm");
      var card = group && group.querySelector(".da");
      var add = card && card.querySelector(".da-add");
      var cols = card && card.querySelector(".da-cols");
      return {
        headerLabel: header ? header.textContent : null,
        addCollapsed: add ? getComputedStyle(add).maxHeight === "0px" : null,
        colsCollapsed: cols ? getComputedStyle(cols).maxHeight === "0px" : null,
        addHasChips: add ? add.querySelectorAll(".chip").length > 0 : null
      };
    });
    ok("LF66: the Workspace datasets library group is renamed to 'Datasets'",
      lf66Lib.headerLabel === "Datasets", JSON.stringify(lf66Lib));
    ok("LF66: its cards are compact — the +chart quick-adds and column chips collapse until hover",
      lf66Lib.addCollapsed === true && lf66Lib.colsCollapsed === true && lf66Lib.addHasChips === true,
      JSON.stringify(lf66Lib));

    // LF66 (6): a library dataset card dragged onto the canvas lands as a panel. The preview
    // iframe used to swallow the drag; now #preview goes pointer-transparent while a drag is in
    // progress (body.lib-dragging) so #canvas-stage's existing {wsDataset} drop handler fires.
    const lf66Drop = await page.evaluate(function () {
      var conn = Studio.Workspace.put("connections", { name: "lf66drop-conn", adapter: "turso", cfg: {} });
      var ds = Studio.Workspace.put("datasets", { name: "lf66drop-ds", connectionId: conn.id, kind: "sql", sql: "select region, sales from t", columns: ["region", "sales"] });
      window.__studioLoad({ title: "drop test", panels: [], kpis: [] });
      var stage = document.getElementById("canvas-stage");
      var preview = document.getElementById("preview");
      // 1) the drag-through mechanism: with body.lib-dragging the iframe ignores pointer events
      document.body.classList.add("lib-dragging");
      var pePassthrough = getComputedStyle(preview).pointerEvents === "none";
      document.body.classList.remove("lib-dragging");
      // 2) the drop itself lands a panel via the existing #canvas-stage handler
      var before = window.__STUDIO_STATE.spec.panels.length;
      var dt = new DataTransfer();
      dt.setData("text/plain", JSON.stringify({ wsDataset: ds.id }));
      stage.dispatchEvent(new DragEvent("drop", { bubbles: true, cancelable: true, dataTransfer: dt }));
      var after = window.__STUDIO_STATE.spec.panels.length;
      Studio.Workspace.remove("datasets", ds.id, { silent: true });
      Studio.Workspace.remove("connections", conn.id, { silent: true });
      Studio.Workspace.notify("*");
      // restore the clean spec the next test (dsxImport) was written against
      window.__studioLoad({ title: "DS test", panels: [], kpis: [] });
      return { pePassthrough: pePassthrough, before: before, after: after };
    });
    ok("LF66: dragging a library card onto the canvas is not swallowed by the preview iframe (pointer-events pass through)",
      lf66Drop.pePassthrough === true, JSON.stringify(lf66Drop));
    ok("LF66: dropping a dataset on the canvas adds a panel via the existing drop handler",
      lf66Drop.after === lf66Drop.before + 1, JSON.stringify(lf66Drop));

    // LF66 (6): the drop AUTO-PICKS the best-fit chart from the dataset's columns (via chartForDA)
    // instead of always a bare bars panel — a dataset with a time column drops in as a line chart.
    const lf66AutoView = await page.evaluate(function () {
      var conn = Studio.Workspace.put("connections", { name: "lf66av-conn", adapter: "turso", cfg: {} });
      var tsDs = Studio.Workspace.put("datasets", { name: "lf66av-ts", connectionId: conn.id, kind: "sql", sql: "select month, sales from t", columns: ["month", "sales"] });
      var catDs = Studio.Workspace.put("datasets", { name: "lf66av-cat", connectionId: conn.id, kind: "sql", sql: "select region, sales from t", columns: ["region", "sales"] });
      window.__studioLoad({ title: "auto-view test", panels: [], kpis: [] });
      // no explicit type → auto-pick
      window.__studioAddFromWorkspaceDataset(tsDs.id);
      var tsType = ((window.__STUDIO_STATE.spec.panels.slice(-1)[0] || {}).chart || {}).type;
      window.__studioAddFromWorkspaceDataset(catDs.id);
      var catType = ((window.__STUDIO_STATE.spec.panels.slice(-1)[0] || {}).chart || {}).type;
      Studio.Workspace.remove("datasets", tsDs.id, { silent: true });
      Studio.Workspace.remove("datasets", catDs.id, { silent: true });
      Studio.Workspace.remove("connections", conn.id, { silent: true });
      Studio.Workspace.notify("*");
      window.__studioLoad({ title: "DS test", panels: [], kpis: [] });
      return { tsType: tsType, catType: catType };
    });
    ok("LF66: a dropped dataset auto-picks its best chart — a time column → line, plain categorical → bars",
      lf66AutoView.tsType === "line" && lf66AutoView.catType === "bars", JSON.stringify(lf66AutoView));
    const dsxImport = await page.evaluate(function () {
      var ds = Studio.Workspace.all("datasets")[0];
      window.__studioAddFromWorkspaceDataset(ds.id, "bars");
      var spec = window.__STUDIO_STATE.spec;
      var da = spec.cda.dataAccesses[0];
      return {
        das: spec.cda.dataAccesses.length, panels: spec.panels.length,
        linked: da && da.datasetId === ds.id && da.connectionId === "conn-mock",
        selfContained: da && /\{\{schema\}\}/.test(da.dataset.sql) && da.kind === "sql",
        cols: da && (da.columns || []).join(","),
        panelBound: spec.panels[0] && spec.panels[0].chart.da === da.id
      };
    });
    ok("DSX: importing a dataset creates a linked, self-contained data access bound to the new panel",
      dsxImport.das === 1 && dsxImport.panels === 1 && dsxImport.linked && dsxImport.selfContained &&
      dsxImport.cols === "region,total" && dsxImport.panelBound, JSON.stringify(dsxImport));

    // drag a dataset onto Home (post-overhaul backlog item 6): the Datasets
    // catalog row is draggable and its payload matches what Home's "Blank
    // dashboard" tile accepts to start a new, seeded dashboard.
    await page.evaluate(function () { window.__studioShellSetSection("datasets"); });
    await page.waitForTimeout(120);
    const dsxDragStart = await page.evaluate(function () {
      var row = document.querySelector("#dsxResults .cx-row");
      var payload = null;
      var fakeEvt = Object.assign(new Event("dragstart", { bubbles: true }), {
        dataTransfer: { setData: function (type, v) { if (type === "text/plain") payload = v; }, effectAllowed: "" }
      });
      row.dispatchEvent(fakeEvt);
      return { draggable: row.getAttribute("draggable"), payload: payload, dsId: Studio.Workspace.all("datasets")[0].id };
    });
    ok("DSX: a dataset row is draggable and carries the {wsDataset} payload the canvas/Home drops understand",
      dsxDragStart.draggable === "true" && dsxDragStart.payload === JSON.stringify({ wsDataset: dsxDragStart.dsId }),
      JSON.stringify(dsxDragStart));

    // QA-07 (FRONTEND_QA_REPORT_2026-07-24.md): same fix as Connections — the row is a
    // plain container (no role="button"/tabindex), and clicking its title button (the
    // one real <button> in the row) opens the dataset editor.
    const dsxRowSemantics = await page.evaluate(function () {
      var row = document.querySelector("#dsxResults .cx-row");
      var titleBtn = row.querySelector(".cx-name > .cx-title-btn");
      var name = row.querySelector(".cx-name b").textContent;
      return {
        noRoleOrTabindex: !row.hasAttribute("role") && !row.hasAttribute("tabindex"),
        titleIsButton: !!titleBtn && titleBtn.tagName === "BUTTON",
        noNestedInteractive: !!titleBtn && !titleBtn.querySelector("button,a,[role=button],[tabindex]"),
        titleAttrNamesRow: !!titleBtn && titleBtn.title.indexOf(name) === 0
      };
    });
    ok("QA-07: a dataset row is a plain container whose title is a real <button> with no nested interactive descendants",
      dsxRowSemantics.noRoleOrTabindex && dsxRowSemantics.titleIsButton && dsxRowSemantics.noNestedInteractive, JSON.stringify(dsxRowSemantics));
    ok("Track H: a dataset row's title button exposes the dataset's own name via its native title attribute (truncation escape hatch)",
      dsxRowSemantics.titleAttrNamesRow, JSON.stringify(dsxRowSemantics));
    const dsxTitleBtnOpens = await page.evaluate(function () {
      document.querySelector("#dsxResults .cx-row .cx-title-btn").click();
      return { title: (document.querySelector(".modal-h") || {}).textContent };
    });
    ok("QA-07: clicking a dataset row's title button opens its editor", dsxTitleBtnOpens.title === "Edit dataset", JSON.stringify(dsxTitleBtnOpens));
    await page.evaluate(function () { document.querySelector(".modal-ov .x").click(); });
    await page.waitForTimeout(60);

    await page.evaluate(function () { window.__studioShellSetSection("home"); });
    await page.waitForTimeout(150);
    const dsxHomeDrop = await page.evaluate(function () {
      var ds = Studio.Workspace.all("datasets")[0];
      var card = document.querySelector('#secHome .home-card[data-home="blank"]');
      var dragoverEvt = Object.assign(new Event("dragover", { bubbles: true, cancelable: true }), { dataTransfer: { dropEffect: "" } });
      card.dispatchEvent(dragoverEvt);
      var hadClassOnDragover = card.classList.contains("dragover");
      var dropEvt = Object.assign(new Event("drop", { bubbles: true, cancelable: true }), {
        dataTransfer: { getData: function () { return JSON.stringify({ wsDataset: ds.id }); } }
      });
      card.dispatchEvent(dropEvt);
      var spec = window.__STUDIO_STATE.spec;
      var da = spec.cda.dataAccesses[0];
      return {
        hadClassOnDragover: hadClassOnDragover,
        classClearedAfterDrop: !card.classList.contains("dragover"),
        panels: spec.panels.length,
        linked: da && da.datasetId === ds.id
      };
    });
    ok("Home: dropping a dataset on “Blank dashboard” starts a new dashboard seeded with it",
      dsxHomeDrop.hadClassOnDragover && dsxHomeDrop.classClearedAfterDrop && dsxHomeDrop.panels === 1 && dsxHomeDrop.linked,
      JSON.stringify(dsxHomeDrop));

    // dataset lineage (post-overhaul backlog item 5, "blast-radius view"): the
    // Datasets catalog badges each row with the dashboards that reference it,
    // and warns about them before a delete.
    await page.evaluate(function () { window.__studioShellSetSection("datasets"); });
    await page.waitForTimeout(120);
    const dsxLineageBefore = await page.evaluate(function () {
      return { badge: !!document.querySelector("#dsxResults .cx-lineage") };
    });
    ok("DSX: no lineage badge while a dataset isn't saved into any dashboard yet",
      !dsxLineageBefore.badge, JSON.stringify(dsxLineageBefore));

    await page.evaluate(function () {
      var ds = Studio.Workspace.all("datasets")[0];
      Studio.Workspace.put("dashboards", {
        id: "dash-lineage", ts: new Date().toISOString(), title: "Sales overview", name: "",
        spec: { title: "Sales overview", cda: { dataAccesses: [{ id: "da1", datasetId: ds.id }] }, panels: [], kpis: [] }
      }, { silent: true }); // silent: a dashboards-table write isn't in renderDatasets' auto-refresh filter (datasets/connections/*)
      window.__studioRenderDatasets();
    });
    await page.waitForTimeout(120);
    const dsxLineageAfter = await page.evaluate(function () {
      var badge = document.querySelector("#dsxResults .cx-lineage");
      // UX8 slice 2: the badge's naming detail now lives in a hydrated data-tip
      // tooltip (aria-label + .ps-tip-bub), not a native title= (see tooltip.js).
      return { present: !!badge, text: badge ? badge.textContent : "", ariaLabel: badge ? badge.getAttribute("aria-label") : "" };
    });
    ok("DSX: a dataset linked from a saved dashboard shows a '↪ N dashboards' badge naming it",
      dsxLineageAfter.present && /1 dashboard/.test(dsxLineageAfter.text) && /Sales overview/.test(dsxLineageAfter.ariaLabel), JSON.stringify(dsxLineageAfter));

    const dsxDelWarn = await page.evaluate(function () {
      var msg = "";
      window.confirm = function (m) { msg = m; return false; }; // cancel — don't actually delete
      var d = Studio.Workspace.all("datasets")[0];
      document.querySelector('[data-dsx-del="' + d.id + '"]').click();
      return { msg: msg, stillThere: !!Studio.Workspace.get("datasets", d.id) };
    });
    ok("DSX: deleting a dataset in use warns which dashboards reference it, and a cancel keeps it",
      /Sales overview/.test(dsxDelWarn.msg) && /1 dashboard/.test(dsxDelWarn.msg) && dsxDelWarn.stillThere, JSON.stringify(dsxDelWarn));

    // saved views (post-overhaul backlog item 6, "jobtracker pattern"): capture the
    // current search + adapter/tag pill selection as a named, reusable preset. Lives
    // in Workspace SETTINGS (same home as workbooks), so it travels with sync and needs
    // no separate "Clear local data" entry.
    const dsxViewsNone = await page.evaluate(function () { return { addBtn: !!document.querySelector("#dsxViewAddBtn") }; });
    ok("DSX: no '+ Save view' affordance while search + filters are both empty",
      !dsxViewsNone.addBtn, JSON.stringify(dsxViewsNone));

    await page.evaluate(function () {
      var inp = document.querySelector("#dsxSearch");
      inp.value = "sales"; inp.dispatchEvent(new Event("input"));
    });
    await page.waitForTimeout(60);
    await page.evaluate(function () { document.querySelector('[data-dsx-tag="finance"]').click(); });
    await page.waitForTimeout(60);
    await page.evaluate(function () {
      document.querySelector("#dsxViewNameInp").value = "Finance sales";
      document.querySelector("#dsxViewAddBtn").click();
    });
    await page.waitForTimeout(60);
    const dsxViewSaved = await page.evaluate(function () {
      var views = Studio.Workspace.settings().datasetViews || [];
      return {
        count: views.length, name: views[0] && views[0].name, q: views[0] && views[0].q,
        tags: views[0] && (views[0].tags || []).join(","),
        chip: !!document.querySelector("[data-dsx-view]"),
        chipText: (document.querySelector("[data-dsx-view] .wb-chip-label") || {}).textContent
      };
    });
    ok("DSX: '+ Save view' persists the current search + tag filter under a name, and renders a chip",
      dsxViewSaved.count === 1 && dsxViewSaved.name === "Finance sales" && dsxViewSaved.q === "sales" &&
      dsxViewSaved.tags === "finance" && dsxViewSaved.chip && dsxViewSaved.chipText === "Finance sales", JSON.stringify(dsxViewSaved));

    // clear both the search box and the pill filter, then applying the saved view restores both
    await page.evaluate(function () {
      var inp = document.querySelector("#dsxSearch");
      inp.value = ""; inp.dispatchEvent(new Event("input"));
    });
    await page.waitForTimeout(60);
    await page.evaluate(function () { document.querySelector("#dsxPillClear").click(); });
    await page.waitForTimeout(60);
    const dsxViewCleared = await page.evaluate(function () {
      return { q: document.querySelector("#dsxSearch").value, tagActive: !!document.querySelector('[data-dsx-tag="finance"].active') };
    });
    ok("DSX: search + pill filter actually cleared before applying the saved view",
      dsxViewCleared.q === "" && !dsxViewCleared.tagActive, JSON.stringify(dsxViewCleared));

    await page.evaluate(function () { document.querySelector("[data-dsx-view]").click(); });
    await page.waitForTimeout(60);
    const dsxViewApplied = await page.evaluate(function () {
      return { q: document.querySelector("#dsxSearch").value, tagActive: !!document.querySelector('[data-dsx-tag="finance"].active') };
    });
    ok("DSX: clicking a saved-view chip restores its search text and tag filter",
      dsxViewApplied.q === "sales" && dsxViewApplied.tagActive, JSON.stringify(dsxViewApplied));

    const dsxViewDel = await page.evaluate(function () {
      window.confirm = function () { return true; };
      document.querySelector("[data-dsx-view-del]").click();
      return { count: (Studio.Workspace.settings().datasetViews || []).length, chip: !!document.querySelector("[data-dsx-view]") };
    });
    ok("DSX: deleting a saved view removes it from settings and the chip row",
      dsxViewDel.count === 0 && !dsxViewDel.chip, JSON.stringify(dsxViewDel));

    await page.evaluate(function () {
      var inp = document.querySelector("#dsxSearch");
      inp.value = ""; inp.dispatchEvent(new Event("input"));
      // dsxViewDel above only cleared the search text, not the tag/adapter pill
      // state the deleted view had applied — clear it explicitly so the next
      // check isn't hidden behind a stale "finance" tag filter.
      var clearBtn = document.querySelector("#dsxPillClear");
      if (clearBtn) clearBtn.click();
    });
    await page.waitForTimeout(60);

    // pin/favorite (post-overhaul backlog item 7, "organization at scale"):
    // pinning sorts a dataset to the top of the list and persists the flag,
    // same contract as the CX connection-pinning check above.
    const dsxPin = await page.evaluate(function () {
      var existing = Studio.Workspace.all("datasets")[0];
      Studio.Workspace.put("datasets", { id: "d-second", name: "z_other_dataset", connectionId: existing.connectionId, kind: "sql", sql: "SELECT 1" });
      window.__studioRenderDatasets();
      var beforeOrder = [].slice.call(document.querySelectorAll("#dsxResults .cx-row")).map(function (r) { return r.getAttribute("data-dsx-id"); });
      var btn = document.querySelector('[data-dsx-pin="' + existing.id + '"]');
      var beforeOn = btn.classList.contains("on");
      btn.click();
      var afterOrder = [].slice.call(document.querySelectorAll("#dsxResults .cx-row")).map(function (r) { return r.getAttribute("data-dsx-id"); });
      var afterBtn = document.querySelector('[data-dsx-pin="' + existing.id + '"]');
      return {
        beforeOrder: beforeOrder, afterOrder: afterOrder, beforeOn: beforeOn,
        afterOn: afterBtn.classList.contains("on"), ariaAfter: afterBtn.getAttribute("aria-pressed"),
        stored: !!Studio.Workspace.get("datasets", existing.id).pinned, existingId: existing.id
      };
    });
    ok("DSX: pinning a dataset moves it to the top of the list and persists the flag",
      !dsxPin.beforeOn && dsxPin.afterOn && dsxPin.ariaAfter === "true" && dsxPin.stored &&
      dsxPin.beforeOrder[1] === dsxPin.existingId && dsxPin.afterOrder[0] === dsxPin.existingId, JSON.stringify(dsxPin));

    // M6 "favorites-with-thumbnails": pinning a dataset AND a connection surfaces both as
    // cards in a new Home section (reusing the pinnedAnalyses card treatment), each opening
    // its own editor on click — same pattern as the analysis-pin → Home-card → Explore check above.
    const homeFav = await page.evaluate(function (existingId) {
      window.__studioShellSetSection("connections");
      var connBtn = document.querySelector('[data-conn-pin="conn-mock"]');
      var connBeforeOn = connBtn ? connBtn.classList.contains("on") : null;
      if (connBtn) connBtn.click();
      window.__studioShellSetSection("home");
      var dsCard = document.querySelector('[data-home-fav="' + existingId + '"]');
      var cxCard = document.querySelector('[data-home-fav="conn-mock"]');
      return {
        hadConnBtn: !!connBtn, connBeforeOn: connBeforeOn,
        dsCardFound: !!dsCard, cxCardFound: !!cxCard,
        dsLabel: dsCard ? dsCard.querySelector(".home-feat-h span").textContent : null,
        cxLabel: cxCard ? cxCard.querySelector(".home-feat-h span").textContent : null
      };
    }, dsxPin.existingId);
    ok("M6 favorites: pinning a dataset and a connection surfaces both as cards on Home",
      homeFav.hadConnBtn && !homeFav.connBeforeOn && homeFav.dsCardFound && homeFav.cxCardFound &&
      homeFav.dsLabel === "Dataset" && homeFav.cxLabel === "Connection", JSON.stringify(homeFav));

    const homeFavOpen = await page.evaluate(function (id) {
      document.querySelector('[data-home-fav-dataset="' + id + '"]').click();
      var modalTitle = (document.querySelector(".modal-h") || {}).textContent || "";
      document.querySelector(".modal-h .x").click();
      return { modalTitle: modalTitle, modalGone: !document.querySelector(".modal-ov") };
    }, dsxPin.existingId);
    ok("M6 favorites: clicking a favorite dataset's card opens its editor",
      homeFavOpen.modalTitle === "Edit dataset" && homeFavOpen.modalGone, JSON.stringify(homeFavOpen));

    await page.evaluate(function () {
      window.__studioShellSetSection("connections");
      var btn = document.querySelector('[data-conn-pin="conn-mock"]');
      if (btn) btn.click(); // restore: unpin the connection so it doesn't affect later checks
      window.__studioShellSetSection("datasets");
    });

    const dsxUnpin = await page.evaluate(function () {
      var existing = Studio.Workspace.all("datasets").filter(function (d) { return d.id !== "d-second"; })[0];
      document.querySelector('[data-dsx-pin="' + existing.id + '"]').click();
      var r = Studio.Workspace.get("datasets", existing.id);
      return { pinned: !!r.pinned, pinnedAt: r.pinnedAt };
    });
    ok("DSX: unpinning a dataset clears both pinned and pinnedAt",
      !dsxUnpin.pinned && dsxUnpin.pinnedAt === undefined, JSON.stringify(dsxUnpin));

    // by-connection filter (post-overhaul backlog item 7 follow-up, "organization at
    // scale" — the still-open "cross-cutting by-connection view" this item called for).
    // Two connections sharing the SAME adapter (both "turso") get lumped into one
    // by-adapter pill above; the new by-connection pill narrows to just one of them —
    // same multi-select/saved-view plumbing as the adapter and tag strips, just keyed
    // by connectionId.
    const dsxConnPills = await page.evaluate(function () {
      Studio.Workspace.put("connections", { id: "conn-mock-2", name: "Mock warehouse 2", adapter: "turso", cfg: { url: "http://x", token: "t" } });
      Studio.Workspace.put("datasets", { id: "d-third", name: "other_conn_dataset", connectionId: "conn-mock-2", kind: "sql", sql: "SELECT 1" });
      window.__studioRenderDatasets();
      var pills = [].slice.call(document.querySelectorAll("[data-dsx-conn]")).map(function (b) {
        return { id: b.getAttribute("data-dsx-conn"), label: (b.querySelector(".wb-chip-label") || {}).textContent, n: (b.querySelector(".wb-chip-n") || {}).textContent };
      });
      return { pills: pills, rows: document.querySelectorAll("#dsxResults .cx-row").length };
    });
    ok("DSX: a 'by connection' pill appears per connection (distinct from the by-adapter pill, which lumps same-adapter connections together)",
      dsxConnPills.rows === 3 && dsxConnPills.pills.length === 2 &&
      dsxConnPills.pills.some(function (p) { return p.label === "Mock warehouse" && p.n === "2"; }) &&
      dsxConnPills.pills.some(function (p) { return p.label === "Mock warehouse 2" && p.n === "1"; }),
      JSON.stringify(dsxConnPills));

    // Folder pilot slice (#21 org sub-item, "folder tree" step 2 — a single flat
    // d.folder string alongside the existing multi-value tags): no facet row while
    // nothing has been filed, an Edit-modal "Folder" field (with a <datalist> of
    // existing names) files one in, a chip strip appears, filters the list, and
    // shows the folder as a badge on the row.
    const dsxFolderNone = await page.evaluate(function () { return { chip: !!document.querySelector("[data-dsx-folder]") }; });
    ok("DSX: no folder facet row while no dataset has been filed into one",
      !dsxFolderNone.chip, JSON.stringify(dsxFolderNone));

    await page.evaluate(function () { document.querySelector('[data-dsx-edit="d-second"]').click(); });
    await page.waitForTimeout(120);
    const dsxFolderField = await page.evaluate(function () {
      var fields = [].slice.call(document.querySelectorAll(".modal .cx-field"));
      var row = fields.filter(function (f) { return /^Folder/.test(f.textContent); })[0];
      var inp = row && row.querySelector("input");
      var datalist = row && row.querySelector("datalist");
      return { found: !!inp, hasDatalist: !!datalist, listAttr: inp && inp.getAttribute("list") };
    });
    ok("DSX: the dataset editor has a Folder field wired to a <datalist> of existing folder names",
      dsxFolderField.found && dsxFolderField.hasDatalist && dsxFolderField.listAttr === "dsxFolderOptions", JSON.stringify(dsxFolderField));

    await page.evaluate(function () {
      var fields = [].slice.call(document.querySelectorAll(".modal .cx-field"));
      var folderInp = fields.filter(function (f) { return /^Folder/.test(f.textContent); })[0].querySelector("input");
      folderInp.value = "Regional";
    });
    await page.evaluate(function () {
      [].slice.call(document.querySelectorAll(".modal .cx-wiz-foot .btn")).filter(function (b) { return /Save changes/.test(b.textContent); })[0].click();
    });
    await page.waitForTimeout(150);
    const dsxFolderSaved = await page.evaluate(function () {
      var r = Studio.Workspace.get("datasets", "d-second");
      var chip = document.querySelector('[data-dsx-folder="Regional"]');
      var badgeEl = document.querySelector('.cx-row[data-dsx-id="d-second"] .cx-folder');
      // UX8 slice 2 hydrates a .ps-tip-bub tooltip INSIDE the badge — strip it before
      // reading the badge's own visible label text (same convention LF20 uses for icons).
      var badgeClone = badgeEl ? badgeEl.cloneNode(true) : null;
      if (badgeClone) { var bub = badgeClone.querySelector(".ps-tip-bub"); if (bub) bub.remove(); }
      return {
        folder: r.folder,
        chip: !!chip, chipLabel: chip && (chip.querySelector(".wb-chip-label") || {}).textContent,
        chipN: chip && (chip.querySelector(".wb-chip-n") || {}).textContent,
        badge: !!badgeEl,
        badgeText: badgeClone ? badgeClone.textContent : null
      };
    });
    ok("DSX: saving the Folder field persists d.folder, renders a chip, and badges the row",
      dsxFolderSaved.folder === "Regional" && dsxFolderSaved.chip && dsxFolderSaved.chipLabel === "Regional" &&
      dsxFolderSaved.chipN === "1" && dsxFolderSaved.badge && dsxFolderSaved.badgeText === "Regional",
      JSON.stringify(dsxFolderSaved));

    const dsxFolderFilter = await page.evaluate(function () {
      document.querySelector('[data-dsx-folder="Regional"]').click();
      var rows = [].slice.call(document.querySelectorAll("#dsxResults .cx-row")).map(function (r) { return r.getAttribute("data-dsx-id"); });
      return { rows: rows };
    });
    ok("DSX: clicking a folder chip narrows the list to just that folder",
      dsxFolderFilter.rows.length === 1 && dsxFolderFilter.rows[0] === "d-second", JSON.stringify(dsxFolderFilter));

    const dsxFolderUnfiled = await page.evaluate(function () {
      document.querySelector('[data-dsx-folder="__unfiled"]').click();
      var rows = [].slice.call(document.querySelectorAll("#dsxResults .cx-row")).map(function (r) { return r.getAttribute("data-dsx-id"); });
      return { rows: rows, unfiledN: (document.querySelector('[data-dsx-folder="__unfiled"] .wb-chip-n') || {}).textContent };
    });
    ok("DSX: the Unfiled folder chip excludes the dataset that's been filed",
      dsxFolderUnfiled.rows.indexOf("d-second") < 0 && dsxFolderUnfiled.unfiledN === "2", JSON.stringify(dsxFolderUnfiled));

    await page.evaluate(function () { document.querySelector("#dsxPillClear").click(); });
    await page.waitForTimeout(60);
    const dsxFolderCleared = await page.evaluate(function () {
      return { rows: document.querySelectorAll("#dsxResults .cx-row").length, activeChip: !!document.querySelector("[data-dsx-folder].active[data-dsx-folder='Regional']") };
    });
    ok("DSX: Clear resets the folder filter back to all datasets",
      dsxFolderCleared.rows === 3 && !dsxFolderCleared.activeChip, JSON.stringify(dsxFolderCleared));

    const dsxConnFilter = await page.evaluate(function () {
      document.querySelector('[data-dsx-conn="conn-mock-2"]').click();
      var rows = [].slice.call(document.querySelectorAll("#dsxResults .cx-row")).map(function (r) { return r.getAttribute("data-dsx-id"); });
      var active = document.querySelector('[data-dsx-conn="conn-mock-2"]').classList.contains("active");
      return { rows: rows, active: active };
    });
    ok("DSX: clicking a connection pill filters the list down to just that connection's datasets",
      dsxConnFilter.active && dsxConnFilter.rows.length === 1 && dsxConnFilter.rows[0] === "d-third", JSON.stringify(dsxConnFilter));

    await page.evaluate(function () {
      document.querySelector("#dsxViewNameInp").value = "Second warehouse only";
      document.querySelector("#dsxViewAddBtn").click();
    });
    await page.waitForTimeout(60);
    const dsxConnViewSaved = await page.evaluate(function () {
      var views = Studio.Workspace.settings().datasetViews || [];
      return { count: views.length, connections: views[0] && (views[0].connections || []).join(",") };
    });
    ok("DSX: saving a view while a connection pill is active captures it in the view's 'connections' list",
      dsxConnViewSaved.count === 1 && dsxConnViewSaved.connections === "conn-mock-2", JSON.stringify(dsxConnViewSaved));

    await page.evaluate(function () { document.querySelector("#dsxPillClear").click(); });
    await page.waitForTimeout(60);
    const dsxConnViewApplied = await page.evaluate(function () {
      var beforeActive = !!document.querySelector('[data-dsx-conn="conn-mock-2"].active');
      document.querySelector("[data-dsx-view]").click();
      var afterActive = !!document.querySelector('[data-dsx-conn="conn-mock-2"].active');
      var rows = [].slice.call(document.querySelectorAll("#dsxResults .cx-row")).map(function (r) { return r.getAttribute("data-dsx-id"); });
      return { beforeActive: beforeActive, afterActive: afterActive, rows: rows };
    });
    ok("DSX: applying that saved view restores the connection pill filter",
      !dsxConnViewApplied.beforeActive && dsxConnViewApplied.afterActive &&
      dsxConnViewApplied.rows.length === 1 && dsxConnViewApplied.rows[0] === "d-third",
      JSON.stringify(dsxConnViewApplied));

    await page.evaluate(function () { document.querySelector("#dsxPillClear").click(); });
    await page.waitForTimeout(60);

    // "by type" filter (post-overhaul backlog item 7's optional facet, kind:
    // sql/table/file/collection/sheet) — same multi-select/saved-view shape as
    // the adapter/connection/tag pills above, just keyed by d.kind (defaulting
    // to "sql" the same way dsxRunnableDef already does).
    const dsxKindBaseline = await page.evaluate(function () {
      return { rows: document.querySelectorAll("#dsxResults .cx-row").length, sqlN: (document.querySelector('[data-dsx-kind="sql"] .wb-chip-n') || {}).textContent };
    });
    const dsxKindPills = await page.evaluate(function () {
      Studio.Workspace.put("datasets", { id: "d-fourth", name: "kind_test_table", connectionId: "conn-mock-2", kind: "table", table: "orders" });
      window.__studioRenderDatasets();
      var pills = [].slice.call(document.querySelectorAll("[data-dsx-kind]")).map(function (b) {
        return { kind: b.getAttribute("data-dsx-kind"), label: (b.querySelector(".wb-chip-label") || {}).textContent, n: (b.querySelector(".wb-chip-n") || {}).textContent };
      });
      return { pills: pills, rows: document.querySelectorAll("#dsxResults .cx-row").length };
    });
    ok("DSX: a 'by type' pill appears per dataset kind, with a friendly label, and doesn't disturb the other kinds' counts",
      dsxKindPills.rows === dsxKindBaseline.rows + 1 &&
      dsxKindPills.pills.some(function (p) { return p.kind === "sql" && p.label === "SQL query" && p.n === dsxKindBaseline.sqlN; }) &&
      dsxKindPills.pills.some(function (p) { return p.kind === "table" && p.label === "Table" && p.n === "1"; }),
      JSON.stringify({ baseline: dsxKindBaseline, after: dsxKindPills }));

    const dsxKindFilter = await page.evaluate(function () {
      document.querySelector('[data-dsx-kind="table"]').click();
      var rows = [].slice.call(document.querySelectorAll("#dsxResults .cx-row")).map(function (r) { return r.getAttribute("data-dsx-id"); });
      var active = document.querySelector('[data-dsx-kind="table"]').classList.contains("active");
      return { rows: rows, active: active };
    });
    ok("DSX: clicking a type pill filters the list down to just that kind",
      dsxKindFilter.active && dsxKindFilter.rows.length === 1 && dsxKindFilter.rows[0] === "d-fourth", JSON.stringify(dsxKindFilter));

    await page.evaluate(function () {
      document.querySelector("#dsxViewNameInp").value = "Table datasets only";
      document.querySelector("#dsxViewAddBtn").click();
    });
    await page.waitForTimeout(60);
    const dsxKindViewSaved = await page.evaluate(function () {
      var views = Studio.Workspace.settings().datasetViews || [];
      return { kinds: (views[0] && (views[0].kinds || []).join(",")) || "" };
    });
    ok("DSX: saving a view while a type pill is active captures it in the view's 'kinds' list",
      dsxKindViewSaved.kinds === "table", JSON.stringify(dsxKindViewSaved));

    await page.evaluate(function () { document.querySelector("#dsxPillClear").click(); });
    await page.waitForTimeout(60);
    const dsxKindViewApplied = await page.evaluate(function () {
      var beforeActive = !!document.querySelector('[data-dsx-kind="table"].active');
      document.querySelector("[data-dsx-view]").click(); // newest saved view (unshift) is first in DOM order
      var afterActive = !!document.querySelector('[data-dsx-kind="table"].active');
      var rows = [].slice.call(document.querySelectorAll("#dsxResults .cx-row")).map(function (r) { return r.getAttribute("data-dsx-id"); });
      return { beforeActive: beforeActive, afterActive: afterActive, rows: rows };
    });
    ok("DSX: applying that saved view restores the type pill filter",
      !dsxKindViewApplied.beforeActive && dsxKindViewApplied.afterActive &&
      dsxKindViewApplied.rows.length === 1 && dsxKindViewApplied.rows[0] === "d-fourth",
      JSON.stringify(dsxKindViewApplied));

    await page.evaluate(function () { document.querySelector("#dsxPillClear").click(); });
    await page.waitForTimeout(60);

    // LIVE-d (slice 1): multi-select + bulk delete on Datasets — generalizes LF59's
    // Dashboards pattern (session-only select mode, checkbox overlay, bulk bar with
    // Select all/Clear/Delete). Two throwaway datasets keep this from touching the
    // fixture rows other DSX tests above depend on.
    await page.evaluate(function () {
      Studio.Workspace.put("datasets", { id: "livd-bulk-a", name: "livd_bulk_a", connectionId: "conn-mock-2", kind: "sql", sql: "SELECT 1" }, { silent: true });
      Studio.Workspace.put("datasets", { id: "livd-bulk-b", name: "livd_bulk_b", connectionId: "conn-mock-2", kind: "sql", sql: "SELECT 1" }, { silent: true });
      window.__studioRenderDatasets();
    });
    await page.waitForTimeout(100);

    const livdSelectOn = await page.evaluate(function () {
      document.getElementById("dsxSelectBtn").click();
      return {
        mode: window.__studioDsxSelectMode(),
        checkboxes: document.querySelectorAll("#dsxResults .dsx-select-cb").length,
        bulkBar: !!document.querySelector(".dash-bulk-bar"),
        btnText: document.getElementById("dsxSelectBtn").textContent,
        delDisabled: document.getElementById("dsxSelDelBtn").disabled
      };
    });
    ok("LIVE-d: clicking Select enters select mode on Datasets — checkboxes + a bulk bar appear, Delete starts disabled",
      livdSelectOn.mode && livdSelectOn.checkboxes > 0 && livdSelectOn.bulkBar && /Cancel/.test(livdSelectOn.btnText) && livdSelectOn.delDisabled,
      JSON.stringify(livdSelectOn));

    // tapping a row in select mode selects it instead of opening its editor (re-query
    // after the click — its handler re-renders #dsxResults, so pre-click nodes go stale)
    const livdTapSelects = await page.evaluate(function () {
      var row = document.querySelector('.dsx-select-cb[data-dsx-select="livd-bulk-a"]').closest(".cx-row");
      row.click();
      var cbAfter = document.querySelector('.dsx-select-cb[data-dsx-select="livd-bulk-a"]');
      return {
        checked: cbAfter.checked,
        rowSelected: cbAfter.closest(".cx-row").classList.contains("is-selected"),
        selected: window.__studioDsxSelected(),
        noModalOpened: !document.querySelector(".modal-ov")
      };
    });
    ok("LIVE-d: tapping a row in select mode selects it (doesn't open the editor) and highlights the row",
      livdTapSelects.checked && livdTapSelects.rowSelected && livdTapSelects.selected.indexOf("livd-bulk-a") >= 0 && livdTapSelects.noModalOpened,
      JSON.stringify(livdTapSelects));

    // the checkbox itself is an equivalent way to toggle selection
    const livdCbToggle = await page.evaluate(function () {
      document.querySelector('.dsx-select-cb[data-dsx-select="livd-bulk-b"]').click();
      return { count: window.__studioDsxSelected().length, barText: document.querySelector(".dash-bulk-count").textContent };
    });
    ok("LIVE-d: checking a row's checkbox selects it too, and the bulk bar's count reflects the total",
      livdCbToggle.count === 2 && /2 selected/.test(livdCbToggle.barText), JSON.stringify(livdCbToggle));

    // Select all / Clear apply to everything currently in view
    const livdSelectAll = await page.evaluate(function () {
      document.getElementById("dsxSelAllBtn").click();
      var totalRows = document.querySelectorAll("#dsxResults .cx-row").length;
      return { selectedCount: window.__studioDsxSelected().length, totalRows: totalRows };
    });
    ok("LIVE-d: Select all selects every dataset currently in view",
      livdSelectAll.selectedCount === livdSelectAll.totalRows && livdSelectAll.totalRows > 0, JSON.stringify(livdSelectAll));
    const livdClear = await page.evaluate(function () {
      document.getElementById("dsxSelNoneBtn").click();
      return { selectedCount: window.__studioDsxSelected().length, delDisabled: document.getElementById("dsxSelDelBtn").disabled };
    });
    ok("LIVE-d: Clear deselects everything and disables Delete again",
      livdClear.selectedCount === 0 && livdClear.delDisabled, JSON.stringify(livdClear));

    // re-select just the two throwaway datasets and bulk-delete them
    await page.evaluate(function () { document.querySelector('.dsx-select-cb[data-dsx-select="livd-bulk-a"]').click(); });
    await page.evaluate(function () { document.querySelector('.dsx-select-cb[data-dsx-select="livd-bulk-b"]').click(); });
    const livdBeforeDelete = await page.evaluate(function () { return Studio.Workspace.all("datasets").length; });
    // window.confirm is already monkeypatched (not native) by earlier DSX tests in this
    // same page session (e.g. the individual-delete test above) — matching that local
    // convention rather than Playwright's page.once('dialog', ...) API, which would
    // register a listener that never fires here and leaks into a LATER unrelated native
    // dialog elsewhere in the suite.
    await page.evaluate(function () { window.confirm = function () { return true; }; });
    await page.click("#dsxSelDelBtn");
    await page.waitForTimeout(150);
    const livdDeleted = await page.evaluate(function (before) {
      return {
        remaining: Studio.Workspace.all("datasets").length,
        stillA: !!Studio.Workspace.get("datasets", "livd-bulk-a"),
        stillB: !!Studio.Workspace.get("datasets", "livd-bulk-b"),
        selectedAfter: window.__studioDsxSelected().length,
        before: before
      };
    }, livdBeforeDelete);
    ok("LIVE-d: Delete removes every selected dataset after confirming",
      !livdDeleted.stillA && !livdDeleted.stillB && livdDeleted.selectedAfter === 0 && livdDeleted.remaining === livdDeleted.before - 2,
      JSON.stringify(livdDeleted));

    // clicking Select again (now "Cancel") leaves select mode and restores normal open-on-click
    const livdCancel = await page.evaluate(function () {
      document.getElementById("dsxSelectBtn").click();
      return {
        mode: window.__studioDsxSelectMode(),
        checkboxes: document.querySelectorAll("#dsxResults .dsx-select-cb").length,
        btnText: document.getElementById("dsxSelectBtn").textContent
      };
    });
    ok("LIVE-d: clicking Select again exits select mode and hides the checkboxes",
      !livdCancel.mode && livdCancel.checkboxes === 0 && /Select/.test(livdCancel.btnText) && !/Cancel/.test(livdCancel.btnText),
      JSON.stringify(livdCancel));

    // the tile view (dsx-tile) carries the same select-mode checkbox and selection
    // highlight — dsxViewToggle back to list afterward so the rest of the suite sees
    // the layout it expects.
    await page.click("#dsxViewToggle");
    await page.waitForTimeout(80);
    const livdTileSelect = await page.evaluate(function () {
      document.getElementById("dsxSelectBtn").click();
      var cb = document.querySelector("#dsxResults .dsx-tile .dsx-select-cb");
      if (!cb) return { hasCb: false };
      cb.click();
      var tile = document.querySelector("#dsxResults .dsx-tile.is-selected");
      return { hasCb: true, tileSelected: !!tile, selectedCount: window.__studioDsxSelected().length };
    });
    ok("LIVE-d: tile view gets the same select-mode checkbox and selection highlight",
      livdTileSelect.hasCb && livdTileSelect.tileSelected && livdTileSelect.selectedCount === 1, JSON.stringify(livdTileSelect));
    await page.evaluate(function () {
      document.getElementById("dsxSelectBtn").click(); // back out of select mode
    });
    await page.click("#dsxViewToggle"); // back to list view
    await page.waitForTimeout(80);

    // LIVE-d (slice 2): multi-select + bulk delete on Connections — same shape slice 1
    // proved on Datasets (session-only select mode, checkbox overlay, bulk bar with
