    const kpiAfter = await page.evaluate(() => window.__STUDIO_STATE.spec.kpis.map((k) => k.label));
    ok("KPI ↑ reorders the tile", moved && kpiAfter[0] === kpiBefore[1], kpiBefore + " → " + kpiAfter);
    // empty state on New → Blank
