    ok("E1: restore banner .rb-sum shows panel/KPI counts", e1banner.found && /panel/i.test(e1banner.sum), JSON.stringify(e1banner));

    // ---- QA-06: restore banner reserves space instead of overlapping controls (desktop) ----
