    // ---- LF49 slice 1: XLSX export (dependency-free multi-sheet OOXML workbook) ----
    // A STORED (uncompressed) zip keeps every part's XML as plain bytes, so we can decode the
    // bytes latin1 and assert the OOXML structure + content directly — no unzip lib needed.
    console.log("\n• LF49: XLSX workbook export");
    await page.evaluate(async () => {
      var spec = await fetch("data/examples/studio-cost.studio.json").then(function (r) { return r.json(); });
      window.__studioLoad(spec);
    });
    await page.waitForTimeout(400);
    const lf49 = await page.evaluate(() => {
      try {
        var bytes = window.__studioBuildXlsx();
        var s = "";
        for (var i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
        return {
          isUint8: !!(bytes && bytes.constructor && bytes.constructor.name === "Uint8Array"),
          pk: bytes[0] === 0x50 && bytes[1] === 0x4B,               // "PK" zip signature
          hasContentTypes: s.indexOf("[Content_Types].xml") >= 0,
          hasWorkbook: s.indexOf("xl/workbook.xml") >= 0,
          hasSheet1: s.indexOf("xl/worksheets/sheet1.xml") >= 0,
          hasSheet2: s.indexOf("xl/worksheets/sheet2.xml") >= 0,   // ≥2 sheets = summary + data
          eocd: s.indexOf("PK") >= 0,                  // end-of-central-directory record
          dashboardSheet: s.indexOf('name="Dashboard"') >= 0,
          dataSheet: s.indexOf('name="CostBySource"') >= 0,
          title: s.indexOf("Cost Optimization") >= 0,
          kpiLabel: s.indexOf("Monthly Cost") >= 0,
          viewsHeader: s.indexOf("Views</t>") >= 0,
          hasNumber: /<v>[0-9]/.test(s),
          menuBtn: !!document.querySelector("#menuExport button[data-exp='xlsx']"),
          bytes: bytes.length
        };
      } catch (e) { return { err: e.message }; }
    });
    ok("LF49: the Export menu offers an 'Excel workbook (.xlsx)' item", lf49.menuBtn, JSON.stringify({ menuBtn: lf49.menuBtn, err: lf49.err }));
    ok("LF49: exportXlsx yields a valid PK-signed .xlsx with the required OOXML parts (Content_Types, workbook, sheet1) and an EOCD record",
      lf49.isUint8 && lf49.pk && lf49.eocd && lf49.hasContentTypes && lf49.hasWorkbook && lf49.hasSheet1, JSON.stringify(lf49));
    ok("LF49: the workbook is multi-sheet — a 'Dashboard' summary tab plus a data tab named after each source used",
      lf49.hasSheet2 && lf49.dashboardSheet && lf49.dataSheet, JSON.stringify(lf49));
    ok("LF49: tab 1 summarizes the dashboard — title, KPIs (with numeric values), and the Views list",
      lf49.title && lf49.kpiLabel && lf49.viewsHeader && lf49.hasNumber, JSON.stringify(lf49));

    // LF49 slice 2: Word (.docx) — same summary + backend-data tables as a Word report.
    // Same stored-zip OOXML, so we scan the bytes for the parts + content (studio-cost still loaded).
    const lf49d = await page.evaluate(() => {
      try {
        var bytes = window.__studioBuildDocx();
        var s = "";
        for (var i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
        return {
          isUint8: !!(bytes && bytes.constructor && bytes.constructor.name === "Uint8Array"),
          pk: bytes[0] === 0x50 && bytes[1] === 0x4B,
          hasContentTypes: s.indexOf("[Content_Types].xml") >= 0,
          hasDocument: s.indexOf("word/document.xml") >= 0,
          hasRels: s.indexOf("_rels/.rels") >= 0,
          wordDoc: s.indexOf("<w:document") >= 0 && s.indexOf("</w:body></w:document>") >= 0,
          hasTable: s.indexOf("<w:tbl>") >= 0,          // KPIs/Views/data tables
          title: s.indexOf("Cost Optimization") >= 0,
          kpiLabel: s.indexOf("Monthly Cost") >= 0,
          sectPr: s.indexOf("<w:sectPr>") >= 0,          // valid section properties
          menuBtn: !!document.querySelector("#menuExport button[data-exp='docx']"),
          bytes: bytes.length
        };
      } catch (e) { return { err: e.message }; }
    });
    ok("LF49 slice 2: the Export menu offers a 'Word document (.docx)' item", lf49d.menuBtn, JSON.stringify({ menuBtn: lf49d.menuBtn, err: lf49d.err }));
    ok("LF49 slice 2: exportDocx yields a valid PK-signed .docx (Content_Types, _rels, word/document.xml, sectPr)",
      lf49d.isUint8 && lf49d.pk && lf49d.hasContentTypes && lf49d.hasDocument && lf49d.hasRels && lf49d.wordDoc && lf49d.sectPr, JSON.stringify(lf49d));
    ok("LF49 slice 2: the report has the dashboard title, KPI names, and data tables",
      lf49d.title && lf49d.kpiLabel && lf49d.hasTable, JSON.stringify(lf49d));

    // LF49 slice 3: PowerPoint (.pptx) — a deck where each chart View is a slide carrying its
    // CHART IMAGE. The builder rasterizes each panel from the live preview iframe via the render
    // module's __downloadPanelPngDataUrl hook (the same one the on-panel PNG download / LF6 test
    // uses), so we first wait for the preview to render its chart SVGs, then build + validate.
    await page.evaluate(async () => {
      var spec = await fetch("data/examples/studio-cost.studio.json").then(function (r) { return r.json(); });
      window.__studioLoad(spec);
    });
    await page.waitForFunction(() => {
      try { var d = document.querySelector("#preview").contentDocument; return d && d.querySelectorAll("[data-panel-id] svg").length >= 1; }
      catch (e) { return false; }
    }, { timeout: 15000 }).catch(function () {});
    await page.waitForTimeout(500);
    const lf49p = await page.evaluate(() => new Promise((resolve) => {
      try {
        window.__studioBuildPptx(function (bytes) {
          var s = "";
          for (var i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
          resolve({
            isUint8: !!(bytes && bytes.constructor && bytes.constructor.name === "Uint8Array"),
            pk: bytes[0] === 0x50 && bytes[1] === 0x4B,
            hasPresentation: s.indexOf("ppt/presentation.xml") >= 0,
            hasMaster: s.indexOf("ppt/slideMasters/slideMaster1.xml") >= 0,
            hasTheme: s.indexOf("ppt/theme/theme1.xml") >= 0,
            hasSlide1: s.indexOf("ppt/slides/slide1.xml") >= 0,
            media: (s.match(/ppt\/media\/image\d+\.png/g) || []).length,
            hasPic: s.indexOf("<p:pic>") >= 0 && s.indexOf('r:embed="rId2"') >= 0,
            title: s.indexOf("Cost Optimization") >= 0,
            menuBtn: !!document.querySelector("#menuExport button[data-exp='pptx']"),
            bytes: bytes.length
          });
        });
      } catch (e) { resolve({ err: e.message }); }
    }));
    ok("LF49 slice 3: the Export menu offers a 'PowerPoint (.pptx)' item", lf49p.menuBtn, JSON.stringify({ menuBtn: lf49p.menuBtn, err: lf49p.err }));
    ok("LF49 slice 3: exportPptx yields a valid PK-signed .pptx with the OOXML presentation graph (presentation / master / theme / slide1)",
      lf49p.isUint8 && lf49p.pk && lf49p.hasPresentation && lf49p.hasMaster && lf49p.hasTheme && lf49p.hasSlide1, JSON.stringify(lf49p));
    ok("LF49 slice 3: each chart View becomes an image slide — the deck embeds ≥1 chart PNG as a picture (<p:pic>)",
      lf49p.media >= 1 && lf49p.hasPic, JSON.stringify(lf49p));
    ok("LF49 slice 3: the title slide carries the dashboard title", lf49p.title, JSON.stringify(lf49p));

    // ---- N-FUN: first-export delight moment ----
