    ok("M9: no horizontal scroll at phone (documentElement.scrollWidth ≤ viewport + 2)", m9Overflow.noOverflow, JSON.stringify(m9Overflow));

    // ---- M10: secondary topbar buttons hidden at phone widths ≤640px ----
