    await page.fill("#repoSearch", "");
    await page.waitForTimeout(80);
    await page.evaluate(function () {
      Studio.Workspace.remove("dashboards", "test-col-search-dash");
      window.__studioRenderDashboards();
    });

    // N-FUN innovation idea (added 2026-07-04): "what changed since your last visit" digest —
    // combines studio-recents (already tracks a dashboard's current spec) with Version history
    // (already snapshots a checkpoint on Save) into a "N changes since you were last here" hint,
    // reusing Studio.diffSpecs/diffSummary verbatim (same engine Version-history-restore and
    // Compare-dashboards already share).
    console.log("\n• N-FUN: 'what changed since your last visit' digest");
    // Each step gets a real await (not back-to-back synchronous calls) so the ISO timestamps
    // snapshotVersion()/markLastViewed() stamp are guaranteed distinct millisecond values —
    // changesSinceLastView()'s "checkpoint at-or-before last-viewed" lookup depends on real
    // ordering, which synchronous same-tick calls can't reliably produce.
    const civId = "civ-test-dash";
    await page.evaluate(function (id) {
      window.__studioLoad({ id: id, name: id, title: "CIV Original Title", panels: [], kpis: [], filters: [], cda: { connections: [], dataAccesses: [] } });
      window.__studioSnapshotVersion(); // checkpoint #1 — the state as it stood when "last viewed"
    }, civId);
    await page.waitForTimeout(20);
    await page.evaluate(function (id) { window.__studioMarkLastViewed(id); }, civId); // pretend the user just opened it right now
    await page.waitForTimeout(20);
    const civSetup = await page.evaluate(function (id) {
      window.__STUDIO_STATE.spec.title = "CIV Changed Title"; // an edit made during this same visit
      window.__studioSnapshotVersion(); // checkpoint #2 — the Save that follows the edit
      Studio.Workspace.put("dashboards", { id: id, ts: new Date().toISOString(), spec: window.__STUDIO_STATE.spec });
      return id;
    }, civId);
    const civPure = await page.evaluate(function (id) {
      var r = (window.__studioRecents() || []).filter(function (x) { return x.id === id; })[0];
      return window.__studioChangesSinceLastView(r);
    }, civSetup);
    ok("N-FUN: changesSinceLastView() finds a real diff between the last-viewed checkpoint and the current spec",
      !!civPure && civPure.count >= 1 && /Title/.test(civPure.lines.join(" ")), JSON.stringify(civPure));
    await page.evaluate(function () { window.__studioRenderHome(); });
    const civCard = await page.evaluate(function (id) {
      var open = document.querySelector('#secHome [data-recent="' + id + '"]');
      var card = open ? open.closest(".recent-card") : null;
      var hint = card ? card.querySelector(".recent-changed") : null;
      return { hasHint: !!hint, text: hint ? hint.textContent : "", title: hint ? hint.getAttribute("title") : "" };
    }, civSetup);
    ok("N-FUN: Home's recent card shows a '1 change since you were last here' hint",
      civCard.hasHint && /1 change since you were last here/.test(civCard.text), JSON.stringify(civCard));
    ok("N-FUN: the hint's tooltip lists the actual diff line, not just a bare count",
      /Title/.test(civCard.title), JSON.stringify(civCard));
    const civNulls = await page.evaluate(function () {
      var neverViewedId = "civ-test-never-viewed";
      window.__studioLoad({ id: neverViewedId, name: neverViewedId, title: "Never Viewed", panels: [], kpis: [], filters: [], cda: { connections: [], dataAccesses: [] } });
      window.__studioSnapshotVersion();
      var neverViewed = window.__studioChangesSinceLastView({ id: neverViewedId, spec: window.__STUDIO_STATE.spec });
      var noChangeId = "civ-test-no-changes";
      window.__studioLoad({ id: noChangeId, name: noChangeId, title: "No Changes", panels: [], kpis: [], filters: [], cda: { connections: [], dataAccesses: [] } });
      window.__studioSnapshotVersion();
      window.__studioMarkLastViewed(noChangeId);
      var noChange = window.__studioChangesSinceLastView({ id: noChangeId, spec: window.__STUDIO_STATE.spec });
      return { neverViewed: neverViewed, noChange: noChange };
    });
    ok("N-FUN: changesSinceLastView() returns null when the dashboard was never marked as last-viewed",
      civNulls.neverViewed === null, JSON.stringify(civNulls));
    ok("N-FUN: changesSinceLastView() returns null when nothing has actually changed since the last view",
      civNulls.noChange === null, JSON.stringify(civNulls));
    const civOpenMarks = await page.evaluate(function () {
      var id = "civ-test-open-marks";
      Studio.Workspace.put("dashboards", { id: id, ts: new Date().toISOString(), spec: { id: id, name: id, title: "Open Marks Test", panels: [], kpis: [], filters: [], cda: { connections: [], dataAccesses: [] } } });
      var before = window.__studioLastViewed()[id];
      window.__studioOpenRecent(id);
      var after = window.__studioLastViewed()[id];
      return { before: before, after: after };
    });
    ok("N-FUN: opening a dashboard via openRecent() marks it as last-viewed right now (resets the clock)",
      !civOpenMarks.before && !!civOpenMarks.after, JSON.stringify(civOpenMarks));
    await page.evaluate(function () {
      ["civ-test-dash", "civ-test-open-marks"].forEach(function (id) { Studio.Workspace.remove("dashboards", id); });
      window.__studioRenderHome(); window.__studioRenderDashboards();
      // __studioOpenRecent() above (like a real "open a dashboard" click) switches the active
      // shell section to Studio — switch back to Repository so the a11y check right after this
      // still finds #repoSearch in the visible section, not a hidden one.
      if (window.__studioShellSetSection) window.__studioShellSetSection("dashboards");
    });

    // a11y: Track L found the Repository search field was the one input in the app chrome that
    // re-declared outline:none inside its own :focus rule (higher specificity than the shared global
    // :focus-visible ring in studio.css), so tabbing to it showed only a border-color change and zero
    // outline -- unlike every sibling search field (.search/.insp-search/.cg-search/.cl-search).
    await page.evaluate(function () { document.getElementById("repoSearch").focus(); });
    const repoSearchOutline = await page.evaluate(function () {
      var s = document.getElementById("repoSearch");
      return s ? getComputedStyle(s).outlineStyle : "none";
    });
    ok("a11y: keyboard-focusing the Repository search field shows a real outline (not 'none')",
      repoSearchOutline !== "none", "outlineStyle=" + repoSearchOutline);
    await page.evaluate(function () { document.getElementById("repoSearch").blur(); });

    // (Z3-4 "jump to a data-source card in the library" retired with the Repository screen.)

    // Z3-5: clicking a dashboard card in Repository reopens it (same behavior as Home)
    await page.click('#railNav .rail-item[data-sec="dashboards"]');
    await page.waitForTimeout(120);
    const z3RecId = await page.evaluate(function () { return document.querySelector("#repoResults .recent-open").getAttribute("data-recent"); });
    await page.click("#repoResults .recent-card");
    await page.waitForTimeout(150);
    const z3OpenState = await page.evaluate(function (id) {
      var s = window.__STUDIO_STATE.spec;
      return { specId: s.id, studioVisible: document.getElementById("appMain").hidden === false };
    }, z3RecId);
    ok("Z3: clicking a dashboard card in Repository reopens it and returns to Studio",
      z3OpenState.specId === z3RecId && z3OpenState.studioVisible, JSON.stringify(z3OpenState));

    // Z3-6: pinning from Repository updates both Repository's own list and Home's (shared storage)
    const z3PinFirstId = await page.evaluate(function () { return document.querySelector("#repoResults .recent-open").getAttribute("data-recent"); });
    await page.evaluate(function (id) { window.__studioTogglePin(id); }, z3PinFirstId);
    await page.waitForTimeout(80);
    const z3PinState = await page.evaluate(function (id) {
      return {
        pinnedInRepo: !!document.querySelector('#repoResults .recent-pin.pinned[data-pin="' + id + '"]'),
        storedPins: window.__studioPins()
      };
    }, z3PinFirstId);
    ok("Z3: pinning from Repository shows as pinned there and persists to the shared pins store",
      z3PinState.pinnedInRepo && z3PinState.storedPins.indexOf(z3PinFirstId) >= 0, JSON.stringify(z3PinState));
    await page.evaluate(function (id) { window.__studioTogglePin(id); }, z3PinFirstId); // unpin — restore state

    // (Repository data-source card CRUD retired with the Repository screen — data sources
    // are managed in the Datasets/Connections sections and the Studio library pane now.)

    // Z3 follow-up: whole-repository JSON export/import (data sources you authored + dashboard inventory)
    // Z3-5 above navigated away to Studio (opening a dashboard) — the Export/Import buttons only
    // exist in the (now-hidden) Repository section, so switch back before driving a real click on them.
    await page.click('#railNav .rail-item[data-sec="dashboards"]');
    await page.waitForTimeout(120);
    await page.evaluate(function () {
      window.__STUDIO_STATE.catalog.repoExportTest = { file: "repoExportTest.cda", connection: { id: "pdc", jndi: "PDC-BIDB-EXT" },
        dataAccesses: [{ id: "repoTestDs", name: "repoTestDs", kind: "sql", jndi: "PDC-BIDB-EXT", columns: ["a", "b"], authored: true, sql: "SELECT 1", query: "SELECT 1", params: [], calcColumns: [], cache: true, cacheDuration: 300 }] };
    });
    // LF59 (1): "Export dashboards…" now opens a subset picker (defaults to all selected);
    // clicking "Export N dashboards" with everything checked reproduces the historical full export.
    // LF59 (3): the button now lives behind the toolbar's "More" (dashMoreBtn) menu.
    await page.click("#dashMoreBtn");
    await page.click("#repoExportBtn");
    await page.waitForSelector(".exp-dash-list", { timeout: 5000 });
    const [repoDl] = await Promise.all([page.waitForEvent("download", { timeout: 45000 }), page.click(".exp-dash-foot .btn.primary")]);
    const repoDlName = repoDl.suggestedFilename();
    const repoDlStream = await repoDl.createReadStream();
    let repoDlText = ""; for await (const chunk of repoDlStream) repoDlText += chunk.toString();
    let repoDlJson = {}; try { repoDlJson = JSON.parse(repoDlText); } catch (e) {}
    const repoExportedDs = (repoDlJson.dataSources || []).find((d) => d.da && d.da.id === "repoTestDs");
    ok("Z3 follow-up: Export repository downloads a well-formed file with authored data sources + dashboards",
      repoDlName === "dashboard-studio-repository.json" && repoDlJson._type === "studio-repository" &&
      !!repoExportedDs && repoExportedDs.stem === "repoExportTest" && Array.isArray(repoDlJson.dashboards),
      repoDlName + " :: " + repoDlText.slice(0, 160));

    // LF59 (1) — SELECTIVE EXPORT: the export can be scoped to a chosen subset of dashboards
    // rather than always dumping the whole repository. collectRepositoryExport([id]) returns only
    // the picked dashboard(s) and never MORE data sources / pins / workbooks than the full export.
    const lf59sub = await page.evaluate(function () {
      var recents = window.__studioRecents();
      if (!recents.length) return { skip: true };
      var pickId = recents[0].id;
      var full = window.__studioCollectRepositoryExport();
      var subset = window.__studioCollectRepositoryExport([pickId]);
      return {
        type: subset._type,
        subsetDash: subset.dashboards.length,
        onlyPicked: subset.dashboards.every(function (r) { return r.id === pickId; }),
        fullDash: full.dashboards.length,
        dsMonotonic: subset.dataSources.length <= full.dataSources.length,
        wbMonotonic: subset.workbooks.length <= full.workbooks.length
      };
    });
    ok("LF59 (1): selective export — collectRepositoryExport([id]) scopes the file to just the chosen dashboard(s)",
      lf59sub.skip || (lf59sub.type === "studio-repository" && lf59sub.subsetDash === 1 && lf59sub.onlyPicked &&
        lf59sub.subsetDash <= lf59sub.fullDash && lf59sub.dsMonotonic && lf59sub.wbMonotonic),
      JSON.stringify(lf59sub));

    // LF59 (2): multi-select + bulk delete — "Select" turns on a checkbox on every tile/row;
    // tapping a card toggles its selection instead of opening it; the bulk bar's Delete removes
    // every selected dashboard after a confirm. Two throwaway dashboards (one demoPackId-tagged,
    // so the "sample dashboards are selectable/deletable too" semantics get real coverage) keep
    // this from touching real fixture data other tests depend on.
    await page.evaluate(function () {
      Studio.Workspace.put("dashboards", { id: "lf59-bulk-a", ts: new Date().toISOString(),
        spec: { id: "lf59-bulk-a", title: "LF59 bulk A", panels: [], kpis: [], filters: [], cda: { connections: [], dataAccesses: [] } } }, { silent: true });
      Studio.Workspace.put("dashboards", { id: "lf59-bulk-b", ts: new Date().toISOString(), demoPackId: "lf59-test-pack",
        spec: { id: "lf59-bulk-b", title: "LF59 bulk B (sample)", panels: [], kpis: [], filters: [], cda: { connections: [], dataAccesses: [] } } }, { silent: true });
      window.__studioRenderDashboards();
    });
    await page.waitForTimeout(100);

    const lf59SelectOn = await page.evaluate(function () {
      document.getElementById("repoSelectBtn").click();
      return {
        mode: window.__studioDashSelectMode(),
        checkboxes: document.querySelectorAll("#repoResults .dash-select-cb").length,
        bulkBar: !!document.querySelector(".dash-bulk-bar"),
        btnText: document.getElementById("repoSelectBtn").textContent,
        delDisabled: document.getElementById("dashSelDelBtn").disabled
      };
    });
    ok("LF59 (2): clicking Select enters select mode — checkboxes + a bulk bar appear, Delete starts disabled",
      lf59SelectOn.mode && lf59SelectOn.checkboxes > 0 && lf59SelectOn.bulkBar && /Cancel/.test(lf59SelectOn.btnText) && lf59SelectOn.delDisabled,
      JSON.stringify(lf59SelectOn));

    // tapping a tile in select mode selects it instead of opening it (re-query after the click —
    // its handler re-renders #repoResults, so the pre-click node references go stale)
    const lf59TapSelects = await page.evaluate(function () {
      var card = document.querySelector('.dash-select-cb[data-select="lf59-bulk-a"]').closest(".recent-card");
      card.querySelector(".recent-open").click();
      var cbAfter = document.querySelector('.dash-select-cb[data-select="lf59-bulk-a"]');
      return {
        checked: cbAfter.checked,
        cardSelected: cbAfter.closest(".recent-card").classList.contains("is-selected"),
        selected: window.__studioDashSelected(),
        stillOnDashboards: document.getElementById("secDashboards").hidden === false
      };
    });
    ok("LF59 (2): tapping a tile in select mode selects it (doesn't open it) and highlights the card",
      lf59TapSelects.checked && lf59TapSelects.cardSelected && lf59TapSelects.selected.indexOf("lf59-bulk-a") >= 0 && lf59TapSelects.stillOnDashboards,
      JSON.stringify(lf59TapSelects));

    // the checkbox itself is an equivalent way to toggle selection
    const lf59CbToggle = await page.evaluate(function () {
      document.querySelector('.dash-select-cb[data-select="lf59-bulk-b"]').click();
      return { count: window.__studioDashSelected().length, barText: document.querySelector(".dash-bulk-count").textContent };
    });
    ok("LF59 (2): checking a row's checkbox selects it too, and the bulk bar's count reflects the total",
      lf59CbToggle.count === 2 && /2 selected/.test(lf59CbToggle.barText), JSON.stringify(lf59CbToggle));

    // Select all / Clear apply to everything currently in view
    const lf59SelectAll = await page.evaluate(function () {
      document.getElementById("dashSelAllBtn").click();
      var totalCards = document.querySelectorAll("#repoResults .recent-card, #repoResults .dash-li").length;
      return { selectedCount: window.__studioDashSelected().length, totalCards: totalCards };
    });
    ok("LF59 (2): Select all selects every dashboard currently in view",
      lf59SelectAll.selectedCount === lf59SelectAll.totalCards && lf59SelectAll.totalCards > 0, JSON.stringify(lf59SelectAll));
    const lf59Clear = await page.evaluate(function () {
      document.getElementById("dashSelNoneBtn").click();
      return { selectedCount: window.__studioDashSelected().length, delDisabled: document.getElementById("dashSelDelBtn").disabled };
    });
    ok("LF59 (2): Clear deselects everything and disables Delete again",
      lf59Clear.selectedCount === 0 && lf59Clear.delDisabled, JSON.stringify(lf59Clear));

    // re-select just the two throwaway dashboards and bulk-delete them
    await page.evaluate(function () { document.querySelector('.dash-select-cb[data-select="lf59-bulk-a"]').click(); });
    await page.evaluate(function () { document.querySelector('.dash-select-cb[data-select="lf59-bulk-b"]').click(); });
    const lf59BeforeDelete = await page.evaluate(function () { return Studio.Workspace.all("dashboards").length; });
    page.once("dialog", (d) => d.accept());
    await page.click("#dashSelDelBtn");
    await page.waitForTimeout(150);
    const lf59Deleted = await page.evaluate(function (before) {
      return {
        remaining: Studio.Workspace.all("dashboards").length,
        stillA: !!Studio.Workspace.get("dashboards", "lf59-bulk-a"),
        stillB: !!Studio.Workspace.get("dashboards", "lf59-bulk-b"),
        selectedAfter: window.__studioDashSelected().length,
        before: before
      };
    }, lf59BeforeDelete);
    // Not asserting remaining === before - 2 exactly: noteRecent()'s pre-existing "cap unpinned
    // recents at 8" pruning (unrelated to LF59) can independently evict older fixture dashboards
    // on its own debounced timer while this huge suite runs, so remaining can legitimately drop
    // by MORE than 2 — the real assertion is that both our targets are actually gone.
    ok("LF59 (2): Delete removes every selected dashboard (sample-pack ones included) after confirming",
      !lf59Deleted.stillA && !lf59Deleted.stillB && lf59Deleted.selectedAfter === 0 && lf59Deleted.remaining <= lf59Deleted.before - 2,
      JSON.stringify(lf59Deleted));

    // clicking Select again (now "Cancel") leaves select mode and restores normal open-on-click
    const lf59Cancel = await page.evaluate(function () {
      document.getElementById("repoSelectBtn").click();
      return {
        mode: window.__studioDashSelectMode(),
        checkboxes: document.querySelectorAll("#repoResults .dash-select-cb").length,
        btnText: document.getElementById("repoSelectBtn").textContent
      };
    });
    ok("LF59 (2): clicking Select again exits select mode and hides the checkboxes",
      !lf59Cancel.mode && lf59Cancel.checkboxes === 0 && /Select/.test(lf59Cancel.btnText) && !/Cancel/.test(lf59Cancel.btnText),
      JSON.stringify(lf59Cancel));

    // the list-view rows (dashListRowHtml) carry the same select-mode checkbox — dashViewToggle
    // back to tiles afterward so the rest of the suite sees the layout it expects.
    await page.click("#dashViewToggle");
    await page.waitForTimeout(80);
    const lf59ListSelect = await page.evaluate(function () {
      document.getElementById("repoSelectBtn").click();
      var cb = document.querySelector("#repoResults .dash-li .dash-select-cb");
      if (!cb) return { hasCb: false };
      cb.click();
      var row = document.querySelector("#repoResults .dash-li.is-selected");
      return { hasCb: true, rowSelected: !!row, selectedCount: window.__studioDashSelected().length };
    });
    ok("LF59 (2): list-view rows get the same select-mode checkbox and selection highlight",
      lf59ListSelect.hasCb && lf59ListSelect.rowSelected && lf59ListSelect.selectedCount === 1, JSON.stringify(lf59ListSelect));
    await page.evaluate(function () { document.getElementById("repoSelectBtn").click(); }); // back out of select mode
    await page.click("#dashViewToggle");
    await page.waitForTimeout(80);

    const repoImport = await page.evaluate(function () {
      delete window.__STUDIO_STATE.catalog.repoExportTest;
      var before = !!window.__STUDIO_STATE.catalog.repoImportTest;
      var bad = window.__studioApplyRepositoryData({ _type: "not-repository" });
      var res = window.__studioApplyRepositoryData({
        _type: "studio-repository", _v: 1,
        dataSources: [{ stem: "repoImportTest", da: { id: "importedDs", name: "importedDs", kind: "sql", jndi: "PDC-BIDB-EXT", columns: ["x"], authored: true, sql: "SELECT 1", query: "SELECT 1", params: [], calcColumns: [], cache: true, cacheDuration: 300 } }],
        dashboards: [], pins: []
      });
      var after = window.__STUDIO_STATE.catalog.repoImportTest;
      delete window.__STUDIO_STATE.catalog.repoImportTest; // cleanup
      return { before: before, bad: bad, ok: res.ok, dsCount: res.dsCount, hasDa: !!(after && after.dataAccesses[0].id === "importedDs") };
    });
    ok("Z3 follow-up: Import repository rejects unrecognized files and merges recognized ones into the catalog",
      repoImport.before === false && repoImport.bad.ok === false && repoImport.ok === true && repoImport.dsCount === 1 && repoImport.hasDa,
      JSON.stringify(repoImport));

    // ── Z3 follow-up: Workbooks — named collections of dashboards ──
    console.log("\n• Z3 follow-up: Workbooks");
    await page.click('#railNav .rail-item[data-sec="dashboards"]');
    await page.waitForTimeout(120);
    const wbDashId = await page.evaluate(function () { var r = window.__studioRecents(); return r.length ? r[0].id : null; });
    ok("Z3-WB: repository has at least one existing dashboard to test workbook filing", !!wbDashId, String(wbDashId));

    // #122 (test hardening): set the name AND click Add in ONE synchronous in-page step. Split
    // page.fill + page.click let a background autosave re-render (renderDashboards) re-create a
    // fresh, EMPTY #wbNameInp between the two, so the Add handler read "" and no-op'd → 0 workbooks
    // → the [0].id read below FATAL-aborted the whole suite. Atomic set-then-click can't interleave
    // a re-render; then wait for the workbook to actually appear, and read its id null-safely so a
    // future miss fails just this assertion instead of killing the run.
    await page.evaluate(function () {
      var inp = document.querySelector("#wbNameInp"), btn = document.querySelector("#wbAddBtn");
      if (!inp || !btn) return;
      inp.value = "Quarterly Reviews";
      btn.click(); // reads inp.value synchronously in the same task — no re-render can race in
    });
    await page.waitForFunction(function () { return window.__studioWorkbooks().length >= 1; }, { timeout: 5000 }).catch(function () {});
    await page.waitForTimeout(60);
    const wbAfterCreate = await page.evaluate(function () {
      // scope to the Dashboards section — Home renders its own (never-active) copy of the
      // workbook chips, and a background autosave tick can re-render Home mid-test
      var chip = Array.from(document.querySelectorAll("#repoResults .wb-chip")).find(function (b) { return b.textContent.indexOf("Quarterly Reviews") >= 0; });
      return { count: window.__studioWorkbooks().length, chipVisible: !!chip, chipActive: !!(chip && chip.classList.contains("active")) };
    });
    ok("Z3-WB: creating a workbook via the name field + button adds it, shows a filter chip, and auto-selects it",
      wbAfterCreate.count >= 1 && wbAfterCreate.chipVisible && wbAfterCreate.chipActive, JSON.stringify(wbAfterCreate));
    const wbId = await page.evaluate(function () { var w = window.__studioWorkbooks()[0]; return w ? w.id : null; });

    // Z3 follow-up: hovering a workbook chip reveals a ✎ rename button that swaps its label
    // into an inline rename input (Enter commits, Escape cancels) — same convention as
    // panel/KPI inline rename, just via a dedicated button instead of a native dblclick
    // gesture (a bare dblclick doesn't reliably fire here since each single click already
    // re-renders the whole chip strip, which resets the browser's double-click target tracking).
    // Driven fully in-page and synchronously: the ✎ button is hover-revealed and the input
    // commits on blur, so split physical click/fill/press steps race Playwright's own
    // focus transitions (flaky in full-suite runs). The handler contract — click swaps the
    // label for an input, Enter commits, Escape discards — is what's being tested.
    const wbRenameFlow = await page.evaluate(function (id) {
      var renameBtn = id && document.querySelector('.wb-chip-rename[data-wb-rename="' + id + '"]');
      if (!renameBtn) return { input: false }; // #122: don't FATAL if creation above missed
      renameBtn.click();
      var inp = document.querySelector(".wb-chip-rename-inp");
      if (!inp) return { input: false };
      inp.value = "Board Reviews";
      inp.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true }));
      return { input: true };
    }, wbId);
    ok("Z3-WB: the ✎ rename button swaps a workbook chip's label into a rename <input>", wbRenameFlow.input, JSON.stringify(wbRenameFlow));
    await page.waitForTimeout(80);
    const wbAfterRename = await page.evaluate(function (id) {
      var wb = window.__studioWorkbooks().find(function (w) { return w.id === id; });
      var chip = document.querySelector('.wb-chip[data-wb-name="' + id + '"] .wb-chip-label');
      return { name: wb ? wb.name : null, chipText: chip ? chip.textContent : null };
    }, wbId);
    ok("Z3-WB: renaming a workbook via the inline input persists the new name and re-renders the chip",
      wbAfterRename.name === "Board Reviews" && wbAfterRename.chipText === "Board Reviews", JSON.stringify(wbAfterRename));

    // Escape cancels the rename — name stays whatever it was just set to above
    await page.evaluate(function (id) {
      document.querySelector('.wb-chip-rename[data-wb-rename="' + id + '"]').click();
      var inp = document.querySelector(".wb-chip-rename-inp");
      if (!inp) return;
      inp.value = "Should Not Save";
      inp.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
    }, wbId);
    await page.waitForTimeout(80);
    const wbAfterEscape = await page.evaluate(function (id) {
      var wb = window.__studioWorkbooks().find(function (w) { return w.id === id; });
      return wb ? wb.name : null;
    }, wbId);
    ok("Z3-WB: pressing Escape during a workbook rename discards the edit", wbAfterEscape === "Board Reviews", String(wbAfterEscape));

    // switch back to "All" so the not-yet-filed dashboard (and its workbook picker) is visible
    await page.click('.wb-chip[data-wb-filter=""]');
    await page.waitForTimeout(80);
    await page.selectOption('.recent-wb-sel[data-recent-wb="' + wbDashId + '"]', wbId);
    await page.waitForTimeout(80);
    const wbAfterAssign = await page.evaluate(function (dashId) {
      var r = window.__studioRecents().find(function (x) { return x.id === dashId; });
      return { workbookId: r ? r.workbookId : null };
    }, wbDashId);
    ok("Z3-WB: assigning a dashboard's inline Workbook select files it into that workbook (persisted)",
      wbAfterAssign.workbookId === wbId, JSON.stringify(wbAfterAssign));

    // filtering: the workbook's own chip shows the filed dashboard; "Unfiled" hides it
    await page.click('.wb-chip[data-wb-filter="' + wbId + '"]');
    await page.waitForTimeout(80);
    const wbFilteredView = await page.evaluate(function (dashId) {
      return { cardShown: !!document.querySelector('#repoResults [data-recent="' + dashId + '"]') };
    }, wbDashId);
    ok("Z3-WB: filtering by a workbook's chip shows the dashboard filed into it", wbFilteredView.cardShown, JSON.stringify(wbFilteredView));
    await page.click('.wb-chip[data-wb-filter="__unfiled"]');
    await page.waitForTimeout(80);
    const wbUnfiledView = await page.evaluate(function (dashId) {
      return { cardShown: !!document.querySelector('#repoResults [data-recent="' + dashId + '"]') };
    }, wbDashId);
    ok("Z3-WB: the \"Unfiled\" chip excludes a dashboard that's been filed into a workbook",
      !wbUnfiledView.cardShown, JSON.stringify(wbUnfiledView));

    // deleting a workbook un-files its dashboards instead of deleting them
    await page.click('.wb-chip[data-wb-filter=""]');
    await page.waitForTimeout(80);
    page.once("dialog", (d) => d.accept());
    await page.click('.wb-chip-del[data-wb-del="' + wbId + '"]');
    await page.waitForTimeout(100);
    const wbAfterDelete = await page.evaluate(function (dashId) {
      var r = window.__studioRecents().find(function (x) { return x.id === dashId; });
      return { workbooksLeft: window.__studioWorkbooks().length, dashStillExists: !!r, dashUnfiled: !!(r && !r.workbookId) };
    }, wbDashId);
    ok("Z3-WB: deleting a workbook un-files its dashboards rather than deleting them",
      wbAfterDelete.dashStillExists && wbAfterDelete.dashUnfiled, JSON.stringify(wbAfterDelete));

    // workbooks travel with whole-repository export/import
    const wbExportCheck = await page.evaluate(function () {
      var wb = window.__studioAddWorkbook("Export Test WB");
      return { wbId: wb.id, hasHook: typeof window.__studioExportRepository === "function" };
    });
    // LF59 (3): the button now lives behind the toolbar's "More" (dashMoreBtn) menu.
    await page.click("#dashMoreBtn");
    await page.click("#repoExportBtn");
    await page.waitForSelector(".exp-dash-list", { timeout: 5000 });
    const [wbDl] = await Promise.all([page.waitForEvent("download", { timeout: 45000 }), page.click(".exp-dash-foot .btn.primary")]);
    const wbDlStream = await wbDl.createReadStream();
    let wbDlText = ""; for await (const chunk of wbDlStream) wbDlText += chunk.toString();
    let wbDlJson = {}; try { wbDlJson = JSON.parse(wbDlText); } catch (e) {}
    const wbExported = (wbDlJson.workbooks || []).find((w) => w.id === wbExportCheck.wbId);
    ok("Z3-WB: whole-repository export includes workbooks", !!wbExported && wbExported.name === "Export Test WB", JSON.stringify(wbDlJson.workbooks || []));
    await page.evaluate(function (id) { window.__studioDeleteWorkbook(id); }, wbExportCheck.wbId); // cleanup

    // ── LF66/LF59: dashboards get FOLDERS alongside workbooks ──
    // The Dashboards section used to organize by workbooks only; dashboards now also carry the
    // same flat "/"-path `folder` field datasets/connections/jobs use — a Folders facet strip
    // (composing with the workbook chips), a per-row folder badge, and a move-to-folder button.
    console.log("\n• LF66/LF59: dashboard folders");
    await page.evaluate(function () { window.__studioShellSetSection("dashboards"); });
    await page.waitForTimeout(60);
    await page.evaluate(function (dashId) {
      var r = Studio.Workspace.get("dashboards", dashId);
      r.folder = "Finance/2026"; Studio.Workspace.put("dashboards", r);
      window.__studioRenderDashboards();
    }, wbDashId);
    await page.waitForTimeout(60);
    const dfChips = await page.evaluate(function () {
      return Array.prototype.map.call(document.querySelectorAll('#repoResults .cx-folder-chips [data-dash-folder]'), function (b) { return b.getAttribute("data-dash-folder"); });
    });
    ok("LF66/LF59: filing a dashboard surfaces a Folders facet with that folder chip (alongside the workbook chips)",
      dfChips.indexOf("Finance/2026") >= 0 && dfChips.indexOf("__unfiled") >= 0, JSON.stringify(dfChips));
    await page.click('#repoResults .cx-folder-chips [data-dash-folder="Finance/2026"]');
    await page.waitForTimeout(60);
    const dfFiltered = await page.evaluate(function (dashId) { return { shown: !!document.querySelector('#repoResults [data-recent="' + dashId + '"]') }; }, wbDashId);
    ok("LF66/LF59: the folder chip filters the Dashboards list to that folder", dfFiltered.shown, JSON.stringify(dfFiltered));
    await page.click('#repoResults .cx-folder-chips [data-dash-folder="__unfiled"]');
    await page.waitForTimeout(60);
    const dfUnfiled = await page.evaluate(function (dashId) { return { shown: !!document.querySelector('#repoResults [data-recent="' + dashId + '"]') }; }, wbDashId);
    ok("LF66/LF59: the Unfiled folder chip excludes a filed dashboard", !dfUnfiled.shown, JSON.stringify(dfUnfiled));
    await page.click('#repoResults .cx-folder-chips [data-dash-folder=""]');
    await page.waitForTimeout(40);
    // force LIST view (folder badge + move button live on the list row); the toggle persists, so restore after
    const dfSwitched = await page.evaluate(function () { if (!document.querySelector('#repoResults .dash-list')) { var t = document.getElementById('dashViewToggle'); if (t) { t.click(); return true; } } return false; });
    await page.waitForTimeout(60);
    const dfRow = await page.evaluate(function (dashId) {
      var row = document.querySelector('#repoResults .dash-list [data-recent="' + dashId + '"]');
      var badge = row && row.querySelector('.cx-folder');
      return { badge: badge ? badge.textContent : null, hasMove: !!(row && row.querySelector('.recent-folder')) };
    }, wbDashId);
    ok("LF66/LF59: a filed dashboard's list row shows a folder badge + a move-to-folder button",
      dfRow.badge === "Finance/2026" && dfRow.hasMove, JSON.stringify(dfRow));
    // cleanup: unfile the dashboard + restore tile view so later tests see the pre-existing state
    await page.evaluate(function (dashId) {
      var r = Studio.Workspace.get("dashboards", dashId); delete r.folder; Studio.Workspace.put("dashboards", r);
      window.__studioRenderDashboards();
    }, wbDashId);
    if (dfSwitched) { await page.evaluate(function () { var t = document.getElementById('dashViewToggle'); if (t) t.click(); }); }

    // ── LF66/LF59: the folder badge + move-to-folder ALSO live on the Dashboards TILE ──
    // The list row already carried a folder badge + move button; the tile now shows a persistent
    // folder chip (.recent-folder-chip) reading the folder name — or "Add to folder" when unfiled —
    // wired to the same shared .recent-folder move handler (the LF56 picker). Reuse, not new infra.
    console.log("\n• LF66/LF59: dashboard folder chip on the tile");
    const dfTileFlipped = await page.evaluate(function () {
      // ensure TILE view (the chip lives on the tile, not the list row); the toggle persists
      if (document.querySelector('#repoResults .dash-list')) { var t = document.getElementById('dashViewToggle'); if (t) { t.click(); return true; } }
      return false;
    });
    await page.waitForTimeout(60);
    const dfTileUnfiled = await page.evaluate(function (dashId) {
      var card = document.querySelector('#repoResults .recent-card [data-recent="' + dashId + '"]');
      var chip = document.querySelector('#repoResults .recent-folder-chip[data-folder="' + dashId + '"]');
      var nameEl = chip && chip.querySelector('.rf-name');
      return {
        hasCard: !!card, hasChip: !!chip, name: nameEl ? nameEl.textContent : null,
        filed: !!(chip && chip.classList.contains('filed')),
        moveHook: !!(chip && chip.classList.contains('recent-folder'))
      };
    }, wbDashId);
    ok("LF66/LF59: an unfiled dashboard tile shows an 'Add to folder' chip wired to the shared move handler",
      dfTileUnfiled.hasCard && dfTileUnfiled.hasChip && dfTileUnfiled.name === "Add to folder" && !dfTileUnfiled.filed && dfTileUnfiled.moveHook, JSON.stringify(dfTileUnfiled));
    await page.evaluate(function (dashId) {
      var r = Studio.Workspace.get("dashboards", dashId); r.folder = "Studio/2026"; Studio.Workspace.put("dashboards", r);
      window.__studioRenderDashboards();
    }, wbDashId);
    await page.waitForTimeout(60);
    const dfTileFiled = await page.evaluate(function (dashId) {
      var chip = document.querySelector('#repoResults .recent-folder-chip[data-folder="' + dashId + '"]');
      var nameEl = chip && chip.querySelector('.rf-name');
      return { name: nameEl ? nameEl.textContent : null, filed: !!(chip && chip.classList.contains('filed')) };
    }, wbDashId);
    ok("LF66/LF59: filing the dashboard updates its tile chip to the folder name with a filed state",
      dfTileFiled.name === "Studio/2026" && dfTileFiled.filed, JSON.stringify(dfTileFiled));
    // cleanup: unfile + restore prior view state so later tests see the pre-existing state
    await page.evaluate(function (dashId) {
      var r = Studio.Workspace.get("dashboards", dashId); delete r.folder; Studio.Workspace.put("dashboards", r);
      window.__studioRenderDashboards();
    }, wbDashId);
    if (dfTileFlipped) { await page.evaluate(function () { var t = document.getElementById('dashViewToggle'); if (t) t.click(); }); }

    // ── LF66: workbooks can ALSO be filed into a folder (Kevin's direction) ──
    // A workbook record gains an optional `folder`; each workbook chip gets a move-to-folder
    // button (LF56 picker) and shows an in-folder state. Folders and workbooks stay independent.
    console.log("\n• LF66: workbooks into folders");
    await page.evaluate(function () { window.__studioShellSetSection("dashboards"); window.__studioRenderDashboards(); });
    await page.waitForTimeout(60);
    const wbFolder = await page.evaluate(function () {
      var wb = window.__studioAddWorkbook("Filed WB");
      var okSet = window.__studioSetWorkbookFolder(wb.id, "Client/2026");
      window.__studioRenderDashboards();
      var stored = window.__studioWorkbooks().filter(function (w) { return w.id === wb.id; })[0];
      var btn = document.querySelector('#repoResults .wb-chip-folder[data-wb-folder="' + wb.id + '"]');
      var wrap = btn ? btn.closest(".wb-chip-wrap") : null;
      var res = { okSet: okSet, storedFolder: stored && stored.folder, hasBtn: !!btn, inFolder: !!(wrap && wrap.classList.contains("in-folder")) };
      window.__studioSetWorkbookFolder(wb.id, "");
      var stored2 = window.__studioWorkbooks().filter(function (w) { return w.id === wb.id; })[0];
      res.clearedFolder = !!(stored2 && stored2.folder);
      window.__studioDeleteWorkbook(wb.id);
      return res;
    });
    ok("LF66: a workbook files into a folder (persisted, folder button + in-folder state on its chip) and unfiles again",
      wbFolder.okSet && wbFolder.storedFolder === "Client/2026" && wbFolder.hasBtn && wbFolder.inFolder && !wbFolder.clearedFolder, JSON.stringify(wbFolder));

    await page.evaluate(function () { window.__studioShellSetSection("studio"); });
    await page.waitForTimeout(80);

    // ── N-DIST: shareable state links — encode the whole spec into a #share= link ──
    console.log("\n• N-DIST: shareable state links");
    const shareRoundTrip = await page.evaluate(function () {
      var spec = { id: "share-test", title: "Café Résumé 🚀", panels: [{ id: "p1", type: "bars" }], kpis: [], filters: [] };
      var enc = Studio.encodeSpecToShareString(spec);
      var dec = Studio.decodeSpecFromShareString(enc);
      var bad = Studio.decodeSpecFromShareString("not-valid-base64-!!!");
      return {
        roundTrips: !!dec && dec.title === spec.title && dec.panels.length === 1,
        badReturnsNull: bad === null,
        encIsUrlSafe: !/[^A-Za-z0-9._~%-]/.test(enc)
      };
    });
    ok("N-DIST: encodeSpecToShareString/decodeSpecFromShareString round-trip (incl. unicode/emoji) and reject garbage",
      shareRoundTrip.roundTrips && shareRoundTrip.badReturnsNull && shareRoundTrip.encIsUrlSafe, JSON.stringify(shareRoundTrip));

    await page.evaluate(() => { window.__studioSelectDashboard(); });
    await page.waitForTimeout(150);
    const shareUI = await page.evaluate(function () {
      var btns = Array.from(document.querySelectorAll("#inspBody .btn"));
      var shBtn = btns.find(function (b) { return /Copy shareable link/.test(b.textContent); });
      var heading = Array.from(document.querySelectorAll("#inspBody h4")).find(function (h) { return h.textContent === "Share this dashboard"; });
      return { hasBtn: !!shBtn, hasHeading: !!heading };
    });
    ok("N-DIST: Dashboard inspector shows a 'Share this dashboard' section with a Copy shareable link button",
      shareUI.hasBtn, JSON.stringify(shareUI));

    // Boot-time load: a fresh tab opened on a #share= link should reopen that exact dashboard
    // (not the default flagship example) and clear the hash so it can't re-trigger on reload.
    const shareBootSpec = await page.evaluate(function () {
      return Studio.encodeSpecToShareString({
        id: "shared-boot-test", name: "shared-boot-test", title: "Shared Boot Test Dashboard",
        panels: [], kpis: [], filters: [], cda: { connections: [], dataAccesses: [] }
      });
    });
    const sharePage = await browser.newPage();
    await sharePage.addInitScript(() => { try { sessionStorage.setItem("studio-gate-ok", "1"); localStorage.setItem("studio-welcome-seen", "1"); } catch (e) {} });
    await sharePage.goto(`http://localhost:${PORT}/app/#share=${shareBootSpec}`, { waitUntil: "networkidle" });
    await sharePage.waitForFunction(() => window.__STUDIO_STATE && window.__STUDIO_STATE.assets && window.__STUDIO_STATE.assets.js.length > 0, { timeout: 10000 });
    await sharePage.waitForTimeout(700);
    const shareBootResult = await sharePage.evaluate(function () {
      return { title: window.__STUDIO_STATE.spec.title, hash: location.hash };
    });
    await sharePage.close();
    ok("N-DIST: opening a #share= link boots straight into that exact dashboard and clears the hash",
      shareBootResult.title === "Shared Boot Test Dashboard" && shareBootResult.hash === "", JSON.stringify(shareBootResult));

    // ── N-DIST follow-up: diff-based "Share just my changes" link ──
    console.log("\n• N-DIST follow-up: diff-based share links");
    const sharePatchRoundTrip = await page.evaluate(function () {
      // Unchanged panels (p5..p20) stand in for a realistic dashboard's worth of untouched
      // content -- the point of a diff link is that they're never re-encoded at all, so the
      // patch should end up far smaller than the full spec even though only ONE thing changed.
      var untouched = []; for (var i = 5; i <= 20; i++) untouched.push({ id: "p" + i, title: "Untouched panel " + i, chart: { type: "bars", da: "da" + i }, note: "Some longer descriptive note text for panel " + i + " to bulk up its footprint." });
      var base = {
        id: "patch-test", title: "Base title", themeColor: "#111111",
        panels: [{ id: "p1", title: "Keep me", chart: { type: "bars" } }, { id: "p2", title: "Remove me", chart: { type: "bars" } }, { id: "p3", title: "Change me", chart: { type: "bars" } }].concat(untouched),
        filters: [{ id: "f1", label: "Region" }],
        kpis: [{ label: "Total", agg: "sum" }]
      };
      var cur = {
        id: "patch-test", title: "Edited title", themeColor: "#111111",
        panels: [{ id: "p1", title: "Keep me", chart: { type: "bars" } }, { id: "p3", title: "Changed!", chart: { type: "bars" } }, { id: "p4", title: "New panel", chart: { type: "line" } }].concat(untouched),
        filters: [{ id: "f1", label: "Región" }],
        kpis: [{ label: "Total", agg: "avg" }]
      };
      var patch = Studio.buildSharePatch(base, cur);
      var applied = Studio.applySharePatch(base, patch);
      var noopPatch = Studio.buildSharePatch(base, base);
      var noopApplied = Studio.applySharePatch(base, noopPatch);
      return {
        appliedMatchesCurrent: JSON.stringify(applied) === JSON.stringify(cur),
        patchOmitsUnchangedScalar: !("themeColor" in patch.fields),
        patchIsSmallerThanFullSpec: JSON.stringify(patch).length < JSON.stringify(cur).length,
        noopPatchIsNoop: JSON.stringify(noopApplied) === JSON.stringify(base)
      };
    });
    ok("N-DIST follow-up: buildSharePatch/applySharePatch round-trip (scalar/panel add+remove+change/filter change/kpi change), omit unchanged fields, and are a no-op against an identical spec",
      sharePatchRoundTrip.appliedMatchesCurrent && sharePatchRoundTrip.patchOmitsUnchangedScalar &&
      sharePatchRoundTrip.patchIsSmallerThanFullSpec && sharePatchRoundTrip.noopPatchIsNoop, JSON.stringify(sharePatchRoundTrip));

    const shareDiffUiFlow = await page.evaluate(function () {
      function hasBtn(label) { return !!Array.from(document.querySelectorAll("#inspBody .btn")).find(function (b) { return new RegExp(label).test(b.textContent); }); }
      var spec = window.__STUDIO_STATE.spec;
      // Start clean: no share-base recorded yet for this dashboard id.
      var all = {}; try { all = JSON.parse(localStorage.getItem("studio-share-base") || "{}"); } catch (e) {}
      delete all[spec.id];
      try { localStorage.setItem("studio-share-base", JSON.stringify(all)); } catch (e) {}
      window.__studioSelectDashboard();
      var noBase = hasBtn("Share just my changes");
      var fullBtn = Array.from(document.querySelectorAll("#inspBody .btn")).find(function (b) { return /Copy shareable link/.test(b.textContent); });
      fullBtn.click(); // sets the share-base to the CURRENT (unchanged) spec
      window.__studioSelectDashboard();
      var rightAfterFullShare = hasBtn("Share just my changes"); // no diff yet -> still hidden
      spec.title = spec.title + " (edited for test)";
      window.__studioSelectDashboard();
      var afterEdit = hasBtn("Share just my changes"); // now differs from the stored base -> shown
      var diffBtn = Array.from(document.querySelectorAll("#inspBody .btn")).find(function (b) { return /Share just my changes/.test(b.textContent); });
      diffBtn.click(); // exercises the click handler end to end (clipboard write may reject headless; caught either way)
      window.__studioSelectDashboard();
      var afterSecondShare = hasBtn("Share just my changes"); // base just moved to current again -> hidden once more
      return { noBase: noBase, rightAfterFullShare: rightAfterFullShare, afterEdit: afterEdit, afterSecondShare: afterSecondShare };
    });
    ok("N-DIST follow-up: 'Share just my changes' stays hidden with no base or no diff yet, appears once the spec diverges from the last shared base, and hides again once a new link is copied",
      shareDiffUiFlow.noBase === false && shareDiffUiFlow.rightAfterFullShare === false &&
      shareDiffUiFlow.afterEdit === true && shareDiffUiFlow.afterSecondShare === false, JSON.stringify(shareDiffUiFlow));

    // Boot-time: a diff link only resolves when THIS browser already has a base for that
    // dashboard id (Studio.getShareBase) -- the realistic "recipient already has it" case.
    const diffBootWithBase = await page.evaluate(function () {
      var base = { id: "diff-boot-test", name: "diff-boot-test", title: "Diff Boot Base", panels: [], kpis: [], filters: [], cda: { connections: [], dataAccesses: [] } };
      var cur = { id: "diff-boot-test", name: "diff-boot-test", title: "Diff Boot Updated", panels: [], kpis: [], filters: [], cda: { connections: [], dataAccesses: [] } };
      var patch = Studio.buildSharePatch(base, cur);
      return { base: base, enc: Studio.encodeSpecToShareString({ __shareDiff: true, id: "diff-boot-test", patch: patch }) };
    });
    const diffPageWithBase = await browser.newPage();
    await diffPageWithBase.addInitScript((base) => {
      try {
        sessionStorage.setItem("studio-gate-ok", "1"); localStorage.setItem("studio-welcome-seen", "1");
        localStorage.setItem("studio-share-base", JSON.stringify({ "diff-boot-test": base }));
      } catch (e) {}
    }, diffBootWithBase.base);
    await diffPageWithBase.goto(`http://localhost:${PORT}/app/#share=${diffBootWithBase.enc}`, { waitUntil: "networkidle" });
    await diffPageWithBase.waitForFunction(() => window.__STUDIO_STATE && window.__STUDIO_STATE.assets && window.__STUDIO_STATE.assets.js.length > 0, { timeout: 10000 });
    await diffPageWithBase.waitForTimeout(700);
    const diffBootWithBaseResult = await diffPageWithBase.evaluate(function () {
      return { title: window.__STUDIO_STATE.spec.title, hash: location.hash };
    });
    await diffPageWithBase.close();
    ok("N-DIST follow-up: opening a diff share link with a matching local base applies the patch and boots straight into the updated dashboard",
      diffBootWithBaseResult.title === "Diff Boot Updated" && diffBootWithBaseResult.hash === "", JSON.stringify(diffBootWithBaseResult));

    // Boot-time: no matching base locally (the recipient never opened the original full link) --
    // must fall through to the normal boot flow (never crash), not silently do nothing.
    const diffPageNoBase = await browser.newPage();
    const noBasePageErrors = [];
    diffPageNoBase.on("pageerror", function (e) { noBasePageErrors.push(String(e)); });
    await diffPageNoBase.addInitScript(() => { try { sessionStorage.setItem("studio-gate-ok", "1"); localStorage.setItem("studio-welcome-seen", "1"); } catch (e) {} });
    await diffPageNoBase.goto(`http://localhost:${PORT}/app/#share=${diffBootWithBase.enc}`, { waitUntil: "networkidle" });
    await diffPageNoBase.waitForFunction(() => window.__STUDIO_STATE && window.__STUDIO_STATE.assets && window.__STUDIO_STATE.assets.js.length > 0, { timeout: 10000 });
    await diffPageNoBase.waitForTimeout(700);
    const diffBootNoBaseResult = await diffPageNoBase.evaluate(function () {
      return { title: window.__STUDIO_STATE.spec.title, hash: location.hash, toastText: (document.getElementById("toast") || {}).textContent || "" };
    });
    await diffPageNoBase.close();
    ok("N-DIST follow-up: opening a diff share link with NO matching local base falls through to the normal boot (default dashboard, no crash) and surfaces an explanatory toast",
      diffBootNoBaseResult.title !== "Diff Boot Updated" && diffBootNoBaseResult.hash === "" &&
      /open the original/i.test(diffBootNoBaseResult.toastText) && noBasePageErrors.length === 0,
      JSON.stringify(diffBootNoBaseResult) + " errors=" + JSON.stringify(noBasePageErrors));

    // ── N-DIST: "Import from URL" — a zero-backend community-template exchange ──
    // Stubs window.fetch (no real internet route in this sandbox) so this exercises the
    // whole modal → fetchJSON → normalize → load wiring, not just the fetch call itself.
    console.log("\n• N-DIST: Import dashboard from URL");
    const importOk = await page.evaluate(function () {
      var origFetch = window.fetch;
      window.fetch = function () {
        return Promise.resolve({ ok: true, json: function () {
          return Promise.resolve({ id: "imp1", name: "imported-test", title: "Imported From URL Test", panels: [], kpis: [], filters: [], cda: { connections: [], dataAccesses: [] } });
        } });
      };
      window.__studioImportFromUrl();
      var inp = document.getElementById("importUrlInput");
      inp.value = "https://example.com/dash.studio.json";
      document.getElementById("importUrlGo").click();
      return new Promise(function (resolve) {
        setTimeout(function () {
          window.fetch = origFetch;
          resolve({ modalGone: !document.querySelector(".modal-ov"), title: window.__STUDIO_STATE.spec.title });
        }, 120);
      });
    });
    ok("N-DIST: Import from URL fetches, normalizes, and loads a valid .studio.json spec, then closes the modal",
      importOk.modalGone && importOk.title === "Imported From URL Test", JSON.stringify(importOk));

    const importFail = await page.evaluate(function () {
      var origFetch = window.fetch;
      window.fetch = function () { return Promise.resolve({ ok: false, status: 404, json: function () { return Promise.reject(new Error("no body")); } }); };
      window.__studioImportFromUrl();
      var inp = document.getElementById("importUrlInput");
      inp.value = "https://example.com/missing.studio.json";
      document.getElementById("importUrlGo").click();
      return new Promise(function (resolve) {
        setTimeout(function () {
          window.fetch = origFetch;
          var status = document.getElementById("importUrlStatus");
          var ov = document.querySelector(".modal-ov");
          if (ov) ov.remove();
          resolve({ modalStillOpen: !!ov, statusText: status ? status.textContent : "" });
        }, 120);
      });
    });
    ok("N-DIST: Import from URL surfaces a clear inline error on a failed fetch instead of hanging/crashing",
      importFail.modalStillOpen && /couldn.t import/i.test(importFail.statusText), JSON.stringify(importFail));

    // ── N-DIST follow-up: "index of several" — one URL can list many templates ──
    console.log("\n• N-DIST follow-up: Import from URL — index of several templates");
    const importIndex = await page.evaluate(function () {
      var origFetch = window.fetch;
      window.fetch = function (url) {
        if (/index\.json/.test(url)) {
          return Promise.resolve({ ok: true, json: function () {
            return Promise.resolve({ templates: [
              { title: "Sales Overview", url: "https://example.com/templates/sales.studio.json", description: "Quarterly sales KPIs" },
              { title: "Ops Health", url: "https://example.com/templates/ops.studio.json" }
            ] });
          } });
        }
        return Promise.resolve({ ok: true, json: function () {
          return Promise.resolve({ id: "imp2", name: "sales-tpl", title: "Sales Overview Loaded", panels: [], kpis: [], filters: [], cda: { connections: [], dataAccesses: [] } });
        } });
      };
      window.__studioImportFromUrl();
      var inp = document.getElementById("importUrlInput");
      inp.value = "https://example.com/templates/index.json";
      document.getElementById("importUrlGo").click();
      return new Promise(function (resolve) {
        setTimeout(function () {
          var items = [].slice.call(document.querySelectorAll("#importUrlList .row-item"));
          var titles = items.map(function (r) { return r.querySelector(".ri-t").textContent; });
          items[0].click();
          setTimeout(function () {
            window.fetch = origFetch;
            resolve({
              listedTitles: titles,
              modalGone: !document.querySelector(".modal-ov"),
              loadedTitle: window.__STUDIO_STATE.spec.title
            });
          }, 120);
        }, 120);
      });
    });
    ok("N-DIST: an index.json URL (array or {templates:[]}) renders a browsable list of templates",
      importIndex.listedTitles.length === 2 && importIndex.listedTitles[0] === "Sales Overview" && importIndex.listedTitles[1] === "Ops Health",
      JSON.stringify(importIndex));
    ok("N-DIST: picking a template from the index fetches its own URL and imports it",
      importIndex.modalGone && importIndex.loadedTitle === "Sales Overview Loaded", JSON.stringify(importIndex));

    const importIndexArray = await page.evaluate(function () {
      var origFetch = window.fetch;
      window.fetch = function (url) {
        if (/list\.json/.test(url)) {
          return Promise.resolve({ ok: true, json: function () {
            return Promise.resolve([{ title: "Bare Array Template", file: "tpl.studio.json" }]);
          } });
        }
        return Promise.resolve({ ok: true, json: function () {
          return Promise.resolve({ id: "imp3", name: "bare-tpl", title: "Bare Array Loaded", panels: [], kpis: [], filters: [], cda: { connections: [], dataAccesses: [] } });
        } });
      };
      window.__studioImportFromUrl();
      var inp = document.getElementById("importUrlInput");
      inp.value = "https://example.com/templates/list.json";
      document.getElementById("importUrlGo").click();
      return new Promise(function (resolve) {
        setTimeout(function () {
          var item = document.querySelector("#importUrlList .row-item");
          var hadItem = !!item;
          if (item) item.click();
          setTimeout(function () {
            window.fetch = origFetch;
            resolve({ hadItem: hadItem, loadedTitle: window.__STUDIO_STATE.spec.title });
          }, 120);
        }, 120);
      });
    });
    ok("N-DIST: a bare JSON array index also works, resolving a relative 'file' key against the index URL",
      importIndexArray.hadItem && importIndexArray.loadedTitle === "Bare Array Loaded", JSON.stringify(importIndexArray));

    // ── N-DIST follow-up: local version history ("time travel" for a dashboard) ──
    console.log("\n• N-DIST follow-up: local version history");
    const vhId = "vh-test-9f3";
    await page.evaluate(function (id) {
      // seed an "orphan" version entry for a dashboard id that is NOT in studio-recents,
      // to prove pruneVersions() cleans it up once recents settle again.
      var versions = {}; try { versions = JSON.parse(localStorage.getItem("studio-versions") || "{}"); } catch (e) {}
      versions["vh-orphan-xyz"] = [{ ts: new Date().toISOString(), spec: { id: "vh-orphan-xyz", title: "Orphan" } }];
      delete versions[id];
      localStorage.setItem("studio-versions", JSON.stringify(versions));
      window.__studioLoad({ id: id, name: id, title: "VH Original Title", panels: [], kpis: [], filters: [], cda: { connections: [], dataAccesses: [] } });
    }, vhId);
    await page.waitForTimeout(120);

    const vhBasic = await page.evaluate(function (id) {
      var before = (window.__studioVersions()[id] || []).length;
      window.__studioSnapshotVersion(); // simulates hitting Save once
      var afterOne = (window.__studioVersions()[id] || []).length;
      window.__studioSnapshotVersion(); // simulates hitting Save a second time
      var list = window.__studioVersions()[id] || [];
      return { before: before, afterOne: afterOne, afterTwo: list.length, newestFirst: list.length === 2 && list[0].ts >= list[1].ts, hasSpec: !!(list[0] && list[0].spec && list[0].spec.title === "VH Original Title") };
    }, vhId);
    ok("N-DIST: snapshotVersion() appends a newest-first checkpoint to studio-versions keyed by dashboard id",
      vhBasic.before === 0 && vhBasic.afterOne === 1 && vhBasic.afterTwo === 2 && vhBasic.newestFirst && vhBasic.hasSpec, JSON.stringify(vhBasic));

    await page.evaluate(function () { window.__studioSelectDashboard(); });
    await page.waitForTimeout(150);
    const vhUI = await page.evaluate(function () {
      var heading = Array.from(document.querySelectorAll("#inspBody h4")).find(function (h) { return /^Version history/.test(h.textContent); });
      var rows = document.querySelectorAll("#inspBody .row-item .ri-icon");
      var vhRows = Array.from(rows).filter(function (r) { return r.textContent.indexOf("↺") >= 0; });
      return { hasHeading: !!heading, headingText: heading ? heading.textContent : "", rowCount: vhRows.length };
    });
    ok("N-DIST: Dashboard inspector shows a 'Version history (2)' section listing both checkpoints",
      vhUI.hasHeading && /\(2\)/.test(vhUI.headingText) && vhUI.rowCount === 2, JSON.stringify(vhUI));

    // Simulate an unsaved edit, then restore the earlier version — the edit should be
    // discarded and a fresh checkpoint of the *restored* state appended (restoring is
    // itself undoable, same "time travel" convention as Google Docs / git checkout).
    page.once("dialog", (d) => d.accept());
    const vhRestore = await page.evaluate(function (id) {
      window.__STUDIO_STATE.spec.title = "An unsaved in-progress edit";
      var target = window.__studioVersions()[id][1]; // the OLDER of the two identical snapshots
      window.__studioRestoreVersion(target.ts);
      return { titleAfterRestore: window.__STUDIO_STATE.spec.title, versionCountAfterRestore: (window.__studioVersions()[id] || []).length };
    }, vhId);
    ok("N-DIST: restoring a version discards the unsaved edit and replaces the working spec",
      vhRestore.titleAfterRestore === "VH Original Title", JSON.stringify(vhRestore));
    ok("N-DIST: restoring a version itself pushes a new checkpoint (a restore can be undone too)",
      vhRestore.versionCountAfterRestore === 3, JSON.stringify(vhRestore));

    // The debounced noteRecent() (fired ~800ms after any edit settles, via refreshPreview())
    // prunes studio-versions down to only dashboards still tracked in studio-recents. Margin
    // padded well past the 800ms debounce to absorb event-loop scheduling jitter under load.
    await page.waitForTimeout(1800);
    const vhPrune = await page.evaluate(function (id) {
      var versions = window.__studioVersions();
      return { orphanGone: !versions["vh-orphan-xyz"], targetKept: (versions[id] || []).length > 0 };
    }, vhId);
    ok("N-DIST: pruneVersions() removes version history for dashboards no longer in studio-recents, keeping the active one",
      vhPrune.orphanGone && vhPrune.targetKept, JSON.stringify(vhPrune));

    // ── N-DIST follow-up: version-history visual diff (Compare to current) ──
    console.log("\n• N-DIST follow-up: version-history diff");
    const diffPure = await page.evaluate(function () {
      var a = { title: "Old title", panels: [{ id: "p1", title: "Revenue" }, { id: "p2", title: "Costs" }], kpis: [{ label: "K1" }], filters: [{ id: "f1", label: "Region" }] };
      var b = { title: "New title", panels: [{ id: "p1", title: "Revenue (renamed)" }, { id: "p3", title: "New panel" }], kpis: [{ label: "K1" }, { label: "K2" }], filters: [] };
      var d = Studio.diffSpecs(a, b);
      var summary = Studio.diffSummary(d);
      var identical = Studio.diffSummary(Studio.diffSpecs(a, a));
      return {
        titleField: d.fields.some(function (f) { return f.key === "title" && f.from === "Old title" && f.to === "New title"; }),
        panelAdded: d.panels.added.indexOf("New panel") >= 0,
        panelRemoved: d.panels.removed.indexOf("Costs") >= 0,
        panelChanged: d.panels.changed.indexOf("Revenue (renamed)") >= 0,
        kpiAdded: d.kpis.added === 1,
        filterRemoved: d.filters.removed.indexOf("Region") >= 0,
        summaryLen: summary.length,
        identicalLen: identical.length
      };
    });
    ok("Studio.diffSpecs detects a changed scalar field (title)", diffPure.titleField, JSON.stringify(diffPure));
    ok("Studio.diffSpecs detects an added + a removed + a changed panel (matched by id)",
      diffPure.panelAdded && diffPure.panelRemoved && diffPure.panelChanged, JSON.stringify(diffPure));
    ok("Studio.diffSpecs counts an added KPI (positional) and a removed filter (matched by id)",
      diffPure.kpiAdded && diffPure.filterRemoved, JSON.stringify(diffPure));
    ok("Studio.diffSummary renders lines for a real diff, and none for two identical specs",
      diffPure.summaryLen > 0 && diffPure.identicalLen === 0, JSON.stringify(diffPure));

    // Live UI: open the Compare modal on the earlier checkpoint (title differs from the
    // now-current "VH Original Title" restored state) and confirm it surfaces a real diff.
    const vhDiffUI = await page.evaluate(function (id) {
      window.__STUDIO_STATE.spec.title = "A brand-new unsaved title";
      var list = window.__studioVersions()[id] || [];
      window.__studioOpenVersionDiff(list[list.length - 1]); // oldest checkpoint vs. current
      var modal = document.querySelector(".modal-ov .modal");
      var rows = modal ? Array.from(modal.querySelectorAll(".vdiff-row")).map(function (r) { return r.textContent; }) : [];
      var hasRestoreBtn = !!(modal && Array.from(modal.querySelectorAll("button")).find(function (b) { return /Restore this version/.test(b.textContent); }));
      return { hasModal: !!modal, rowCount: rows.length, mentionsTitle: rows.some(function (r) { return /Title:/.test(r); }), hasRestoreBtn: hasRestoreBtn };
    }, vhId);
    ok("N-DIST: Compare-to-current modal opens and lists the Title field change",
      vhDiffUI.hasModal && vhDiffUI.rowCount > 0 && vhDiffUI.mentionsTitle, JSON.stringify(vhDiffUI));
    ok("N-DIST: Compare modal offers a 'Restore this version' action", vhDiffUI.hasRestoreBtn, JSON.stringify(vhDiffUI));
    await page.evaluate(function () { var ov = document.querySelector(".modal-ov"); if (ov) ov.remove(); });

    // ── Track N innovation idea (added 2026-07-04): canvas sticky notes ──
